   end subroutine cfc_nuclear_eval

   pure module subroutine cfc_hessian_eval(pd0, pd1_r, pd2_rr, qa0, qa1_r, qa2_rr, qb0, qb1_r, qb2_rr, &
                                    qq0, qq1_r, qq2_rr, max_deriv, f2_rArB, f3_r_rArB, f4_rr_rArB)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qa0(3)
      !> Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qa1_r(3, 3)
      !> Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qa2_rr(3, 3, 3)
      !> Atom-B d/dR_B of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qb0(3)
      !> Atom-B d/dR_B of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qb1_r(3, 3)
      !> Atom-B d/dR_B of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qb2_rr(3, 3, 3)
      !> d2/(dR_A dR_B) of the order-0 spatial derivative of PD; the two trailing indices are the
      !> nuclear components of A and B
      real(wp), intent(in) :: qq0(3, 3)
      !> d2/(dR_A dR_B) of the order-1 spatial derivative of PD; the two trailing indices are the
      !> nuclear components of A and B
      real(wp), intent(in) :: qq1_r(3, 3, 3)
      !> d2/(dR_A dR_B) of the order-2 spatial derivative of PD; the two trailing indices are the
      !> nuclear components of A and B
      real(wp), intent(in) :: qq2_rr(3, 3, 3, 3)
      !> Highest spatial-derivative order to lift (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dR_A dR_B) of the order-0 spatial derivative of the level set; the two trailing indices
      !> are the nuclear components of A and B
      real(wp), intent(out) :: f2_rArB(3, 3)
      !> d2/(dR_A dR_B) of the order-1 spatial derivative of the level set; the two trailing indices
      !> are the nuclear components of A and B
      real(wp), intent(out) :: f3_r_rArB(3, 3, 3)
      !> d2/(dR_A dR_B) of the order-2 spatial derivative of the level set; the two trailing indices
      !> are the nuclear components of A and B
      real(wp), intent(out) :: f4_rr_rArB(3, 3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      f2_rArB = 0.0_wp
      f3_r_rArB = 0.0_wp
      f4_rr_rArB = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3

            x0 = (inv_pd*inv_pd)
            x1 = qa0(1)*x0
            x2 = qa0(2)*x0
            x3 = qa0(3)*x0
            f2_rArB(1, 1) = -inv_pd*qq0(1, 1) + qb0(1)*x1
            f2_rArB(1, 2) = -inv_pd*qq0(1, 2) + qb0(2)*x1
            f2_rArB(1, 3) = -inv_pd*qq0(1, 3) + qb0(3)*x1
            f2_rArB(2, 1) = -inv_pd*qq0(2, 1) + qb0(1)*x2
            f2_rArB(2, 2) = -inv_pd*qq0(2, 2) + qb0(2)*x2
            f2_rArB(2, 3) = -inv_pd*qq0(2, 3) + qb0(3)*x2
            f2_rArB(3, 1) = -inv_pd*qq0(3, 1) + qb0(1)*x3
            f2_rArB(3, 2) = -inv_pd*qq0(3, 2) + qb0(2)*x3
            f2_rArB(3, 3) = -inv_pd*qq0(3, 3) + qb0(3)*x3
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19

            x0 = (inv_pd*inv_pd)
            x1 = qa0(1)*x0
            x2 = qa0(2)*x0
            x3 = qa0(3)*x0
            x4 = pd1_r(1)*x0
            x5 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
            x6 = pd1_r(1)*x5
            x7 = -qa0(1)*x6 + qa1_r(1, 1)*x0
            x8 = -qa0(2)*x6 + qa1_r(1, 2)*x0
            x9 = -qa0(3)*x6 + qa1_r(1, 3)*x0
            x10 = pd1_r(2)*x0
            x11 = pd1_r(2)*x5
            x12 = -qa0(1)*x11 + qa1_r(2, 1)*x0
            x13 = -qa0(2)*x11 + qa1_r(2, 2)*x0
            x14 = -qa0(3)*x11 + qa1_r(2, 3)*x0
            x15 = pd1_r(3)*x0
            x16 = pd1_r(3)*x5
            x17 = -qa0(1)*x16 + qa1_r(3, 1)*x0
            x18 = -qa0(2)*x16 + qa1_r(3, 2)*x0
            x19 = -qa0(3)*x16 + qa1_r(3, 3)*x0
            f2_rArB(1, 1) = -inv_pd*qq0(1, 1) + qb0(1)*x1
            f2_rArB(1, 2) = -inv_pd*qq0(1, 2) + qb0(2)*x1
            f2_rArB(1, 3) = -inv_pd*qq0(1, 3) + qb0(3)*x1
            f2_rArB(2, 1) = -inv_pd*qq0(2, 1) + qb0(1)*x2
            f2_rArB(2, 2) = -inv_pd*qq0(2, 2) + qb0(2)*x2
            f2_rArB(2, 3) = -inv_pd*qq0(2, 3) + qb0(3)*x2
            f2_rArB(3, 1) = -inv_pd*qq0(3, 1) + qb0(1)*x3
            f2_rArB(3, 2) = -inv_pd*qq0(3, 2) + qb0(2)*x3
            f2_rArB(3, 3) = -inv_pd*qq0(3, 3) + qb0(3)*x3
            f3_r_rArB(1, 1, 1) = -inv_pd*qq1_r(1, 1, 1) + qb0(1)*x7 + qb1_r(1, 1)*x1 + qq0(1, 1)*x4
            f3_r_rArB(1, 1, 2) = -inv_pd*qq1_r(1, 1, 2) + qb0(2)*x7 + qb1_r(1, 2)*x1 + qq0(1, 2)*x4
            f3_r_rArB(1, 1, 3) = -inv_pd*qq1_r(1, 1, 3) + qb0(3)*x7 + qb1_r(1, 3)*x1 + qq0(1, 3)*x4
            f3_r_rArB(1, 2, 1) = -inv_pd*qq1_r(1, 2, 1) + qb0(1)*x8 + qb1_r(1, 1)*x2 + qq0(2, 1)*x4
            f3_r_rArB(1, 2, 2) = -inv_pd*qq1_r(1, 2, 2) + qb0(2)*x8 + qb1_r(1, 2)*x2 + qq0(2, 2)*x4
            f3_r_rArB(1, 2, 3) = -inv_pd*qq1_r(1, 2, 3) + qb0(3)*x8 + qb1_r(1, 3)*x2 + qq0(2, 3)*x4
            f3_r_rArB(1, 3, 1) = -inv_pd*qq1_r(1, 3, 1) + qb0(1)*x9 + qb1_r(1, 1)*x3 + qq0(3, 1)*x4
            f3_r_rArB(1, 3, 2) = -inv_pd*qq1_r(1, 3, 2) + qb0(2)*x9 + qb1_r(1, 2)*x3 + qq0(3, 2)*x4
            f3_r_rArB(1, 3, 3) = -inv_pd*qq1_r(1, 3, 3) + qb0(3)*x9 + qb1_r(1, 3)*x3 + qq0(3, 3)*x4
            f3_r_rArB(2, 1, 1) = &
               -inv_pd*qq1_r(2, 1, 1) + qb0(1)*x12 + qb1_r(2, 1)*x1 + qq0(1, 1)*x10
            f3_r_rArB(2, 1, 2) = &
               -inv_pd*qq1_r(2, 1, 2) + qb0(2)*x12 + qb1_r(2, 2)*x1 + qq0(1, 2)*x10
            f3_r_rArB(2, 1, 3) = &
               -inv_pd*qq1_r(2, 1, 3) + qb0(3)*x12 + qb1_r(2, 3)*x1 + qq0(1, 3)*x10
            f3_r_rArB(2, 2, 1) = &
               -inv_pd*qq1_r(2, 2, 1) + qb0(1)*x13 + qb1_r(2, 1)*x2 + qq0(2, 1)*x10
            f3_r_rArB(2, 2, 2) = &
               -inv_pd*qq1_r(2, 2, 2) + qb0(2)*x13 + qb1_r(2, 2)*x2 + qq0(2, 2)*x10
            f3_r_rArB(2, 2, 3) = &
               -inv_pd*qq1_r(2, 2, 3) + qb0(3)*x13 + qb1_r(2, 3)*x2 + qq0(2, 3)*x10
            f3_r_rArB(2, 3, 1) = &
               -inv_pd*qq1_r(2, 3, 1) + qb0(1)*x14 + qb1_r(2, 1)*x3 + qq0(3, 1)*x10
            f3_r_rArB(2, 3, 2) = &
               -inv_pd*qq1_r(2, 3, 2) + qb0(2)*x14 + qb1_r(2, 2)*x3 + qq0(3, 2)*x10
            f3_r_rArB(2, 3, 3) = &
               -inv_pd*qq1_r(2, 3, 3) + qb0(3)*x14 + qb1_r(2, 3)*x3 + qq0(3, 3)*x10
            f3_r_rArB(3, 1, 1) = &
               -inv_pd*qq1_r(3, 1, 1) + qb0(1)*x17 + qb1_r(3, 1)*x1 + qq0(1, 1)*x15
            f3_r_rArB(3, 1, 2) = &
               -inv_pd*qq1_r(3, 1, 2) + qb0(2)*x17 + qb1_r(3, 2)*x1 + qq0(1, 2)*x15
            f3_r_rArB(3, 1, 3) = &
               -inv_pd*qq1_r(3, 1, 3) + qb0(3)*x17 + qb1_r(3, 3)*x1 + qq0(1, 3)*x15
            f3_r_rArB(3, 2, 1) = &
               -inv_pd*qq1_r(3, 2, 1) + qb0(1)*x18 + qb1_r(3, 1)*x2 + qq0(2, 1)*x15
            f3_r_rArB(3, 2, 2) = &
               -inv_pd*qq1_r(3, 2, 2) + qb0(2)*x18 + qb1_r(3, 2)*x2 + qq0(2, 2)*x15
            f3_r_rArB(3, 2, 3) = &
               -inv_pd*qq1_r(3, 2, 3) + qb0(3)*x18 + qb1_r(3, 3)*x2 + qq0(2, 3)*x15
            f3_r_rArB(3, 3, 1) = &
               -inv_pd*qq1_r(3, 3, 1) + qb0(1)*x19 + qb1_r(3, 1)*x3 + qq0(3, 1)*x15
            f3_r_rArB(3, 3, 2) = &
               -inv_pd*qq1_r(3, 3, 2) + qb0(2)*x19 + qb1_r(3, 2)*x3 + qq0(3, 2)*x15
            f3_r_rArB(3, 3, 3) = &
               -inv_pd*qq1_r(3, 3, 3) + qb0(3)*x19 + qb1_r(3, 3)*x3 + qq0(3, 3)*x15
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, t_f4_rr_rArB_0100
            real(wp) :: t_f4_rr_rArB_0101, t_f4_rr_rArB_0102, t_f4_rr_rArB_0110, t_f4_rr_rArB_0111
            real(wp) :: t_f4_rr_rArB_0112, t_f4_rr_rArB_0120, t_f4_rr_rArB_0121, t_f4_rr_rArB_0122
            real(wp) :: t_f4_rr_rArB_0200, t_f4_rr_rArB_0201, t_f4_rr_rArB_0202, t_f4_rr_rArB_0210
            real(wp) :: t_f4_rr_rArB_0211, t_f4_rr_rArB_0212, t_f4_rr_rArB_0220, t_f4_rr_rArB_0221
            real(wp) :: t_f4_rr_rArB_0222, t_f4_rr_rArB_1200, t_f4_rr_rArB_1201, t_f4_rr_rArB_1202
            real(wp) :: t_f4_rr_rArB_1210, t_f4_rr_rArB_1211, t_f4_rr_rArB_1212, t_f4_rr_rArB_1220
            real(wp) :: t_f4_rr_rArB_1221, t_f4_rr_rArB_1222

            x0 = (inv_pd*inv_pd)
            x1 = qa0(1)*x0
            x2 = qa0(2)*x0
            x3 = qa0(3)*x0
            x4 = pd1_r(1)*x0
            x5 = (inv_pd*inv_pd*inv_pd)
            x6 = 2.0_wp*x5
            x7 = pd1_r(1)*x6
            x8 = -qa0(1)*x7 + qa1_r(1, 1)*x0
            x9 = -qa0(2)*x7 + qa1_r(1, 2)*x0
            x10 = -qa0(3)*x7 + qa1_r(1, 3)*x0
            x11 = pd1_r(2)*x0
            x12 = pd1_r(2)*x6
            x13 = -qa0(1)*x12 + qa1_r(2, 1)*x0
            x14 = -qa0(2)*x12 + qa1_r(2, 2)*x0
            x15 = -qa0(3)*x12 + qa1_r(2, 3)*x0
            x16 = pd1_r(3)*x0
            x17 = pd1_r(3)*x6
            x18 = -qa0(1)*x17 + qa1_r(3, 1)*x0
            x19 = -qa0(2)*x17 + qa1_r(3, 2)*x0
            x20 = -qa0(3)*x17 + qa1_r(3, 3)*x0
            x21 = 2.0_wp*x4
            x22 = 4.0_wp*x5
            x23 = pd1_r(1)*x22
            x24 = -qa0(1)*x23 + 2.0_wp*qa1_r(1, 1)*x0
            x25 = (pd1_r(1)*pd1_r(1))
            x26 = pd2_rr(1, 1)*x0 - x25*x6
            x27 = 6.0_wp*(inv_pd*inv_pd*inv_pd*inv_pd)
            x28 = -pd2_rr(1, 1)*x6 + x25*x27
            x29 = qa0(1)*x28 - qa1_r(1, 1)*x23 + qa2_rr(1, 1, 1)*x0
            x30 = -qa0(2)*x23 + 2.0_wp*qa1_r(1, 2)*x0
            x31 = qa0(2)*x28 - qa1_r(1, 2)*x23 + qa2_rr(1, 1, 2)*x0
            x32 = -qa0(3)*x23 + 2.0_wp*qa1_r(1, 3)*x0
            x33 = qa0(3)*x28 - qa1_r(1, 3)*x23 + qa2_rr(1, 1, 3)*x0
            x34 = -pd1_r(2)*x7 + pd2_rr(1, 2)*x0
            x35 = pd1_r(1)*x27
            x36 = pd1_r(2)*x35 - pd2_rr(1, 2)*x6
            x37 = qa0(1)*x36 - qa1_r(1, 1)*x12 - qa1_r(2, 1)*x7 + qa2_rr(1, 2, 1)*x0
            x38 = qa0(2)*x36 - qa1_r(1, 2)*x12 - qa1_r(2, 2)*x7 + qa2_rr(1, 2, 2)*x0
            x39 = qa0(3)*x36 - qa1_r(1, 3)*x12 - qa1_r(2, 3)*x7 + qa2_rr(1, 2, 3)*x0
            x40 = -pd1_r(3)*x7 + pd2_rr(1, 3)*x0
            x41 = pd1_r(3)*x35 - pd2_rr(1, 3)*x6
            x42 = qa0(1)*x41 - qa1_r(1, 1)*x17 - qa1_r(3, 1)*x7 + qa2_rr(1, 3, 1)*x0
            x43 = qa0(2)*x41 - qa1_r(1, 2)*x17 - qa1_r(3, 2)*x7 + qa2_rr(1, 3, 2)*x0
            x44 = qa0(3)*x41 - qa1_r(1, 3)*x17 - qa1_r(3, 3)*x7 + qa2_rr(1, 3, 3)*x0
            x45 = 2.0_wp*x11
            x46 = pd1_r(2)*x22
            x47 = -qa0(1)*x46 + 2.0_wp*qa1_r(2, 1)*x0
            x48 = (pd1_r(2)*pd1_r(2))
            x49 = pd2_rr(2, 2)*x0 - x48*x6
            x50 = -pd2_rr(2, 2)*x6 + x27*x48
            x51 = qa0(1)*x50 - qa1_r(2, 1)*x46 + qa2_rr(2, 2, 1)*x0
            x52 = -qa0(2)*x46 + 2.0_wp*qa1_r(2, 2)*x0
            x53 = qa0(2)*x50 - qa1_r(2, 2)*x46 + qa2_rr(2, 2, 2)*x0
            x54 = -qa0(3)*x46 + 2.0_wp*qa1_r(2, 3)*x0
            x55 = qa0(3)*x50 - qa1_r(2, 3)*x46 + qa2_rr(2, 2, 3)*x0
            x56 = -pd1_r(3)*x12 + pd2_rr(2, 3)*x0
            x57 = pd1_r(2)*pd1_r(3)*x27 - pd2_rr(2, 3)*x6
            x58 = qa0(1)*x57 - qa1_r(2, 1)*x17 - qa1_r(3, 1)*x12 + qa2_rr(2, 3, 1)*x0
            x59 = qa0(2)*x57 - qa1_r(2, 2)*x17 - qa1_r(3, 2)*x12 + qa2_rr(2, 3, 2)*x0
            x60 = qa0(3)*x57 - qa1_r(2, 3)*x17 - qa1_r(3, 3)*x12 + qa2_rr(2, 3, 3)*x0
            x61 = 2.0_wp*x16
            x62 = pd1_r(3)*x22
            x63 = -qa0(1)*x62 + 2.0_wp*qa1_r(3, 1)*x0
            x64 = (pd1_r(3)*pd1_r(3))
            x65 = pd2_rr(3, 3)*x0 - x6*x64
            x66 = -pd2_rr(3, 3)*x6 + x27*x64
            x67 = qa0(1)*x66 - qa1_r(3, 1)*x62 + qa2_rr(3, 3, 1)*x0
            x68 = -qa0(2)*x62 + 2.0_wp*qa1_r(3, 2)*x0
            x69 = qa0(2)*x66 - qa1_r(3, 2)*x62 + qa2_rr(3, 3, 2)*x0
            x70 = -qa0(3)*x62 + 2.0_wp*qa1_r(3, 3)*x0
            x71 = qa0(3)*x66 - qa1_r(3, 3)*x62 + qa2_rr(3, 3, 3)*x0
            f2_rArB(1, 1) = -inv_pd*qq0(1, 1) + qb0(1)*x1
            f2_rArB(1, 2) = -inv_pd*qq0(1, 2) + qb0(2)*x1
            f2_rArB(1, 3) = -inv_pd*qq0(1, 3) + qb0(3)*x1
            f2_rArB(2, 1) = -inv_pd*qq0(2, 1) + qb0(1)*x2
            f2_rArB(2, 2) = -inv_pd*qq0(2, 2) + qb0(2)*x2
            f2_rArB(2, 3) = -inv_pd*qq0(2, 3) + qb0(3)*x2
            f2_rArB(3, 1) = -inv_pd*qq0(3, 1) + qb0(1)*x3
            f2_rArB(3, 2) = -inv_pd*qq0(3, 2) + qb0(2)*x3
            f2_rArB(3, 3) = -inv_pd*qq0(3, 3) + qb0(3)*x3
            f3_r_rArB(1, 1, 1) = -inv_pd*qq1_r(1, 1, 1) + qb0(1)*x8 + qb1_r(1, 1)*x1 + qq0(1, 1)*x4
            f3_r_rArB(1, 1, 2) = -inv_pd*qq1_r(1, 1, 2) + qb0(2)*x8 + qb1_r(1, 2)*x1 + qq0(1, 2)*x4
            f3_r_rArB(1, 1, 3) = -inv_pd*qq1_r(1, 1, 3) + qb0(3)*x8 + qb1_r(1, 3)*x1 + qq0(1, 3)*x4
            f3_r_rArB(1, 2, 1) = -inv_pd*qq1_r(1, 2, 1) + qb0(1)*x9 + qb1_r(1, 1)*x2 + qq0(2, 1)*x4
            f3_r_rArB(1, 2, 2) = -inv_pd*qq1_r(1, 2, 2) + qb0(2)*x9 + qb1_r(1, 2)*x2 + qq0(2, 2)*x4
            f3_r_rArB(1, 2, 3) = -inv_pd*qq1_r(1, 2, 3) + qb0(3)*x9 + qb1_r(1, 3)*x2 + qq0(2, 3)*x4
            f3_r_rArB(1, 3, 1) = -inv_pd*qq1_r(1, 3, 1) + qb0(1)*x10 + qb1_r(1, 1)*x3 + qq0(3, 1)*x4
            f3_r_rArB(1, 3, 2) = -inv_pd*qq1_r(1, 3, 2) + qb0(2)*x10 + qb1_r(1, 2)*x3 + qq0(3, 2)*x4
            f3_r_rArB(1, 3, 3) = -inv_pd*qq1_r(1, 3, 3) + qb0(3)*x10 + qb1_r(1, 3)*x3 + qq0(3, 3)*x4
            f3_r_rArB(2, 1, 1) = &
