               qb2_rr(2, 3, 1)*x3 + qq0(3, 1)*x56 + qq1_r(2, 3, 1)*x16 + qq1_r(3, 3, 1)*x11
            f4_rr_rArB(2, 3, 3, 1) = t_f4_rr_rArB_1220
            f4_rr_rArB(3, 2, 3, 1) = t_f4_rr_rArB_1220
            t_f4_rr_rArB_1221 = &
               -inv_pd*qq2_rr(2, 3, 3, 2) + qb0(2)*x60 + qb1_r(2, 2)*x20 + qb1_r(3, 2)*x15 + &
               qb2_rr(2, 3, 2)*x3 + qq0(3, 2)*x56 + qq1_r(2, 3, 2)*x16 + qq1_r(3, 3, 2)*x11
            f4_rr_rArB(2, 3, 3, 2) = t_f4_rr_rArB_1221
            f4_rr_rArB(3, 2, 3, 2) = t_f4_rr_rArB_1221
            t_f4_rr_rArB_1222 = &
               -inv_pd*qq2_rr(2, 3, 3, 3) + qb0(3)*x60 + qb1_r(2, 3)*x20 + qb1_r(3, 3)*x15 + &
               qb2_rr(2, 3, 3)*x3 + qq0(3, 3)*x56 + qq1_r(2, 3, 3)*x16 + qq1_r(3, 3, 3)*x11
            f4_rr_rArB(2, 3, 3, 3) = t_f4_rr_rArB_1222
            f4_rr_rArB(3, 2, 3, 3) = t_f4_rr_rArB_1222
            f4_rr_rArB(3, 3, 1, 1) = &
               -inv_pd*qq2_rr(3, 3, 1, 1) + qb0(1)*x67 + qb1_r(3, 1)*x63 + qb2_rr(3, 3, 1)*x1 + &
               qq0(1, 1)*x65 + qq1_r(3, 1, 1)*x61
            f4_rr_rArB(3, 3, 1, 2) = &
               -inv_pd*qq2_rr(3, 3, 1, 2) + qb0(2)*x67 + qb1_r(3, 2)*x63 + qb2_rr(3, 3, 2)*x1 + &
               qq0(1, 2)*x65 + qq1_r(3, 1, 2)*x61
            f4_rr_rArB(3, 3, 1, 3) = &
               -inv_pd*qq2_rr(3, 3, 1, 3) + qb0(3)*x67 + qb1_r(3, 3)*x63 + qb2_rr(3, 3, 3)*x1 + &
               qq0(1, 3)*x65 + qq1_r(3, 1, 3)*x61
            f4_rr_rArB(3, 3, 2, 1) = &
               -inv_pd*qq2_rr(3, 3, 2, 1) + qb0(1)*x69 + qb1_r(3, 1)*x68 + qb2_rr(3, 3, 1)*x2 + &
               qq0(2, 1)*x65 + qq1_r(3, 2, 1)*x61
            f4_rr_rArB(3, 3, 2, 2) = &
               -inv_pd*qq2_rr(3, 3, 2, 2) + qb0(2)*x69 + qb1_r(3, 2)*x68 + qb2_rr(3, 3, 2)*x2 + &
               qq0(2, 2)*x65 + qq1_r(3, 2, 2)*x61
            f4_rr_rArB(3, 3, 2, 3) = &
               -inv_pd*qq2_rr(3, 3, 2, 3) + qb0(3)*x69 + qb1_r(3, 3)*x68 + qb2_rr(3, 3, 3)*x2 + &
               qq0(2, 3)*x65 + qq1_r(3, 2, 3)*x61
            f4_rr_rArB(3, 3, 3, 1) = &
               -inv_pd*qq2_rr(3, 3, 3, 1) + qb0(1)*x71 + qb1_r(3, 1)*x70 + qb2_rr(3, 3, 1)*x3 + &
               qq0(3, 1)*x65 + qq1_r(3, 3, 1)*x61
            f4_rr_rArB(3, 3, 3, 2) = &
               -inv_pd*qq2_rr(3, 3, 3, 2) + qb0(2)*x71 + qb1_r(3, 2)*x70 + qb2_rr(3, 3, 2)*x3 + &
               qq0(3, 2)*x65 + qq1_r(3, 3, 2)*x61
            f4_rr_rArB(3, 3, 3, 3) = &
               -inv_pd*qq2_rr(3, 3, 3, 3) + qb0(3)*x71 + qb1_r(3, 3)*x70 + qb2_rr(3, 3, 3)*x3 + &
               qq0(3, 3)*x65 + qq1_r(3, 3, 3)*x61
         end block
      end select

   end subroutine cfc_hessian_eval

   pure module subroutine cfc_tangent_eval(pd0, pd1_r, pd2_rr, pd3_rrr, tg0, tg1_r, tg2_rr, tg3_rrr, &
                                    max_deriv, tangent_f0, tangent_f1_r, tangent_f2_rr, &
                                    tangent_f3_rrr)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Accumulated order-3 spatial derivative of PD
      real(wp), intent(in) :: pd3_rrr(3, 3, 3)
      !> Accumulated sum_B v_B . d/dR_B of the order-0 derivative of PD
      real(wp), intent(in) :: tg0
      !> Accumulated sum_B v_B . d/dR_B of the order-1 derivative of PD
      real(wp), intent(in) :: tg1_r(3)
      !> Accumulated sum_B v_B . d/dR_B of the order-2 derivative of PD
      real(wp), intent(in) :: tg2_rr(3, 3)
      !> Accumulated sum_B v_B . d/dR_B of the order-3 derivative of PD
      real(wp), intent(in) :: tg3_rrr(3, 3, 3)
      !> Highest spatial-derivative order to lift (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_B v_B . d/dR_B of the order-0 spatial derivative of the level set
      real(wp), intent(out) :: tangent_f0
      !> sum_B v_B . d/dR_B of the order-1 spatial derivative of the level set
      real(wp), intent(out) :: tangent_f1_r(3)
      !> sum_B v_B . d/dR_B of the order-2 spatial derivative of the level set
      real(wp), intent(out) :: tangent_f2_rr(3, 3)
      !> sum_B v_B . d/dR_B of the order-3 spatial derivative of the level set
      real(wp), intent(out) :: tangent_f3_rrr(3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      tangent_f0 = 0.0_wp
      tangent_f1_r = 0.0_wp
      tangent_f2_rr = 0.0_wp
      tangent_f3_rrr = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            tangent_f0 = -inv_pd*tg0
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0

            x0 = (inv_pd*inv_pd)*tg0
            tangent_f0 = -inv_pd*tg0
            tangent_f1_r(1) = -inv_pd*tg1_r(1) + pd1_r(1)*x0
            tangent_f1_r(2) = -inv_pd*tg1_r(2) + pd1_r(2)*x0
            tangent_f1_r(3) = -inv_pd*tg1_r(3) + pd1_r(3)*x0
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, t_tangent_f2_rr_01, t_tangent_f2_rr_02
            real(wp) :: t_tangent_f2_rr_12

            x0 = (inv_pd*inv_pd)
            x1 = tg0*x0
            x2 = pd1_r(1)*x0
            x3 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
            x4 = tg1_r(1)*x0
            x5 = pd1_r(1)*x3
            x6 = pd1_r(2)*x0
            x7 = pd1_r(3)*x0
            tangent_f0 = -inv_pd*tg0
            tangent_f1_r(1) = -inv_pd*tg1_r(1) + pd1_r(1)*x1
            tangent_f1_r(2) = -inv_pd*tg1_r(2) + pd1_r(2)*x1
            tangent_f1_r(3) = -inv_pd*tg1_r(3) + pd1_r(3)*x1
            tangent_f2_rr(1, 1) = &
               -inv_pd*tg2_rr(1, 1) + tg0*(-(pd1_r(1)*pd1_r(1))*x3 + pd2_rr(1, 1)*x0) + &
               2.0_wp*tg1_r(1)*x2
            t_tangent_f2_rr_01 = &
               -inv_pd*tg2_rr(1, 2) + pd1_r(2)*x4 + tg0*(-pd1_r(2)*x5 + pd2_rr(1, 2)*x0) + &
               tg1_r(2)*x2
            tangent_f2_rr(1, 2) = t_tangent_f2_rr_01
            tangent_f2_rr(2, 1) = t_tangent_f2_rr_01
            t_tangent_f2_rr_02 = &
               -inv_pd*tg2_rr(1, 3) + pd1_r(3)*x4 + tg0*(-pd1_r(3)*x5 + pd2_rr(1, 3)*x0) + &
               tg1_r(3)*x2
            tangent_f2_rr(1, 3) = t_tangent_f2_rr_02
            tangent_f2_rr(3, 1) = t_tangent_f2_rr_02
            tangent_f2_rr(2, 2) = &
               -inv_pd*tg2_rr(2, 2) + tg0*(-(pd1_r(2)*pd1_r(2))*x3 + pd2_rr(2, 2)*x0) + &
               2.0_wp*tg1_r(2)*x6
            t_tangent_f2_rr_12 = &
               -inv_pd*tg2_rr(2, 3) + tg0*(-pd1_r(2)*pd1_r(3)*x3 + pd2_rr(2, 3)*x0) + tg1_r(2)*x7 &
               + tg1_r(3)*x6
            tangent_f2_rr(2, 3) = t_tangent_f2_rr_12
            tangent_f2_rr(3, 2) = t_tangent_f2_rr_12
            tangent_f2_rr(3, 3) = &
               -inv_pd*tg2_rr(3, 3) + tg0*(-(pd1_r(3)*pd1_r(3))*x3 + pd2_rr(3, 3)*x0) + &
               2.0_wp*tg1_r(3)*x7
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, t_tangent_f2_rr_01
            real(wp) :: t_tangent_f2_rr_02, t_tangent_f2_rr_12, t_tangent_f3_rrr_001
            real(wp) :: t_tangent_f3_rrr_002, t_tangent_f3_rrr_011, t_tangent_f3_rrr_012
            real(wp) :: t_tangent_f3_rrr_022, t_tangent_f3_rrr_112, t_tangent_f3_rrr_122

            x0 = (inv_pd*inv_pd)
            x1 = tg0*x0
            x2 = pd1_r(1)*x0
            x3 = 2.0_wp*x2
            x4 = (pd1_r(1)*pd1_r(1))
            x5 = (inv_pd*inv_pd*inv_pd)
            x6 = 2.0_wp*x5
            x7 = pd2_rr(1, 1)*x0 - x4*x6
            x8 = tg1_r(1)*x0
            x9 = pd1_r(1)*x6
            x10 = -pd1_r(2)*x9 + pd2_rr(1, 2)*x0
            x11 = -pd1_r(3)*x9 + pd2_rr(1, 3)*x0
            x12 = pd1_r(2)*x0
            x13 = 2.0_wp*x12
            x14 = (pd1_r(2)*pd1_r(2))
            x15 = pd2_rr(2, 2)*x0 - x14*x6
            x16 = pd1_r(3)*x0
            x17 = pd1_r(2)*pd1_r(3)
            x18 = pd2_rr(2, 3)*x0 - x17*x6
            x19 = 2.0_wp*x16
            x20 = (pd1_r(3)*pd1_r(3))
            x21 = pd2_rr(3, 3)*x0 - x20*x6
            x22 = 6.0_wp*x4
            x23 = 4.0_wp*x5
            x24 = pd1_r(1)*x23
            x25 = (inv_pd*inv_pd*inv_pd*inv_pd)
            x26 = -pd2_rr(1, 1)*x6 + x22*x25
            x27 = -pd1_r(2)*x24 + 2.0_wp*pd2_rr(1, 2)*x0
            x28 = -pd1_r(3)*x24 + 2.0_wp*pd2_rr(1, 3)*x0
            x29 = pd2_rr(2, 2)*x6
            x30 = pd2_rr(1, 2)*x6
            x31 = 6.0_wp*x25
            x32 = pd1_r(1)*x31
            x33 = pd1_r(2)*x32 - x30
            x34 = pd2_rr(2, 3)*x6
            x35 = pd2_rr(1, 3)*x6
            x36 = pd2_rr(3, 3)*x6
            x37 = 6.0_wp*x14
            x38 = pd1_r(2)*x23
            x39 = x25*x37 - x29
            x40 = 2.0_wp*pd2_rr(2, 3)*x0 - x17*x23
            x41 = 6.0_wp*x20
            tangent_f0 = -inv_pd*tg0
            tangent_f1_r(1) = -inv_pd*tg1_r(1) + pd1_r(1)*x1
            tangent_f1_r(2) = -inv_pd*tg1_r(2) + pd1_r(2)*x1
            tangent_f1_r(3) = -inv_pd*tg1_r(3) + pd1_r(3)*x1
            tangent_f2_rr(1, 1) = -inv_pd*tg2_rr(1, 1) + tg0*x7 + tg1_r(1)*x3
            t_tangent_f2_rr_01 = -inv_pd*tg2_rr(1, 2) + pd1_r(2)*x8 + tg0*x10 + tg1_r(2)*x2
            tangent_f2_rr(1, 2) = t_tangent_f2_rr_01
            tangent_f2_rr(2, 1) = t_tangent_f2_rr_01
            t_tangent_f2_rr_02 = -inv_pd*tg2_rr(1, 3) + pd1_r(3)*x8 + tg0*x11 + tg1_r(3)*x2
            tangent_f2_rr(1, 3) = t_tangent_f2_rr_02
            tangent_f2_rr(3, 1) = t_tangent_f2_rr_02
            tangent_f2_rr(2, 2) = -inv_pd*tg2_rr(2, 2) + tg0*x15 + tg1_r(2)*x13
            t_tangent_f2_rr_12 = -inv_pd*tg2_rr(2, 3) + tg0*x18 + tg1_r(2)*x16 + tg1_r(3)*x12
            tangent_f2_rr(2, 3) = t_tangent_f2_rr_12
            tangent_f2_rr(3, 2) = t_tangent_f2_rr_12
            tangent_f2_rr(3, 3) = -inv_pd*tg2_rr(3, 3) + tg0*x21 + tg1_r(3)*x19
            tangent_f3_rrr(1, 1, 1) = &
               -inv_pd*tg3_rrr(1, 1, 1) + tg0*(pd1_r(1)*x26 - pd2_rr(1, 1)*x24 + pd3_rrr(1, 1, &
               1)*x0) + tg1_r(1)*(3.0_wp*pd2_rr(1, 1)*x0 - x22*x5) + 3.0_wp*tg2_rr(1, 1)*x2
            t_tangent_f3_rrr_001 = &
               -inv_pd*tg3_rrr(1, 1, 2) + tg0*(pd1_r(2)*x26 - pd2_rr(1, 2)*x24 + pd3_rrr(1, 1, &
               2)*x0) + tg1_r(1)*x27 + tg1_r(2)*x7 + tg2_rr(1, 1)*x12 + tg2_rr(1, 2)*x3
            tangent_f3_rrr(1, 1, 2) = t_tangent_f3_rrr_001
            tangent_f3_rrr(1, 2, 1) = t_tangent_f3_rrr_001
            tangent_f3_rrr(2, 1, 1) = t_tangent_f3_rrr_001
            t_tangent_f3_rrr_002 = &
               -inv_pd*tg3_rrr(1, 1, 3) + tg0*(pd1_r(3)*x26 - pd2_rr(1, 3)*x24 + pd3_rrr(1, 1, &
               3)*x0) + tg1_r(1)*x28 + tg1_r(3)*x7 + tg2_rr(1, 1)*x16 + tg2_rr(1, 3)*x3
            tangent_f3_rrr(1, 1, 3) = t_tangent_f3_rrr_002
            tangent_f3_rrr(1, 3, 1) = t_tangent_f3_rrr_002
            tangent_f3_rrr(3, 1, 1) = t_tangent_f3_rrr_002
            t_tangent_f3_rrr_011 = &
               -inv_pd*tg3_rrr(1, 2, 2) + tg0*(-pd1_r(1)*x29 - pd1_r(2)*x30 + pd1_r(2)*x33 + &
               pd3_rrr(1, 2, 2)*x0) + tg1_r(1)*x15 + tg1_r(2)*x27 + tg2_rr(1, 2)*x13 + tg2_rr(2, &
               2)*x2
            tangent_f3_rrr(1, 2, 2) = t_tangent_f3_rrr_011
            tangent_f3_rrr(2, 1, 2) = t_tangent_f3_rrr_011
            tangent_f3_rrr(2, 2, 1) = t_tangent_f3_rrr_011
            t_tangent_f3_rrr_012 = &
               -inv_pd*tg3_rrr(1, 2, 3) + tg0*(-pd1_r(1)*x34 - pd1_r(2)*x35 + pd1_r(3)*x33 + &
               pd3_rrr(1, 2, 3)*x0) + tg1_r(1)*x18 + tg1_r(2)*x11 + tg1_r(3)*x10 + tg2_rr(1, &
               2)*x16 + tg2_rr(1, 3)*x12 + tg2_rr(2, 3)*x2
            tangent_f3_rrr(1, 2, 3) = t_tangent_f3_rrr_012
            tangent_f3_rrr(1, 3, 2) = t_tangent_f3_rrr_012
            tangent_f3_rrr(2, 1, 3) = t_tangent_f3_rrr_012
            tangent_f3_rrr(2, 3, 1) = t_tangent_f3_rrr_012
            tangent_f3_rrr(3, 1, 2) = t_tangent_f3_rrr_012
            tangent_f3_rrr(3, 2, 1) = t_tangent_f3_rrr_012
            t_tangent_f3_rrr_022 = &
               -inv_pd*tg3_rrr(1, 3, 3) + tg0*(-pd1_r(1)*x36 - pd1_r(3)*x35 + &
               pd1_r(3)*(pd1_r(3)*x32 - x35) + pd3_rrr(1, 3, 3)*x0) + tg1_r(1)*x21 + tg1_r(3)*x28 &
               + tg2_rr(1, 3)*x19 + tg2_rr(3, 3)*x2
            tangent_f3_rrr(1, 3, 3) = t_tangent_f3_rrr_022
            tangent_f3_rrr(3, 1, 3) = t_tangent_f3_rrr_022
            tangent_f3_rrr(3, 3, 1) = t_tangent_f3_rrr_022
            tangent_f3_rrr(2, 2, 2) = &
               -inv_pd*tg3_rrr(2, 2, 2) + tg0*(pd1_r(2)*x39 - pd2_rr(2, 2)*x38 + pd3_rrr(2, 2, &
               2)*x0) + tg1_r(2)*(3.0_wp*pd2_rr(2, 2)*x0 - x37*x5) + 3.0_wp*tg2_rr(2, 2)*x12
            t_tangent_f3_rrr_112 = &
               -inv_pd*tg3_rrr(2, 2, 3) + tg0*(pd1_r(3)*x39 - pd2_rr(2, 3)*x38 + pd3_rrr(2, 2, &
               3)*x0) + tg1_r(2)*x40 + tg1_r(3)*x15 + tg2_rr(2, 2)*x16 + tg2_rr(2, 3)*x13
            tangent_f3_rrr(2, 2, 3) = t_tangent_f3_rrr_112
            tangent_f3_rrr(2, 3, 2) = t_tangent_f3_rrr_112
            tangent_f3_rrr(3, 2, 2) = t_tangent_f3_rrr_112
            t_tangent_f3_rrr_122 = &
               -inv_pd*tg3_rrr(2, 3, 3) + tg0*(-pd1_r(2)*x36 - pd1_r(3)*x34 + pd1_r(3)*(x17*x31 - &
               x34) + pd3_rrr(2, 3, 3)*x0) + tg1_r(2)*x21 + tg1_r(3)*x40 + tg2_rr(2, 3)*x19 + &
               tg2_rr(3, 3)*x12
            tangent_f3_rrr(2, 3, 3) = t_tangent_f3_rrr_122
            tangent_f3_rrr(3, 2, 3) = t_tangent_f3_rrr_122
            tangent_f3_rrr(3, 3, 2) = t_tangent_f3_rrr_122
            tangent_f3_rrr(3, 3, 3) = &
               -inv_pd*tg3_rrr(3, 3, 3) + tg0*(-pd1_r(3)*pd2_rr(3, 3)*x23 + pd1_r(3)*(x25*x41 - &
               x36) + pd3_rrr(3, 3, 3)*x0) + tg1_r(3)*(3.0_wp*pd2_rr(3, 3)*x0 - x41*x5) + &
               3.0_wp*tg2_rr(3, 3)*x16
         end block
      end select

   end subroutine cfc_tangent_eval

   pure module subroutine cfc_hvp_eval(pd0, pd1_r, pd2_rr, tg0, tg1_r, tg2_rr, qn0, qn1_r, qn2_rr, hvp0, &
                                hvp1_r, hvp2_rr, max_deriv, hvp_f1_rA, hvp_f2_r_rA, hvp_f3_rr_rA)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Accumulated sum_B v_B . d/dR_B of the order-0 derivative of PD
      real(wp), intent(in) :: tg0
      !> Accumulated sum_B v_B . d/dR_B of the order-1 derivative of PD
      real(wp), intent(in) :: tg1_r(3)
      !> Accumulated sum_B v_B . d/dR_B of the order-2 derivative of PD
      real(wp), intent(in) :: tg2_rr(3, 3)
      !> Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn0(3)
      !> Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn1_r(3, 3)
      !> Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn2_rr(3, 3, 3)
      !> Atom-A sum_B v_B . d2/(dR_A dR_B) of the order-0 spatial derivative of PD; trailing index
      !> is the retained nuclear component
      real(wp), intent(in) :: hvp0(3)
      !> Atom-A sum_B v_B . d2/(dR_A dR_B) of the order-1 spatial derivative of PD; trailing index
      !> is the retained nuclear component
      real(wp), intent(in) :: hvp1_r(3, 3)
      !> Atom-A sum_B v_B . d2/(dR_A dR_B) of the order-2 spatial derivative of PD; trailing index
      !> is the retained nuclear component
      real(wp), intent(in) :: hvp2_rr(3, 3, 3)
      !> Highest spatial-derivative order to lift (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> sum_B v_B . d2/(dR_A dR_B) of the order-0 spatial derivative of the level set; trailing
      !> index is the retained nuclear component
      real(wp), intent(out) :: hvp_f1_rA(3)
      !> sum_B v_B . d2/(dR_A dR_B) of the order-1 spatial derivative of the level set; trailing
      !> index is the retained nuclear component
      real(wp), intent(out) :: hvp_f2_r_rA(3, 3)
      !> sum_B v_B . d2/(dR_A dR_B) of the order-2 spatial derivative of the level set; trailing
      !> index is the retained nuclear component
      real(wp), intent(out) :: hvp_f3_rr_rA(3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      hvp_f1_rA = 0.0_wp
      hvp_f2_r_rA = 0.0_wp
      hvp_f3_rr_rA = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0

            x0 = (inv_pd*inv_pd)
            hvp_f1_rA(1) = -hvp0(1)*inv_pd + qn0(1)*tg0*x0
            hvp_f1_rA(2) = -hvp0(2)*inv_pd + qn0(2)*tg0*x0
            hvp_f1_rA(3) = -hvp0(3)*inv_pd + qn0(3)*tg0*x0
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            x2 = tg0*x0
            x3 = 2.0_wp*(inv_pd*inv_pd*inv_pd)*tg0
            x4 = -pd1_r(1)*x3 + tg1_r(1)*x0
            x5 = pd1_r(2)*x0
            x6 = -pd1_r(2)*x3 + tg1_r(2)*x0
            x7 = pd1_r(3)*x0
            x8 = -pd1_r(3)*x3 + tg1_r(3)*x0
            hvp_f1_rA(1) = -hvp0(1)*inv_pd + qn0(1)*tg0*x0
            hvp_f1_rA(2) = -hvp0(2)*inv_pd + qn0(2)*tg0*x0
            hvp_f1_rA(3) = -hvp0(3)*inv_pd + qn0(3)*tg0*x0
            hvp_f2_r_rA(1, 1) = hvp0(1)*x1 - hvp1_r(1, 1)*inv_pd + qn0(1)*x4 + qn1_r(1, 1)*x2
            hvp_f2_r_rA(1, 2) = hvp0(2)*x1 - hvp1_r(1, 2)*inv_pd + qn0(2)*x4 + qn1_r(1, 2)*x2
            hvp_f2_r_rA(1, 3) = hvp0(3)*x1 - hvp1_r(1, 3)*inv_pd + qn0(3)*x4 + qn1_r(1, 3)*x2
            hvp_f2_r_rA(2, 1) = hvp0(1)*x5 - hvp1_r(2, 1)*inv_pd + qn0(1)*x6 + qn1_r(2, 1)*x2
            hvp_f2_r_rA(2, 2) = hvp0(2)*x5 - hvp1_r(2, 2)*inv_pd + qn0(2)*x6 + qn1_r(2, 2)*x2
            hvp_f2_r_rA(2, 3) = hvp0(3)*x5 - hvp1_r(2, 3)*inv_pd + qn0(3)*x6 + qn1_r(2, 3)*x2
            hvp_f2_r_rA(3, 1) = hvp0(1)*x7 - hvp1_r(3, 1)*inv_pd + qn0(1)*x8 + qn1_r(3, 1)*x2
            hvp_f2_r_rA(3, 2) = hvp0(2)*x7 - hvp1_r(3, 2)*inv_pd + qn0(2)*x8 + qn1_r(3, 2)*x2
            hvp_f2_r_rA(3, 3) = hvp0(3)*x7 - hvp1_r(3, 3)*inv_pd + qn0(3)*x8 + qn1_r(3, 3)*x2
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, t_hvp_f3_rr_rA_010
            real(wp) :: t_hvp_f3_rr_rA_011, t_hvp_f3_rr_rA_012, t_hvp_f3_rr_rA_020
            real(wp) :: t_hvp_f3_rr_rA_021, t_hvp_f3_rr_rA_022, t_hvp_f3_rr_rA_120
            real(wp) :: t_hvp_f3_rr_rA_121, t_hvp_f3_rr_rA_122

            x0 = (inv_pd*inv_pd)
            x1 = pd1_r(1)*x0
            x2 = tg0*x0
            x3 = (inv_pd*inv_pd*inv_pd)
            x4 = 2.0_wp*x3
            x5 = tg0*x4
            x6 = -pd1_r(1)*x5 + tg1_r(1)*x0
            x7 = pd1_r(2)*x0
            x8 = -pd1_r(2)*x5 + tg1_r(2)*x0
            x9 = pd1_r(3)*x0
            x10 = -pd1_r(3)*x5 + tg1_r(3)*x0
            x11 = 2.0_wp*x1
            x12 = (pd1_r(1)*pd1_r(1))
            x13 = pd2_rr(1, 1)*x0 - x12*x4
            x14 = 4.0_wp*x3
            x15 = pd1_r(1)*x14
            x16 = -tg0*x15 + 2.0_wp*tg1_r(1)*x0
            x17 = 6.0_wp*(inv_pd*inv_pd*inv_pd*inv_pd)
            x18 = tg0*(-pd2_rr(1, 1)*x4 + x12*x17) - tg1_r(1)*x15 + tg2_rr(1, 1)*x0
            x19 = pd1_r(1)*pd1_r(2)
            x20 = pd2_rr(1, 2)*x0 - x19*x4
            x21 = pd1_r(1)*x4
            x22 = tg1_r(1)*x4
            x23 = -pd1_r(2)*x22 + tg0*(-pd2_rr(1, 2)*x4 + x17*x19) - tg1_r(2)*x21 + tg2_rr(1, 2)*x0
            x24 = -pd1_r(3)*x21 + pd2_rr(1, 3)*x0
            x25 = pd1_r(3)*x17
            x26 = &
               -pd1_r(3)*x22 + tg0*(pd1_r(1)*x25 - pd2_rr(1, 3)*x4) - tg1_r(3)*x21 + tg2_rr(1, &
               3)*x0
            x27 = 2.0_wp*x7
            x28 = (pd1_r(2)*pd1_r(2))
            x29 = pd2_rr(2, 2)*x0 - x28*x4
            x30 = pd1_r(2)*x14
            x31 = -tg0*x30 + 2.0_wp*tg1_r(2)*x0
            x32 = tg0*(-pd2_rr(2, 2)*x4 + x17*x28) - tg1_r(2)*x30 + tg2_rr(2, 2)*x0
            x33 = pd1_r(2)*x4
            x34 = -pd1_r(3)*x33 + pd2_rr(2, 3)*x0
            x35 = &
               -pd1_r(3)*tg1_r(2)*x4 + tg0*(pd1_r(2)*x25 - pd2_rr(2, 3)*x4) - tg1_r(3)*x33 + &
               tg2_rr(2, 3)*x0
            x36 = 2.0_wp*x9
            x37 = (pd1_r(3)*pd1_r(3))
            x38 = pd2_rr(3, 3)*x0 - x37*x4
            x39 = pd1_r(3)*x14
            x40 = -tg0*x39 + 2.0_wp*tg1_r(3)*x0
            x41 = tg0*(-pd2_rr(3, 3)*x4 + x17*x37) - tg1_r(3)*x39 + tg2_rr(3, 3)*x0
            hvp_f1_rA(1) = -hvp0(1)*inv_pd + qn0(1)*tg0*x0
            hvp_f1_rA(2) = -hvp0(2)*inv_pd + qn0(2)*tg0*x0
            hvp_f1_rA(3) = -hvp0(3)*inv_pd + qn0(3)*tg0*x0
            hvp_f2_r_rA(1, 1) = hvp0(1)*x1 - hvp1_r(1, 1)*inv_pd + qn0(1)*x6 + qn1_r(1, 1)*x2
            hvp_f2_r_rA(1, 2) = hvp0(2)*x1 - hvp1_r(1, 2)*inv_pd + qn0(2)*x6 + qn1_r(1, 2)*x2
            hvp_f2_r_rA(1, 3) = hvp0(3)*x1 - hvp1_r(1, 3)*inv_pd + qn0(3)*x6 + qn1_r(1, 3)*x2
            hvp_f2_r_rA(2, 1) = hvp0(1)*x7 - hvp1_r(2, 1)*inv_pd + qn0(1)*x8 + qn1_r(2, 1)*x2
            hvp_f2_r_rA(2, 2) = hvp0(2)*x7 - hvp1_r(2, 2)*inv_pd + qn0(2)*x8 + qn1_r(2, 2)*x2
            hvp_f2_r_rA(2, 3) = hvp0(3)*x7 - hvp1_r(2, 3)*inv_pd + qn0(3)*x8 + qn1_r(2, 3)*x2
            hvp_f2_r_rA(3, 1) = hvp0(1)*x9 - hvp1_r(3, 1)*inv_pd + qn0(1)*x10 + qn1_r(3, 1)*x2
            hvp_f2_r_rA(3, 2) = hvp0(2)*x9 - hvp1_r(3, 2)*inv_pd + qn0(2)*x10 + qn1_r(3, 2)*x2
            hvp_f2_r_rA(3, 3) = hvp0(3)*x9 - hvp1_r(3, 3)*inv_pd + qn0(3)*x10 + qn1_r(3, 3)*x2
            hvp_f3_rr_rA(1, 1, 1) = &
               hvp0(1)*x13 + hvp1_r(1, 1)*x11 - hvp2_rr(1, 1, 1)*inv_pd + qn0(1)*x18 + qn1_r(1, &
               1)*x16 + qn2_rr(1, 1, 1)*x2
            hvp_f3_rr_rA(1, 1, 2) = &
               hvp0(2)*x13 + hvp1_r(1, 2)*x11 - hvp2_rr(1, 1, 2)*inv_pd + qn0(2)*x18 + qn1_r(1, &
               2)*x16 + qn2_rr(1, 1, 2)*x2
            hvp_f3_rr_rA(1, 1, 3) = &
               hvp0(3)*x13 + hvp1_r(1, 3)*x11 - hvp2_rr(1, 1, 3)*inv_pd + qn0(3)*x18 + qn1_r(1, &
               3)*x16 + qn2_rr(1, 1, 3)*x2
            t_hvp_f3_rr_rA_010 = &
               hvp0(1)*x20 + hvp1_r(1, 1)*x7 + hvp1_r(2, 1)*x1 - hvp2_rr(1, 2, 1)*inv_pd + &
               qn0(1)*x23 + qn1_r(1, 1)*x8 + qn1_r(2, 1)*x6 + qn2_rr(1, 2, 1)*x2
            hvp_f3_rr_rA(1, 2, 1) = t_hvp_f3_rr_rA_010
            hvp_f3_rr_rA(2, 1, 1) = t_hvp_f3_rr_rA_010
            t_hvp_f3_rr_rA_011 = &
               hvp0(2)*x20 + hvp1_r(1, 2)*x7 + hvp1_r(2, 2)*x1 - hvp2_rr(1, 2, 2)*inv_pd + &
               qn0(2)*x23 + qn1_r(1, 2)*x8 + qn1_r(2, 2)*x6 + qn2_rr(1, 2, 2)*x2
            hvp_f3_rr_rA(1, 2, 2) = t_hvp_f3_rr_rA_011
            hvp_f3_rr_rA(2, 1, 2) = t_hvp_f3_rr_rA_011
            t_hvp_f3_rr_rA_012 = &
               hvp0(3)*x20 + hvp1_r(1, 3)*x7 + hvp1_r(2, 3)*x1 - hvp2_rr(1, 2, 3)*inv_pd + &
               qn0(3)*x23 + qn1_r(1, 3)*x8 + qn1_r(2, 3)*x6 + qn2_rr(1, 2, 3)*x2
            hvp_f3_rr_rA(1, 2, 3) = t_hvp_f3_rr_rA_012
            hvp_f3_rr_rA(2, 1, 3) = t_hvp_f3_rr_rA_012
            t_hvp_f3_rr_rA_020 = &
               hvp0(1)*x24 + hvp1_r(1, 1)*x9 + hvp1_r(3, 1)*x1 - hvp2_rr(1, 3, 1)*inv_pd + &
               qn0(1)*x26 + qn1_r(1, 1)*x10 + qn1_r(3, 1)*x6 + qn2_rr(1, 3, 1)*x2
            hvp_f3_rr_rA(1, 3, 1) = t_hvp_f3_rr_rA_020
            hvp_f3_rr_rA(3, 1, 1) = t_hvp_f3_rr_rA_020
            t_hvp_f3_rr_rA_021 = &
               hvp0(2)*x24 + hvp1_r(1, 2)*x9 + hvp1_r(3, 2)*x1 - hvp2_rr(1, 3, 2)*inv_pd + &
               qn0(2)*x26 + qn1_r(1, 2)*x10 + qn1_r(3, 2)*x6 + qn2_rr(1, 3, 2)*x2
            hvp_f3_rr_rA(1, 3, 2) = t_hvp_f3_rr_rA_021
            hvp_f3_rr_rA(3, 1, 2) = t_hvp_f3_rr_rA_021
            t_hvp_f3_rr_rA_022 = &
               hvp0(3)*x24 + hvp1_r(1, 3)*x9 + hvp1_r(3, 3)*x1 - hvp2_rr(1, 3, 3)*inv_pd + &
               qn0(3)*x26 + qn1_r(1, 3)*x10 + qn1_r(3, 3)*x6 + qn2_rr(1, 3, 3)*x2
            hvp_f3_rr_rA(1, 3, 3) = t_hvp_f3_rr_rA_022
            hvp_f3_rr_rA(3, 1, 3) = t_hvp_f3_rr_rA_022
            hvp_f3_rr_rA(2, 2, 1) = &
               hvp0(1)*x29 + hvp1_r(2, 1)*x27 - hvp2_rr(2, 2, 1)*inv_pd + qn0(1)*x32 + qn1_r(2, &
               1)*x31 + qn2_rr(2, 2, 1)*x2
            hvp_f3_rr_rA(2, 2, 2) = &
               hvp0(2)*x29 + hvp1_r(2, 2)*x27 - hvp2_rr(2, 2, 2)*inv_pd + qn0(2)*x32 + qn1_r(2, &
               2)*x31 + qn2_rr(2, 2, 2)*x2
            hvp_f3_rr_rA(2, 2, 3) = &
               hvp0(3)*x29 + hvp1_r(2, 3)*x27 - hvp2_rr(2, 2, 3)*inv_pd + qn0(3)*x32 + qn1_r(2, &
               3)*x31 + qn2_rr(2, 2, 3)*x2
            t_hvp_f3_rr_rA_120 = &
               hvp0(1)*x34 + hvp1_r(2, 1)*x9 + hvp1_r(3, 1)*x7 - hvp2_rr(2, 3, 1)*inv_pd + &
               qn0(1)*x35 + qn1_r(2, 1)*x10 + qn1_r(3, 1)*x8 + qn2_rr(2, 3, 1)*x2
            hvp_f3_rr_rA(2, 3, 1) = t_hvp_f3_rr_rA_120
            hvp_f3_rr_rA(3, 2, 1) = t_hvp_f3_rr_rA_120
            t_hvp_f3_rr_rA_121 = &
               hvp0(2)*x34 + hvp1_r(2, 2)*x9 + hvp1_r(3, 2)*x7 - hvp2_rr(2, 3, 2)*inv_pd + &
               qn0(2)*x35 + qn1_r(2, 2)*x10 + qn1_r(3, 2)*x8 + qn2_rr(2, 3, 2)*x2
            hvp_f3_rr_rA(2, 3, 2) = t_hvp_f3_rr_rA_121
            hvp_f3_rr_rA(3, 2, 2) = t_hvp_f3_rr_rA_121
            t_hvp_f3_rr_rA_122 = &
               hvp0(3)*x34 + hvp1_r(2, 3)*x9 + hvp1_r(3, 3)*x7 - hvp2_rr(2, 3, 3)*inv_pd + &
               qn0(3)*x35 + qn1_r(2, 3)*x10 + qn1_r(3, 3)*x8 + qn2_rr(2, 3, 3)*x2
            hvp_f3_rr_rA(2, 3, 3) = t_hvp_f3_rr_rA_122
            hvp_f3_rr_rA(3, 2, 3) = t_hvp_f3_rr_rA_122
            hvp_f3_rr_rA(3, 3, 1) = &
               hvp0(1)*x38 + hvp1_r(3, 1)*x36 - hvp2_rr(3, 3, 1)*inv_pd + qn0(1)*x41 + qn1_r(3, &
               1)*x40 + qn2_rr(3, 3, 1)*x2
            hvp_f3_rr_rA(3, 3, 2) = &
               hvp0(2)*x38 + hvp1_r(3, 2)*x36 - hvp2_rr(3, 3, 2)*inv_pd + qn0(2)*x41 + qn1_r(3, &
               2)*x40 + qn2_rr(3, 3, 2)*x2
            hvp_f3_rr_rA(3, 3, 3) = &
               hvp0(3)*x38 + hvp1_r(3, 3)*x36 - hvp2_rr(3, 3, 3)*inv_pd + qn0(3)*x41 + qn1_r(3, &
               3)*x40 + qn2_rr(3, 3, 3)*x2
         end block
      end select

   end subroutine cfc_hvp_eval

   pure module subroutine cfc_vjp_eval(pd0, pd1_r, pd2_rr, qn0, qn1_r, qn2_rr, w0, w1, w2, vjp_f1_rA)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn0(3)
      !> Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn1_r(3, 3)
      !> Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qn2_rr(3, 3, 3)
      !> Adjoint weight of the value rung `f1_rA`
      real(wp), intent(in) :: w0
      !> Adjoint weights of the gradient rung `f2_r_rA`
      real(wp), intent(in) :: w1(3)
      !> Adjoint weights of the Hessian rung `f3_rr_rA`; a general 3x3, read entry by entry
      real(wp), intent(in) :: w2(3, 3)
      !> Adjoint jet contracted onto the nuclear gradient of the level set; the only index is the
      !> retained nuclear component
      real(wp), intent(out) :: vjp_f1_rA(3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd
      !> Common subexpressions and symmetry orbits
      real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16, x17
      real(wp) :: x18, x19, x20, x21, x22, x23, x24, x25, x26

      ! Unconditional: a screened-out point returns early below, and the
      ! result must be defined on that path too.
      vjp_f1_rA = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      x0 = inv_pd*w0
      x1 = (inv_pd*inv_pd)
      x2 = qn0(1)*x1
      x3 = pd1_r(1)*x1
      x4 = 2.0_wp*x3
      x5 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
      x6 = -(pd1_r(1)*pd1_r(1))*x5 + pd2_rr(1, 1)*x1
      x7 = pd1_r(2)*x1
      x8 = 2.0_wp*x7
      x9 = -(pd1_r(2)*pd1_r(2))*x5 + pd2_rr(2, 2)*x1
      x10 = pd1_r(3)*x1
      x11 = 2.0_wp*x10
      x12 = -(pd1_r(3)*pd1_r(3))*x5 + pd2_rr(3, 3)*x1
      x13 = qn1_r(1, 1)*x1
      x14 = pd1_r(1)*x5
      x15 = -pd1_r(2)*x14 + pd2_rr(1, 2)*x1
      x16 = -inv_pd*qn2_rr(1, 2, 1) + pd1_r(2)*x13 + qn0(1)*x15 + qn1_r(2, 1)*x3
      x17 = -pd1_r(3)*x14 + pd2_rr(1, 3)*x1
      x18 = -inv_pd*qn2_rr(1, 3, 1) + pd1_r(3)*x13 + qn0(1)*x17 + qn1_r(3, 1)*x3
      x19 = -pd1_r(2)*pd1_r(3)*x5 + pd2_rr(2, 3)*x1
      x20 = -inv_pd*qn2_rr(2, 3, 1) + qn0(1)*x19 + qn1_r(2, 1)*x10 + qn1_r(3, 1)*x7
      x21 = -inv_pd*qn2_rr(1, 2, 2) + qn0(2)*x15 + qn1_r(1, 2)*x7 + qn1_r(2, 2)*x3
      x22 = -inv_pd*qn2_rr(1, 3, 2) + qn0(2)*x17 + qn1_r(1, 2)*x10 + qn1_r(3, 2)*x3
      x23 = -inv_pd*qn2_rr(2, 3, 2) + qn0(2)*x19 + qn1_r(2, 2)*x10 + qn1_r(3, 2)*x7
      x24 = -inv_pd*qn2_rr(1, 2, 3) + qn0(3)*x15 + qn1_r(1, 3)*x7 + qn1_r(2, 3)*x3
      x25 = -inv_pd*qn2_rr(1, 3, 3) + qn0(3)*x17 + qn1_r(1, 3)*x10 + qn1_r(3, 3)*x3
      x26 = -inv_pd*qn2_rr(2, 3, 3) + qn0(3)*x19 + qn1_r(2, 3)*x10 + qn1_r(3, 3)*x7
      vjp_f1_rA(1) = &
         -qn0(1)*x0 + w1(1)*(-inv_pd*qn1_r(1, 1) + pd1_r(1)*x2) + w1(2)*(-inv_pd*qn1_r(2, 1) + &
         pd1_r(2)*x2) + w1(3)*(-inv_pd*qn1_r(3, 1) + pd1_r(3)*x2) + w2(1, 1)*(-inv_pd*qn2_rr(1, 1, &
         1) + qn0(1)*x6 + qn1_r(1, 1)*x4) + w2(1, 2)*x16 + w2(1, 3)*x18 + w2(2, 1)*x16 + w2(2, &
         2)*(-inv_pd*qn2_rr(2, 2, 1) + qn0(1)*x9 + qn1_r(2, 1)*x8) + w2(2, 3)*x20 + w2(3, 1)*x18 + &
         w2(3, 2)*x20 + w2(3, 3)*(-inv_pd*qn2_rr(3, 3, 1) + qn0(1)*x12 + qn1_r(3, 1)*x11)
      vjp_f1_rA(2) = &
         -qn0(2)*x0 + w1(1)*(-inv_pd*qn1_r(1, 2) + qn0(2)*x3) + w1(2)*(-inv_pd*qn1_r(2, 2) + &
         qn0(2)*x7) + w1(3)*(-inv_pd*qn1_r(3, 2) + qn0(2)*x10) + w2(1, 1)*(-inv_pd*qn2_rr(1, 1, 2) &
         + qn0(2)*x6 + qn1_r(1, 2)*x4) + w2(1, 2)*x21 + w2(1, 3)*x22 + w2(2, 1)*x21 + w2(2, &
         2)*(-inv_pd*qn2_rr(2, 2, 2) + qn0(2)*x9 + qn1_r(2, 2)*x8) + w2(2, 3)*x23 + w2(3, 1)*x22 + &
         w2(3, 2)*x23 + w2(3, 3)*(-inv_pd*qn2_rr(3, 3, 2) + qn0(2)*x12 + qn1_r(3, 2)*x11)
      vjp_f1_rA(3) = &
         -qn0(3)*x0 + w1(1)*(-inv_pd*qn1_r(1, 3) + qn0(3)*x3) + w1(2)*(-inv_pd*qn1_r(2, 3) + &
         qn0(3)*x7) + w1(3)*(-inv_pd*qn1_r(3, 3) + qn0(3)*x10) + w2(1, 1)*(-inv_pd*qn2_rr(1, 1, 3) &
         + qn0(3)*x6 + qn1_r(1, 3)*x4) + w2(1, 2)*x24 + w2(1, 3)*x25 + w2(2, 1)*x24 + w2(2, &
         2)*(-inv_pd*qn2_rr(2, 2, 3) + qn0(3)*x9 + qn1_r(2, 3)*x8) + w2(2, 3)*x26 + w2(3, 1)*x25 + &
         w2(3, 2)*x26 + w2(3, 3)*(-inv_pd*qn2_rr(3, 3, 3) + qn0(3)*x12 + qn1_r(3, 3)*x11)

   end subroutine cfc_vjp_eval

   pure module subroutine cfc_radius_eval(pd0, pd1_r, pd2_rr, pd3_rrr, rd0, rd1_r, rd2_rr, rd3_rrr, &
                                   max_deriv, f1_rad, f2_r_rad, f3_rr_rad, f4_rrr_rad)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Accumulated order-3 spatial derivative of PD
      real(wp), intent(in) :: pd3_rrr(3, 3, 3)
      !> Atom-A d/dRad_A of the order-0 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rd0
      !> Atom-A d/dRad_A of the order-1 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rd1_r(3)
      !> Atom-A d/dRad_A of the order-2 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rd2_rr(3, 3)
      !> Atom-A d/dRad_A of the order-3 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rd3_rrr(3, 3, 3)
      !> Highest spatial-derivative order to lift (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> d/dRad_A of the order-0 spatial derivative of the level set
      real(wp), intent(out) :: f1_rad
      !> d/dRad_A of the order-1 spatial derivative of the level set
      real(wp), intent(out) :: f2_r_rad(3)
      !> d/dRad_A of the order-2 spatial derivative of the level set
      real(wp), intent(out) :: f3_rr_rad(3, 3)
      !> d/dRad_A of the order-3 spatial derivative of the level set
      real(wp), intent(out) :: f4_rrr_rad(3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      f1_rad = 0.0_wp
      f2_r_rad = 0.0_wp
      f3_rr_rad = 0.0_wp
      f4_rrr_rad = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            f1_rad = -inv_pd*rd0
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0

            x0 = (inv_pd*inv_pd)*rd0
            f1_rad = -inv_pd*rd0
            f2_r_rad(1) = -inv_pd*rd1_r(1) + pd1_r(1)*x0
            f2_r_rad(2) = -inv_pd*rd1_r(2) + pd1_r(2)*x0
            f2_r_rad(3) = -inv_pd*rd1_r(3) + pd1_r(3)*x0
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, t_f3_rr_rad_01, t_f3_rr_rad_02
            real(wp) :: t_f3_rr_rad_12

            x0 = (inv_pd*inv_pd)
            x1 = rd0*x0
            x2 = pd1_r(1)*x0
            x3 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
            x4 = rd1_r(1)*x0
            x5 = pd1_r(1)*x3
            x6 = pd1_r(2)*x0
            x7 = pd1_r(3)*x0
            f1_rad = -inv_pd*rd0
            f2_r_rad(1) = -inv_pd*rd1_r(1) + pd1_r(1)*x1
            f2_r_rad(2) = -inv_pd*rd1_r(2) + pd1_r(2)*x1
            f2_r_rad(3) = -inv_pd*rd1_r(3) + pd1_r(3)*x1
            f3_rr_rad(1, 1) = &
               -inv_pd*rd2_rr(1, 1) + rd0*(-(pd1_r(1)*pd1_r(1))*x3 + pd2_rr(1, 1)*x0) + &
               2.0_wp*rd1_r(1)*x2
            t_f3_rr_rad_01 = &
               -inv_pd*rd2_rr(1, 2) + pd1_r(2)*x4 + rd0*(-pd1_r(2)*x5 + pd2_rr(1, 2)*x0) + &
               rd1_r(2)*x2
            f3_rr_rad(1, 2) = t_f3_rr_rad_01
            f3_rr_rad(2, 1) = t_f3_rr_rad_01
            t_f3_rr_rad_02 = &
               -inv_pd*rd2_rr(1, 3) + pd1_r(3)*x4 + rd0*(-pd1_r(3)*x5 + pd2_rr(1, 3)*x0) + &
               rd1_r(3)*x2
            f3_rr_rad(1, 3) = t_f3_rr_rad_02
            f3_rr_rad(3, 1) = t_f3_rr_rad_02
            f3_rr_rad(2, 2) = &
               -inv_pd*rd2_rr(2, 2) + rd0*(-(pd1_r(2)*pd1_r(2))*x3 + pd2_rr(2, 2)*x0) + &
               2.0_wp*rd1_r(2)*x6
            t_f3_rr_rad_12 = &
               -inv_pd*rd2_rr(2, 3) + rd0*(-pd1_r(2)*pd1_r(3)*x3 + pd2_rr(2, 3)*x0) + rd1_r(2)*x7 &
               + rd1_r(3)*x6
            f3_rr_rad(2, 3) = t_f3_rr_rad_12
            f3_rr_rad(3, 2) = t_f3_rr_rad_12
            f3_rr_rad(3, 3) = &
               -inv_pd*rd2_rr(3, 3) + rd0*(-(pd1_r(3)*pd1_r(3))*x3 + pd2_rr(3, 3)*x0) + &
               2.0_wp*rd1_r(3)*x7
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, t_f3_rr_rad_01
            real(wp) :: t_f3_rr_rad_02, t_f3_rr_rad_12, t_f4_rrr_rad_001, t_f4_rrr_rad_002
            real(wp) :: t_f4_rrr_rad_011, t_f4_rrr_rad_012, t_f4_rrr_rad_022, t_f4_rrr_rad_112
            real(wp) :: t_f4_rrr_rad_122

            x0 = (inv_pd*inv_pd)
            x1 = rd0*x0
            x2 = pd1_r(1)*x0
            x3 = 2.0_wp*x2
            x4 = (pd1_r(1)*pd1_r(1))
            x5 = (inv_pd*inv_pd*inv_pd)
            x6 = 2.0_wp*x5
            x7 = pd2_rr(1, 1)*x0 - x4*x6
            x8 = rd1_r(1)*x0
            x9 = pd1_r(1)*x6
            x10 = -pd1_r(2)*x9 + pd2_rr(1, 2)*x0
            x11 = -pd1_r(3)*x9 + pd2_rr(1, 3)*x0
            x12 = pd1_r(2)*x0
            x13 = 2.0_wp*x12
            x14 = (pd1_r(2)*pd1_r(2))
            x15 = pd2_rr(2, 2)*x0 - x14*x6
            x16 = pd1_r(3)*x0
            x17 = pd1_r(2)*pd1_r(3)
            x18 = pd2_rr(2, 3)*x0 - x17*x6
            x19 = 2.0_wp*x16
            x20 = (pd1_r(3)*pd1_r(3))
            x21 = pd2_rr(3, 3)*x0 - x20*x6
            x22 = 6.0_wp*x4
            x23 = 4.0_wp*x5
            x24 = pd1_r(1)*x23
            x25 = (inv_pd*inv_pd*inv_pd*inv_pd)
            x26 = -pd2_rr(1, 1)*x6 + x22*x25
            x27 = -pd1_r(2)*x24 + 2.0_wp*pd2_rr(1, 2)*x0
            x28 = -pd1_r(3)*x24 + 2.0_wp*pd2_rr(1, 3)*x0
            x29 = pd2_rr(2, 2)*x6
            x30 = pd2_rr(1, 2)*x6
            x31 = 6.0_wp*x25
            x32 = pd1_r(1)*x31
            x33 = pd1_r(2)*x32 - x30
            x34 = pd2_rr(2, 3)*x6
            x35 = pd2_rr(1, 3)*x6
            x36 = pd2_rr(3, 3)*x6
            x37 = 6.0_wp*x14
            x38 = pd1_r(2)*x23
            x39 = x25*x37 - x29
            x40 = 2.0_wp*pd2_rr(2, 3)*x0 - x17*x23
            x41 = 6.0_wp*x20
            f1_rad = -inv_pd*rd0
            f2_r_rad(1) = -inv_pd*rd1_r(1) + pd1_r(1)*x1
            f2_r_rad(2) = -inv_pd*rd1_r(2) + pd1_r(2)*x1
            f2_r_rad(3) = -inv_pd*rd1_r(3) + pd1_r(3)*x1
            f3_rr_rad(1, 1) = -inv_pd*rd2_rr(1, 1) + rd0*x7 + rd1_r(1)*x3
            t_f3_rr_rad_01 = -inv_pd*rd2_rr(1, 2) + pd1_r(2)*x8 + rd0*x10 + rd1_r(2)*x2
            f3_rr_rad(1, 2) = t_f3_rr_rad_01
            f3_rr_rad(2, 1) = t_f3_rr_rad_01
            t_f3_rr_rad_02 = -inv_pd*rd2_rr(1, 3) + pd1_r(3)*x8 + rd0*x11 + rd1_r(3)*x2
            f3_rr_rad(1, 3) = t_f3_rr_rad_02
            f3_rr_rad(3, 1) = t_f3_rr_rad_02
            f3_rr_rad(2, 2) = -inv_pd*rd2_rr(2, 2) + rd0*x15 + rd1_r(2)*x13
            t_f3_rr_rad_12 = -inv_pd*rd2_rr(2, 3) + rd0*x18 + rd1_r(2)*x16 + rd1_r(3)*x12
            f3_rr_rad(2, 3) = t_f3_rr_rad_12
            f3_rr_rad(3, 2) = t_f3_rr_rad_12
            f3_rr_rad(3, 3) = -inv_pd*rd2_rr(3, 3) + rd0*x21 + rd1_r(3)*x19
            f4_rrr_rad(1, 1, 1) = &
               -inv_pd*rd3_rrr(1, 1, 1) + rd0*(pd1_r(1)*x26 - pd2_rr(1, 1)*x24 + pd3_rrr(1, 1, &
               1)*x0) + rd1_r(1)*(3.0_wp*pd2_rr(1, 1)*x0 - x22*x5) + 3.0_wp*rd2_rr(1, 1)*x2
            t_f4_rrr_rad_001 = &
               -inv_pd*rd3_rrr(1, 1, 2) + rd0*(pd1_r(2)*x26 - pd2_rr(1, 2)*x24 + pd3_rrr(1, 1, &
               2)*x0) + rd1_r(1)*x27 + rd1_r(2)*x7 + rd2_rr(1, 1)*x12 + rd2_rr(1, 2)*x3
            f4_rrr_rad(1, 1, 2) = t_f4_rrr_rad_001
            f4_rrr_rad(1, 2, 1) = t_f4_rrr_rad_001
            f4_rrr_rad(2, 1, 1) = t_f4_rrr_rad_001
            t_f4_rrr_rad_002 = &
               -inv_pd*rd3_rrr(1, 1, 3) + rd0*(pd1_r(3)*x26 - pd2_rr(1, 3)*x24 + pd3_rrr(1, 1, &
               3)*x0) + rd1_r(1)*x28 + rd1_r(3)*x7 + rd2_rr(1, 1)*x16 + rd2_rr(1, 3)*x3
            f4_rrr_rad(1, 1, 3) = t_f4_rrr_rad_002
            f4_rrr_rad(1, 3, 1) = t_f4_rrr_rad_002
            f4_rrr_rad(3, 1, 1) = t_f4_rrr_rad_002
            t_f4_rrr_rad_011 = &
               -inv_pd*rd3_rrr(1, 2, 2) + rd0*(-pd1_r(1)*x29 - pd1_r(2)*x30 + pd1_r(2)*x33 + &
               pd3_rrr(1, 2, 2)*x0) + rd1_r(1)*x15 + rd1_r(2)*x27 + rd2_rr(1, 2)*x13 + rd2_rr(2, &
               2)*x2
            f4_rrr_rad(1, 2, 2) = t_f4_rrr_rad_011
            f4_rrr_rad(2, 1, 2) = t_f4_rrr_rad_011
            f4_rrr_rad(2, 2, 1) = t_f4_rrr_rad_011
            t_f4_rrr_rad_012 = &
               -inv_pd*rd3_rrr(1, 2, 3) + rd0*(-pd1_r(1)*x34 - pd1_r(2)*x35 + pd1_r(3)*x33 + &
               pd3_rrr(1, 2, 3)*x0) + rd1_r(1)*x18 + rd1_r(2)*x11 + rd1_r(3)*x10 + rd2_rr(1, &
               2)*x16 + rd2_rr(1, 3)*x12 + rd2_rr(2, 3)*x2
            f4_rrr_rad(1, 2, 3) = t_f4_rrr_rad_012
            f4_rrr_rad(1, 3, 2) = t_f4_rrr_rad_012
            f4_rrr_rad(2, 1, 3) = t_f4_rrr_rad_012
            f4_rrr_rad(2, 3, 1) = t_f4_rrr_rad_012
            f4_rrr_rad(3, 1, 2) = t_f4_rrr_rad_012
            f4_rrr_rad(3, 2, 1) = t_f4_rrr_rad_012
            t_f4_rrr_rad_022 = &
               -inv_pd*rd3_rrr(1, 3, 3) + rd0*(-pd1_r(1)*x36 - pd1_r(3)*x35 + &
               pd1_r(3)*(pd1_r(3)*x32 - x35) + pd3_rrr(1, 3, 3)*x0) + rd1_r(1)*x21 + rd1_r(3)*x28 &
               + rd2_rr(1, 3)*x19 + rd2_rr(3, 3)*x2
            f4_rrr_rad(1, 3, 3) = t_f4_rrr_rad_022
            f4_rrr_rad(3, 1, 3) = t_f4_rrr_rad_022
            f4_rrr_rad(3, 3, 1) = t_f4_rrr_rad_022
            f4_rrr_rad(2, 2, 2) = &
               -inv_pd*rd3_rrr(2, 2, 2) + rd0*(pd1_r(2)*x39 - pd2_rr(2, 2)*x38 + pd3_rrr(2, 2, &
               2)*x0) + rd1_r(2)*(3.0_wp*pd2_rr(2, 2)*x0 - x37*x5) + 3.0_wp*rd2_rr(2, 2)*x12
            t_f4_rrr_rad_112 = &
               -inv_pd*rd3_rrr(2, 2, 3) + rd0*(pd1_r(3)*x39 - pd2_rr(2, 3)*x38 + pd3_rrr(2, 2, &
               3)*x0) + rd1_r(2)*x40 + rd1_r(3)*x15 + rd2_rr(2, 2)*x16 + rd2_rr(2, 3)*x13
            f4_rrr_rad(2, 2, 3) = t_f4_rrr_rad_112
            f4_rrr_rad(2, 3, 2) = t_f4_rrr_rad_112
            f4_rrr_rad(3, 2, 2) = t_f4_rrr_rad_112
            t_f4_rrr_rad_122 = &
               -inv_pd*rd3_rrr(2, 3, 3) + rd0*(-pd1_r(2)*x36 - pd1_r(3)*x34 + pd1_r(3)*(x17*x31 - &
               x34) + pd3_rrr(2, 3, 3)*x0) + rd1_r(2)*x21 + rd1_r(3)*x40 + rd2_rr(2, 3)*x19 + &
               rd2_rr(3, 3)*x12
            f4_rrr_rad(2, 3, 3) = t_f4_rrr_rad_122
            f4_rrr_rad(3, 2, 3) = t_f4_rrr_rad_122
            f4_rrr_rad(3, 3, 2) = t_f4_rrr_rad_122
            f4_rrr_rad(3, 3, 3) = &
               -inv_pd*rd3_rrr(3, 3, 3) + rd0*(-pd1_r(3)*pd2_rr(3, 3)*x23 + pd1_r(3)*(x25*x41 - &
               x36) + pd3_rrr(3, 3, 3)*x0) + rd1_r(3)*(3.0_wp*pd2_rr(3, 3)*x0 - x41*x5) + &
               3.0_wp*rd2_rr(3, 3)*x16
         end block
      end select

   end subroutine cfc_radius_eval

   pure module subroutine cfc_radius2_eval(pd0, pd1_r, pd2_rr, ra0, ra1_r, ra2_rr, rb0, rb1_r, rb2_rr, &
                                    rr0, rr1_r, rr2_rr, max_deriv, f2_radrad, f3_r_radrad, &
                                    f4_rr_radrad)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Atom-A d/dRad_A of the order-0 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: ra0
      !> Atom-A d/dRad_A of the order-1 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: ra1_r(3)
      !> Atom-A d/dRad_A of the order-2 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: ra2_rr(3, 3)
      !> Atom-B d/dRad_B of the order-0 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rb0
      !> Atom-B d/dRad_B of the order-1 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rb1_r(3)
      !> Atom-B d/dRad_B of the order-2 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rb2_rr(3, 3)
      !> d2/(dRad_A dRad_B) of the order-0 spatial derivative of PD
      real(wp), intent(in) :: rr0
      !> d2/(dRad_A dRad_B) of the order-1 spatial derivative of PD
      real(wp), intent(in) :: rr1_r(3)
      !> d2/(dRad_A dRad_B) of the order-2 spatial derivative of PD
      real(wp), intent(in) :: rr2_rr(3, 3)
      !> Highest spatial-derivative order to lift (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dRad_A dRad_B) of the order-0 spatial derivative of the level set
      real(wp), intent(out) :: f2_radrad
      !> d2/(dRad_A dRad_B) of the order-1 spatial derivative of the level set
      real(wp), intent(out) :: f3_r_radrad(3)
      !> d2/(dRad_A dRad_B) of the order-2 spatial derivative of the level set
      real(wp), intent(out) :: f4_rr_radrad(3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      f2_radrad = 0.0_wp
      f3_r_radrad = 0.0_wp
      f4_rr_radrad = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            f2_radrad = (inv_pd*inv_pd)*ra0*rb0 - inv_pd*rr0
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3

            x0 = (inv_pd*inv_pd)
            x1 = ra0*x0
            x2 = rr0*x0
            x3 = 2.0_wp*(inv_pd*inv_pd*inv_pd)*ra0
            f2_radrad = -inv_pd*rr0 + rb0*x1
            f3_r_radrad(1) = &
               -inv_pd*rr1_r(1) + pd1_r(1)*x2 + rb0*(-pd1_r(1)*x3 + ra1_r(1)*x0) + rb1_r(1)*x1
            f3_r_radrad(2) = &
               -inv_pd*rr1_r(2) + pd1_r(2)*x2 + rb0*(-pd1_r(2)*x3 + ra1_r(2)*x0) + rb1_r(2)*x1
            f3_r_radrad(3) = &
               -inv_pd*rr1_r(3) + pd1_r(3)*x2 + rb0*(-pd1_r(3)*x3 + ra1_r(3)*x0) + rb1_r(3)*x1
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, t_f4_rr_radrad_01
            real(wp) :: t_f4_rr_radrad_02, t_f4_rr_radrad_12

            x0 = (inv_pd*inv_pd)
            x1 = ra0*x0
            x2 = rr0*x0
            x3 = (inv_pd*inv_pd*inv_pd)
            x4 = 2.0_wp*x3
            x5 = ra0*x4
            x6 = -pd1_r(1)*x5 + ra1_r(1)*x0
            x7 = -pd1_r(2)*x5 + ra1_r(2)*x0
            x8 = -pd1_r(3)*x5 + ra1_r(3)*x0
            x9 = pd1_r(1)*x0
            x10 = 4.0_wp*x3
            x11 = pd1_r(1)*x10
            x12 = (pd1_r(1)*pd1_r(1))
            x13 = 6.0_wp*(inv_pd*inv_pd*inv_pd*inv_pd)
            x14 = rr1_r(1)*x0
            x15 = pd1_r(1)*pd1_r(2)
            x16 = pd1_r(1)*x4
            x17 = ra1_r(1)*x4
            x18 = pd1_r(3)*x13
            x19 = pd1_r(2)*x0
            x20 = pd1_r(2)*x10
            x21 = (pd1_r(2)*pd1_r(2))
            x22 = pd1_r(3)*x0
            x23 = pd1_r(2)*x4
            x24 = pd1_r(3)*x10
            x25 = (pd1_r(3)*pd1_r(3))
            f2_radrad = -inv_pd*rr0 + rb0*x1
            f3_r_radrad(1) = -inv_pd*rr1_r(1) + pd1_r(1)*x2 + rb0*x6 + rb1_r(1)*x1
            f3_r_radrad(2) = -inv_pd*rr1_r(2) + pd1_r(2)*x2 + rb0*x7 + rb1_r(2)*x1
            f3_r_radrad(3) = -inv_pd*rr1_r(3) + pd1_r(3)*x2 + rb0*x8 + rb1_r(3)*x1
            f4_rr_radrad(1, 1) = &
               -inv_pd*rr2_rr(1, 1) + rb0*(ra0*(-pd2_rr(1, 1)*x4 + x12*x13) - ra1_r(1)*x11 + &
               ra2_rr(1, 1)*x0) + rb1_r(1)*(-ra0*x11 + 2.0_wp*ra1_r(1)*x0) + rb2_rr(1, 1)*x1 + &
               rr0*(pd2_rr(1, 1)*x0 - x12*x4) + 2.0_wp*rr1_r(1)*x9
            t_f4_rr_radrad_01 = &
               -inv_pd*rr2_rr(1, 2) + pd1_r(2)*x14 + rb0*(-pd1_r(2)*x17 + ra0*(-pd2_rr(1, 2)*x4 + &
               x13*x15) - ra1_r(2)*x16 + ra2_rr(1, 2)*x0) + rb1_r(1)*x7 + rb1_r(2)*x6 + rb2_rr(1, &
               2)*x1 + rr0*(pd2_rr(1, 2)*x0 - x15*x4) + rr1_r(2)*x9
            f4_rr_radrad(1, 2) = t_f4_rr_radrad_01
            f4_rr_radrad(2, 1) = t_f4_rr_radrad_01
            t_f4_rr_radrad_02 = &
               -inv_pd*rr2_rr(1, 3) + pd1_r(3)*x14 + rb0*(-pd1_r(3)*x17 + ra0*(pd1_r(1)*x18 - &
               pd2_rr(1, 3)*x4) - ra1_r(3)*x16 + ra2_rr(1, 3)*x0) + rb1_r(1)*x8 + rb1_r(3)*x6 + &
               rb2_rr(1, 3)*x1 + rr0*(-pd1_r(3)*x16 + pd2_rr(1, 3)*x0) + rr1_r(3)*x9
            f4_rr_radrad(1, 3) = t_f4_rr_radrad_02
            f4_rr_radrad(3, 1) = t_f4_rr_radrad_02
            f4_rr_radrad(2, 2) = &
               -inv_pd*rr2_rr(2, 2) + rb0*(ra0*(-pd2_rr(2, 2)*x4 + x13*x21) - ra1_r(2)*x20 + &
               ra2_rr(2, 2)*x0) + rb1_r(2)*(-ra0*x20 + 2.0_wp*ra1_r(2)*x0) + rb2_rr(2, 2)*x1 + &
               rr0*(pd2_rr(2, 2)*x0 - x21*x4) + 2.0_wp*rr1_r(2)*x19
            t_f4_rr_radrad_12 = &
               -inv_pd*rr2_rr(2, 3) + rb0*(-pd1_r(3)*ra1_r(2)*x4 + ra0*(pd1_r(2)*x18 - pd2_rr(2, &
               3)*x4) - ra1_r(3)*x23 + ra2_rr(2, 3)*x0) + rb1_r(2)*x8 + rb1_r(3)*x7 + rb2_rr(2, &
               3)*x1 + rr0*(-pd1_r(3)*x23 + pd2_rr(2, 3)*x0) + rr1_r(2)*x22 + rr1_r(3)*x19
            f4_rr_radrad(2, 3) = t_f4_rr_radrad_12
            f4_rr_radrad(3, 2) = t_f4_rr_radrad_12
            f4_rr_radrad(3, 3) = &
               -inv_pd*rr2_rr(3, 3) + rb0*(ra0*(-pd2_rr(3, 3)*x4 + x13*x25) - ra1_r(3)*x24 + &
               ra2_rr(3, 3)*x0) + rb1_r(3)*(-ra0*x24 + 2.0_wp*ra1_r(3)*x0) + rb2_rr(3, 3)*x1 + &
               rr0*(pd2_rr(3, 3)*x0 - x25*x4) + 2.0_wp*rr1_r(3)*x22
         end block
      end select

   end subroutine cfc_radius2_eval

   pure module subroutine cfc_nucrad_eval(pd0, pd1_r, pd2_rr, qa0, qa1_r, qa2_rr, rb0, rb1_r, rb2_rr, &
                                   mx0, mx1_r, mx2_rr, max_deriv, f2_rA_rad, f3_r_rA_rad, &
                                   f4_rr_rA_rad)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Atom-A d/dR_A of the order-0 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qa0(3)
      !> Atom-A d/dR_A of the order-1 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qa1_r(3, 3)
      !> Atom-A d/dR_A of the order-2 spatial derivative of PD; trailing index is the nuclear
      !> component
      real(wp), intent(in) :: qa2_rr(3, 3, 3)
      !> Atom-B d/dRad_B of the order-0 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rb0
      !> Atom-B d/dRad_B of the order-1 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rb1_r(3)
      !> Atom-B d/dRad_B of the order-2 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rb2_rr(3, 3)
      !> d2/(dR_A dRad_B) of the order-0 spatial derivative of PD; trailing index is atom A's
      !> nuclear component
      real(wp), intent(in) :: mx0(3)
      !> d2/(dR_A dRad_B) of the order-1 spatial derivative of PD; trailing index is atom A's
      !> nuclear component
      real(wp), intent(in) :: mx1_r(3, 3)
      !> d2/(dR_A dRad_B) of the order-2 spatial derivative of PD; trailing index is atom A's
      !> nuclear component
      real(wp), intent(in) :: mx2_rr(3, 3, 3)
      !> Highest spatial-derivative order to lift (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dR_A dRad_B) of the order-0 spatial derivative of the level set; trailing index is atom
      !> A's nuclear component
      real(wp), intent(out) :: f2_rA_rad(3)
      !> d2/(dR_A dRad_B) of the order-1 spatial derivative of the level set; trailing index is atom
      !> A's nuclear component
      real(wp), intent(out) :: f3_r_rA_rad(3, 3)
      !> d2/(dR_A dRad_B) of the order-2 spatial derivative of the level set; trailing index is atom
      !> A's nuclear component
      real(wp), intent(out) :: f4_rr_rA_rad(3, 3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      f2_rA_rad = 0.0_wp
      f3_r_rA_rad = 0.0_wp
      f4_rr_rA_rad = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0

            x0 = (inv_pd*inv_pd)*rb0
            f2_rA_rad(1) = -inv_pd*mx0(1) + qa0(1)*x0
            f2_rA_rad(2) = -inv_pd*mx0(2) + qa0(2)*x0
            f2_rA_rad(3) = -inv_pd*mx0(3) + qa0(3)*x0
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11

            x0 = (inv_pd*inv_pd)
            x1 = rb0*x0
            x2 = pd1_r(1)*x0
            x3 = rb1_r(1)*x0
            x4 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
            x5 = pd1_r(1)*x4
            x6 = pd1_r(2)*x0
            x7 = rb1_r(2)*x0
            x8 = pd1_r(2)*x4
            x9 = pd1_r(3)*x0
            x10 = rb1_r(3)*x0
            x11 = pd1_r(3)*x4
            f2_rA_rad(1) = -inv_pd*mx0(1) + qa0(1)*x1
            f2_rA_rad(2) = -inv_pd*mx0(2) + qa0(2)*x1
            f2_rA_rad(3) = -inv_pd*mx0(3) + qa0(3)*x1
            f3_r_rA_rad(1, 1) = &
               -inv_pd*mx1_r(1, 1) + mx0(1)*x2 + qa0(1)*x3 + rb0*(-qa0(1)*x5 + qa1_r(1, 1)*x0)
            f3_r_rA_rad(1, 2) = &
               -inv_pd*mx1_r(1, 2) + mx0(2)*x2 + qa0(2)*x3 + rb0*(-qa0(2)*x5 + qa1_r(1, 2)*x0)
            f3_r_rA_rad(1, 3) = &
               -inv_pd*mx1_r(1, 3) + mx0(3)*x2 + qa0(3)*x3 + rb0*(-qa0(3)*x5 + qa1_r(1, 3)*x0)
            f3_r_rA_rad(2, 1) = &
               -inv_pd*mx1_r(2, 1) + mx0(1)*x6 + qa0(1)*x7 + rb0*(-qa0(1)*x8 + qa1_r(2, 1)*x0)
            f3_r_rA_rad(2, 2) = &
               -inv_pd*mx1_r(2, 2) + mx0(2)*x6 + qa0(2)*x7 + rb0*(-qa0(2)*x8 + qa1_r(2, 2)*x0)
            f3_r_rA_rad(2, 3) = &
               -inv_pd*mx1_r(2, 3) + mx0(3)*x6 + qa0(3)*x7 + rb0*(-qa0(3)*x8 + qa1_r(2, 3)*x0)
            f3_r_rA_rad(3, 1) = &
               -inv_pd*mx1_r(3, 1) + mx0(1)*x9 + qa0(1)*x10 + rb0*(-qa0(1)*x11 + qa1_r(3, 1)*x0)
            f3_r_rA_rad(3, 2) = &
               -inv_pd*mx1_r(3, 2) + mx0(2)*x9 + qa0(2)*x10 + rb0*(-qa0(2)*x11 + qa1_r(3, 2)*x0)
            f3_r_rA_rad(3, 3) = &
               -inv_pd*mx1_r(3, 3) + mx0(3)*x9 + qa0(3)*x10 + rb0*(-qa0(3)*x11 + qa1_r(3, 3)*x0)
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, t_f4_rr_rA_rad_010, t_f4_rr_rA_rad_011
            real(wp) :: t_f4_rr_rA_rad_012, t_f4_rr_rA_rad_020, t_f4_rr_rA_rad_021
            real(wp) :: t_f4_rr_rA_rad_022, t_f4_rr_rA_rad_120, t_f4_rr_rA_rad_121
            real(wp) :: t_f4_rr_rA_rad_122

            x0 = (inv_pd*inv_pd)
            x1 = rb0*x0
            x2 = pd1_r(1)*x0
            x3 = rb1_r(1)*x0
            x4 = (inv_pd*inv_pd*inv_pd)
            x5 = 2.0_wp*x4
            x6 = pd1_r(1)*x5
            x7 = -qa0(1)*x6 + qa1_r(1, 1)*x0
            x8 = -qa0(2)*x6 + qa1_r(1, 2)*x0
            x9 = -qa0(3)*x6 + qa1_r(1, 3)*x0
            x10 = pd1_r(2)*x0
            x11 = rb1_r(2)*x0
            x12 = pd1_r(2)*x5
            x13 = -qa0(1)*x12 + qa1_r(2, 1)*x0
            x14 = -qa0(2)*x12 + qa1_r(2, 2)*x0
            x15 = -qa0(3)*x12 + qa1_r(2, 3)*x0
            x16 = pd1_r(3)*x0
            x17 = rb1_r(3)*x0
            x18 = pd1_r(3)*x5
            x19 = -qa0(1)*x18 + qa1_r(3, 1)*x0
            x20 = -qa0(2)*x18 + qa1_r(3, 2)*x0
            x21 = -qa0(3)*x18 + qa1_r(3, 3)*x0
            x22 = rb2_rr(1, 1)*x0
            x23 = 2.0_wp*x2
            x24 = (pd1_r(1)*pd1_r(1))
            x25 = pd2_rr(1, 1)*x0 - x24*x5
            x26 = 4.0_wp*x4
            x27 = pd1_r(1)*x26
            x28 = 6.0_wp*(inv_pd*inv_pd*inv_pd*inv_pd)
            x29 = -pd2_rr(1, 1)*x5 + x24*x28
            x30 = rb2_rr(1, 2)*x0
            x31 = -pd1_r(2)*x6 + pd2_rr(1, 2)*x0
            x32 = pd1_r(1)*x28
            x33 = pd1_r(2)*x32 - pd2_rr(1, 2)*x5
            x34 = rb2_rr(1, 3)*x0
            x35 = -pd1_r(3)*x6 + pd2_rr(1, 3)*x0
            x36 = pd1_r(3)*x32 - pd2_rr(1, 3)*x5
            x37 = rb2_rr(2, 2)*x0
            x38 = 2.0_wp*x10
            x39 = (pd1_r(2)*pd1_r(2))
            x40 = pd2_rr(2, 2)*x0 - x39*x5
            x41 = pd1_r(2)*x26
            x42 = -pd2_rr(2, 2)*x5 + x28*x39
            x43 = rb2_rr(2, 3)*x0
            x44 = -pd1_r(3)*x12 + pd2_rr(2, 3)*x0
            x45 = pd1_r(2)*pd1_r(3)*x28 - pd2_rr(2, 3)*x5
            x46 = rb2_rr(3, 3)*x0
            x47 = 2.0_wp*x16
            x48 = (pd1_r(3)*pd1_r(3))
            x49 = pd2_rr(3, 3)*x0 - x48*x5
            x50 = pd1_r(3)*x26
            x51 = -pd2_rr(3, 3)*x5 + x28*x48
            f2_rA_rad(1) = -inv_pd*mx0(1) + qa0(1)*x1
            f2_rA_rad(2) = -inv_pd*mx0(2) + qa0(2)*x1
            f2_rA_rad(3) = -inv_pd*mx0(3) + qa0(3)*x1
            f3_r_rA_rad(1, 1) = -inv_pd*mx1_r(1, 1) + mx0(1)*x2 + qa0(1)*x3 + rb0*x7
            f3_r_rA_rad(1, 2) = -inv_pd*mx1_r(1, 2) + mx0(2)*x2 + qa0(2)*x3 + rb0*x8
            f3_r_rA_rad(1, 3) = -inv_pd*mx1_r(1, 3) + mx0(3)*x2 + qa0(3)*x3 + rb0*x9
            f3_r_rA_rad(2, 1) = -inv_pd*mx1_r(2, 1) + mx0(1)*x10 + qa0(1)*x11 + rb0*x13
            f3_r_rA_rad(2, 2) = -inv_pd*mx1_r(2, 2) + mx0(2)*x10 + qa0(2)*x11 + rb0*x14
            f3_r_rA_rad(2, 3) = -inv_pd*mx1_r(2, 3) + mx0(3)*x10 + qa0(3)*x11 + rb0*x15
            f3_r_rA_rad(3, 1) = -inv_pd*mx1_r(3, 1) + mx0(1)*x16 + qa0(1)*x17 + rb0*x19
            f3_r_rA_rad(3, 2) = -inv_pd*mx1_r(3, 2) + mx0(2)*x16 + qa0(2)*x17 + rb0*x20
            f3_r_rA_rad(3, 3) = -inv_pd*mx1_r(3, 3) + mx0(3)*x16 + qa0(3)*x17 + rb0*x21
            f4_rr_rA_rad(1, 1, 1) = &
               -inv_pd*mx2_rr(1, 1, 1) + mx0(1)*x25 + mx1_r(1, 1)*x23 + qa0(1)*x22 + &
               rb0*(qa0(1)*x29 - qa1_r(1, 1)*x27 + qa2_rr(1, 1, 1)*x0) + rb1_r(1)*(-qa0(1)*x27 + &
               2.0_wp*qa1_r(1, 1)*x0)
            f4_rr_rA_rad(1, 1, 2) = &
               -inv_pd*mx2_rr(1, 1, 2) + mx0(2)*x25 + mx1_r(1, 2)*x23 + qa0(2)*x22 + &
               rb0*(qa0(2)*x29 - qa1_r(1, 2)*x27 + qa2_rr(1, 1, 2)*x0) + rb1_r(1)*(-qa0(2)*x27 + &
               2.0_wp*qa1_r(1, 2)*x0)
            f4_rr_rA_rad(1, 1, 3) = &
               -inv_pd*mx2_rr(1, 1, 3) + mx0(3)*x25 + mx1_r(1, 3)*x23 + qa0(3)*x22 + &
               rb0*(qa0(3)*x29 - qa1_r(1, 3)*x27 + qa2_rr(1, 1, 3)*x0) + rb1_r(1)*(-qa0(3)*x27 + &
               2.0_wp*qa1_r(1, 3)*x0)
            t_f4_rr_rA_rad_010 = &
               -inv_pd*mx2_rr(1, 2, 1) + mx0(1)*x31 + mx1_r(1, 1)*x10 + mx1_r(2, 1)*x2 + &
               qa0(1)*x30 + rb0*(qa0(1)*x33 - qa1_r(1, 1)*x12 - qa1_r(2, 1)*x6 + qa2_rr(1, 2, &
               1)*x0) + rb1_r(1)*x13 + rb1_r(2)*x7
            f4_rr_rA_rad(1, 2, 1) = t_f4_rr_rA_rad_010
            f4_rr_rA_rad(2, 1, 1) = t_f4_rr_rA_rad_010
            t_f4_rr_rA_rad_011 = &
               -inv_pd*mx2_rr(1, 2, 2) + mx0(2)*x31 + mx1_r(1, 2)*x10 + mx1_r(2, 2)*x2 + &
               qa0(2)*x30 + rb0*(qa0(2)*x33 - qa1_r(1, 2)*x12 - qa1_r(2, 2)*x6 + qa2_rr(1, 2, &
               2)*x0) + rb1_r(1)*x14 + rb1_r(2)*x8
            f4_rr_rA_rad(1, 2, 2) = t_f4_rr_rA_rad_011
            f4_rr_rA_rad(2, 1, 2) = t_f4_rr_rA_rad_011
            t_f4_rr_rA_rad_012 = &
               -inv_pd*mx2_rr(1, 2, 3) + mx0(3)*x31 + mx1_r(1, 3)*x10 + mx1_r(2, 3)*x2 + &
               qa0(3)*x30 + rb0*(qa0(3)*x33 - qa1_r(1, 3)*x12 - qa1_r(2, 3)*x6 + qa2_rr(1, 2, &
               3)*x0) + rb1_r(1)*x15 + rb1_r(2)*x9
            f4_rr_rA_rad(1, 2, 3) = t_f4_rr_rA_rad_012
            f4_rr_rA_rad(2, 1, 3) = t_f4_rr_rA_rad_012
            t_f4_rr_rA_rad_020 = &
               -inv_pd*mx2_rr(1, 3, 1) + mx0(1)*x35 + mx1_r(1, 1)*x16 + mx1_r(3, 1)*x2 + &
               qa0(1)*x34 + rb0*(qa0(1)*x36 - qa1_r(1, 1)*x18 - qa1_r(3, 1)*x6 + qa2_rr(1, 3, &
               1)*x0) + rb1_r(1)*x19 + rb1_r(3)*x7
            f4_rr_rA_rad(1, 3, 1) = t_f4_rr_rA_rad_020
            f4_rr_rA_rad(3, 1, 1) = t_f4_rr_rA_rad_020
            t_f4_rr_rA_rad_021 = &
               -inv_pd*mx2_rr(1, 3, 2) + mx0(2)*x35 + mx1_r(1, 2)*x16 + mx1_r(3, 2)*x2 + &
               qa0(2)*x34 + rb0*(qa0(2)*x36 - qa1_r(1, 2)*x18 - qa1_r(3, 2)*x6 + qa2_rr(1, 3, &
               2)*x0) + rb1_r(1)*x20 + rb1_r(3)*x8
            f4_rr_rA_rad(1, 3, 2) = t_f4_rr_rA_rad_021
            f4_rr_rA_rad(3, 1, 2) = t_f4_rr_rA_rad_021
            t_f4_rr_rA_rad_022 = &
               -inv_pd*mx2_rr(1, 3, 3) + mx0(3)*x35 + mx1_r(1, 3)*x16 + mx1_r(3, 3)*x2 + &
               qa0(3)*x34 + rb0*(qa0(3)*x36 - qa1_r(1, 3)*x18 - qa1_r(3, 3)*x6 + qa2_rr(1, 3, &
               3)*x0) + rb1_r(1)*x21 + rb1_r(3)*x9
            f4_rr_rA_rad(1, 3, 3) = t_f4_rr_rA_rad_022
            f4_rr_rA_rad(3, 1, 3) = t_f4_rr_rA_rad_022
            f4_rr_rA_rad(2, 2, 1) = &
               -inv_pd*mx2_rr(2, 2, 1) + mx0(1)*x40 + mx1_r(2, 1)*x38 + qa0(1)*x37 + &
               rb0*(qa0(1)*x42 - qa1_r(2, 1)*x41 + qa2_rr(2, 2, 1)*x0) + rb1_r(2)*(-qa0(1)*x41 + &
               2.0_wp*qa1_r(2, 1)*x0)
            f4_rr_rA_rad(2, 2, 2) = &
               -inv_pd*mx2_rr(2, 2, 2) + mx0(2)*x40 + mx1_r(2, 2)*x38 + qa0(2)*x37 + &
               rb0*(qa0(2)*x42 - qa1_r(2, 2)*x41 + qa2_rr(2, 2, 2)*x0) + rb1_r(2)*(-qa0(2)*x41 + &
               2.0_wp*qa1_r(2, 2)*x0)
            f4_rr_rA_rad(2, 2, 3) = &
               -inv_pd*mx2_rr(2, 2, 3) + mx0(3)*x40 + mx1_r(2, 3)*x38 + qa0(3)*x37 + &
               rb0*(qa0(3)*x42 - qa1_r(2, 3)*x41 + qa2_rr(2, 2, 3)*x0) + rb1_r(2)*(-qa0(3)*x41 + &
               2.0_wp*qa1_r(2, 3)*x0)
            t_f4_rr_rA_rad_120 = &
               -inv_pd*mx2_rr(2, 3, 1) + mx0(1)*x44 + mx1_r(2, 1)*x16 + mx1_r(3, 1)*x10 + &
               qa0(1)*x43 + rb0*(qa0(1)*x45 - qa1_r(2, 1)*x18 - qa1_r(3, 1)*x12 + qa2_rr(2, 3, &
               1)*x0) + rb1_r(2)*x19 + rb1_r(3)*x13
            f4_rr_rA_rad(2, 3, 1) = t_f4_rr_rA_rad_120
            f4_rr_rA_rad(3, 2, 1) = t_f4_rr_rA_rad_120
            t_f4_rr_rA_rad_121 = &
               -inv_pd*mx2_rr(2, 3, 2) + mx0(2)*x44 + mx1_r(2, 2)*x16 + mx1_r(3, 2)*x10 + &
               qa0(2)*x43 + rb0*(qa0(2)*x45 - qa1_r(2, 2)*x18 - qa1_r(3, 2)*x12 + qa2_rr(2, 3, &
               2)*x0) + rb1_r(2)*x20 + rb1_r(3)*x14
            f4_rr_rA_rad(2, 3, 2) = t_f4_rr_rA_rad_121
            f4_rr_rA_rad(3, 2, 2) = t_f4_rr_rA_rad_121
            t_f4_rr_rA_rad_122 = &
               -inv_pd*mx2_rr(2, 3, 3) + mx0(3)*x44 + mx1_r(2, 3)*x16 + mx1_r(3, 3)*x10 + &
               qa0(3)*x43 + rb0*(qa0(3)*x45 - qa1_r(2, 3)*x18 - qa1_r(3, 3)*x12 + qa2_rr(2, 3, &
               3)*x0) + rb1_r(2)*x21 + rb1_r(3)*x15
            f4_rr_rA_rad(2, 3, 3) = t_f4_rr_rA_rad_122
            f4_rr_rA_rad(3, 2, 3) = t_f4_rr_rA_rad_122
            f4_rr_rA_rad(3, 3, 1) = &
               -inv_pd*mx2_rr(3, 3, 1) + mx0(1)*x49 + mx1_r(3, 1)*x47 + qa0(1)*x46 + &
               rb0*(qa0(1)*x51 - qa1_r(3, 1)*x50 + qa2_rr(3, 3, 1)*x0) + rb1_r(3)*(-qa0(1)*x50 + &
               2.0_wp*qa1_r(3, 1)*x0)
            f4_rr_rA_rad(3, 3, 2) = &
               -inv_pd*mx2_rr(3, 3, 2) + mx0(2)*x49 + mx1_r(3, 2)*x47 + qa0(2)*x46 + &
               rb0*(qa0(2)*x51 - qa1_r(3, 2)*x50 + qa2_rr(3, 3, 2)*x0) + rb1_r(3)*(-qa0(2)*x50 + &
               2.0_wp*qa1_r(3, 2)*x0)
            f4_rr_rA_rad(3, 3, 3) = &
               -inv_pd*mx2_rr(3, 3, 3) + mx0(3)*x49 + mx1_r(3, 3)*x47 + qa0(3)*x46 + &
               rb0*(qa0(3)*x51 - qa1_r(3, 3)*x50 + qa2_rr(3, 3, 3)*x0) + rb1_r(3)*(-qa0(3)*x50 + &
               2.0_wp*qa1_r(3, 3)*x0)
         end block
      end select

   end subroutine cfc_nucrad_eval

   pure module subroutine cfc_radius_hvp_eval(pd0, pd1_r, pd2_rr, tg0, tg1_r, tg2_rr, rd0, rd1_r, &
                                       rd2_rr, rh0, rh1_r, rh2_rr, max_deriv, hvp_f1_rad, &
                                       hvp_f2_r_rad, hvp_f3_rr_rad)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Accumulated sum_B (v_B . d/dR_B + vr_B d/dRad_B) of the order-0 derivative of PD
      real(wp), intent(in) :: tg0
      !> Accumulated sum_B (v_B . d/dR_B + vr_B d/dRad_B) of the order-1 derivative of PD
      real(wp), intent(in) :: tg1_r(3)
      !> Accumulated sum_B (v_B . d/dR_B + vr_B d/dRad_B) of the order-2 derivative of PD
      real(wp), intent(in) :: tg2_rr(3, 3)
      !> Atom-A d/dRad_A of the order-0 spatial derivative of PD
      real(wp), intent(in) :: rd0
      !> Atom-A d/dRad_A of the order-1 spatial derivative of PD
      real(wp), intent(in) :: rd1_r(3)
      !> Atom-A d/dRad_A of the order-2 spatial derivative of PD
      real(wp), intent(in) :: rd2_rr(3, 3)
      !> Atom-A sum_B (v_B . d/dR_B + vr_B d/dRad_B) of d/dRad_A of the order-0 spatial derivative
      !> of PD
      real(wp), intent(in) :: rh0
      !> Atom-A sum_B (v_B . d/dR_B + vr_B d/dRad_B) of d/dRad_A of the order-1 spatial derivative
      !> of PD
      real(wp), intent(in) :: rh1_r(3)
      !> Atom-A sum_B (v_B . d/dR_B + vr_B d/dRad_B) of d/dRad_A of the order-2 spatial derivative
      !> of PD
      real(wp), intent(in) :: rh2_rr(3, 3)
      !> Highest spatial-derivative order to lift (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> sum_B (v_B . d/dR_B + vr_B d/dRad_B) of d/dRad_A of the order-0 spatial derivative of the
      !> level set
      real(wp), intent(out) :: hvp_f1_rad
      !> sum_B (v_B . d/dR_B + vr_B d/dRad_B) of d/dRad_A of the order-1 spatial derivative of the
      !> level set
      real(wp), intent(out) :: hvp_f2_r_rad(3)
      !> sum_B (v_B . d/dR_B + vr_B d/dRad_B) of d/dRad_A of the order-2 spatial derivative of the
      !> level set
      real(wp), intent(out) :: hvp_f3_rr_rad(3, 3)

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd

      ! Unconditional: the max_deriv dispatch below writes only the orders it
      ! was asked for, so every higher-order result must already be defined.
      hvp_f1_rad = 0.0_wp
      hvp_f2_r_rad = 0.0_wp
      hvp_f3_rr_rad = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      select case (max_deriv)
      case (0)
         block
            hvp_f1_rad = (inv_pd*inv_pd)*rd0*tg0 - inv_pd*rh0
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3

            x0 = (inv_pd*inv_pd)
            x1 = tg0*x0
            x2 = rh0*x0
            x3 = 2.0_wp*(inv_pd*inv_pd*inv_pd)*tg0
            hvp_f1_rad = -inv_pd*rh0 + rd0*x1
            hvp_f2_r_rad(1) = &
               -inv_pd*rh1_r(1) + pd1_r(1)*x2 + rd0*(-pd1_r(1)*x3 + tg1_r(1)*x0) + rd1_r(1)*x1
            hvp_f2_r_rad(2) = &
               -inv_pd*rh1_r(2) + pd1_r(2)*x2 + rd0*(-pd1_r(2)*x3 + tg1_r(2)*x0) + rd1_r(2)*x1
            hvp_f2_r_rad(3) = &
               -inv_pd*rh1_r(3) + pd1_r(3)*x2 + rd0*(-pd1_r(3)*x3 + tg1_r(3)*x0) + rd1_r(3)*x1
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, t_hvp_f3_rr_rad_01
            real(wp) :: t_hvp_f3_rr_rad_02, t_hvp_f3_rr_rad_12

            x0 = (inv_pd*inv_pd)
            x1 = tg0*x0
            x2 = rh0*x0
            x3 = (inv_pd*inv_pd*inv_pd)
            x4 = 2.0_wp*x3
            x5 = tg0*x4
            x6 = -pd1_r(1)*x5 + tg1_r(1)*x0
            x7 = -pd1_r(2)*x5 + tg1_r(2)*x0
            x8 = -pd1_r(3)*x5 + tg1_r(3)*x0
            x9 = pd1_r(1)*x0
            x10 = 4.0_wp*x3
            x11 = pd1_r(1)*x10
            x12 = (pd1_r(1)*pd1_r(1))
            x13 = 6.0_wp*(inv_pd*inv_pd*inv_pd*inv_pd)
            x14 = rh1_r(1)*x0
            x15 = pd1_r(1)*pd1_r(2)
            x16 = pd1_r(1)*x4
            x17 = tg1_r(1)*x4
            x18 = pd1_r(3)*x13
            x19 = pd1_r(2)*x0
            x20 = pd1_r(2)*x10
            x21 = (pd1_r(2)*pd1_r(2))
            x22 = pd1_r(3)*x0
            x23 = pd1_r(2)*x4
            x24 = pd1_r(3)*x10
            x25 = (pd1_r(3)*pd1_r(3))
            hvp_f1_rad = -inv_pd*rh0 + rd0*x1
            hvp_f2_r_rad(1) = -inv_pd*rh1_r(1) + pd1_r(1)*x2 + rd0*x6 + rd1_r(1)*x1
            hvp_f2_r_rad(2) = -inv_pd*rh1_r(2) + pd1_r(2)*x2 + rd0*x7 + rd1_r(2)*x1
            hvp_f2_r_rad(3) = -inv_pd*rh1_r(3) + pd1_r(3)*x2 + rd0*x8 + rd1_r(3)*x1
            hvp_f3_rr_rad(1, 1) = &
               -inv_pd*rh2_rr(1, 1) + rd0*(tg0*(-pd2_rr(1, 1)*x4 + x12*x13) - tg1_r(1)*x11 + &
               tg2_rr(1, 1)*x0) + rd1_r(1)*(-tg0*x11 + 2.0_wp*tg1_r(1)*x0) + rd2_rr(1, 1)*x1 + &
               rh0*(pd2_rr(1, 1)*x0 - x12*x4) + 2.0_wp*rh1_r(1)*x9
            t_hvp_f3_rr_rad_01 = &
               -inv_pd*rh2_rr(1, 2) + pd1_r(2)*x14 + rd0*(-pd1_r(2)*x17 + tg0*(-pd2_rr(1, 2)*x4 + &
               x13*x15) - tg1_r(2)*x16 + tg2_rr(1, 2)*x0) + rd1_r(1)*x7 + rd1_r(2)*x6 + rd2_rr(1, &
               2)*x1 + rh0*(pd2_rr(1, 2)*x0 - x15*x4) + rh1_r(2)*x9
            hvp_f3_rr_rad(1, 2) = t_hvp_f3_rr_rad_01
            hvp_f3_rr_rad(2, 1) = t_hvp_f3_rr_rad_01
            t_hvp_f3_rr_rad_02 = &
               -inv_pd*rh2_rr(1, 3) + pd1_r(3)*x14 + rd0*(-pd1_r(3)*x17 + tg0*(pd1_r(1)*x18 - &
               pd2_rr(1, 3)*x4) - tg1_r(3)*x16 + tg2_rr(1, 3)*x0) + rd1_r(1)*x8 + rd1_r(3)*x6 + &
               rd2_rr(1, 3)*x1 + rh0*(-pd1_r(3)*x16 + pd2_rr(1, 3)*x0) + rh1_r(3)*x9
            hvp_f3_rr_rad(1, 3) = t_hvp_f3_rr_rad_02
            hvp_f3_rr_rad(3, 1) = t_hvp_f3_rr_rad_02
            hvp_f3_rr_rad(2, 2) = &
               -inv_pd*rh2_rr(2, 2) + rd0*(tg0*(-pd2_rr(2, 2)*x4 + x13*x21) - tg1_r(2)*x20 + &
               tg2_rr(2, 2)*x0) + rd1_r(2)*(-tg0*x20 + 2.0_wp*tg1_r(2)*x0) + rd2_rr(2, 2)*x1 + &
               rh0*(pd2_rr(2, 2)*x0 - x21*x4) + 2.0_wp*rh1_r(2)*x19
            t_hvp_f3_rr_rad_12 = &
               -inv_pd*rh2_rr(2, 3) + rd0*(-pd1_r(3)*tg1_r(2)*x4 + tg0*(pd1_r(2)*x18 - pd2_rr(2, &
               3)*x4) - tg1_r(3)*x23 + tg2_rr(2, 3)*x0) + rd1_r(2)*x8 + rd1_r(3)*x7 + rd2_rr(2, &
               3)*x1 + rh0*(-pd1_r(3)*x23 + pd2_rr(2, 3)*x0) + rh1_r(2)*x22 + rh1_r(3)*x19
            hvp_f3_rr_rad(2, 3) = t_hvp_f3_rr_rad_12
            hvp_f3_rr_rad(3, 2) = t_hvp_f3_rr_rad_12
            hvp_f3_rr_rad(3, 3) = &
               -inv_pd*rh2_rr(3, 3) + rd0*(tg0*(-pd2_rr(3, 3)*x4 + x13*x25) - tg1_r(3)*x24 + &
               tg2_rr(3, 3)*x0) + rd1_r(3)*(-tg0*x24 + 2.0_wp*tg1_r(3)*x0) + rd2_rr(3, 3)*x1 + &
               rh0*(pd2_rr(3, 3)*x0 - x25*x4) + 2.0_wp*rh1_r(3)*x22
         end block
      end select

   end subroutine cfc_radius_hvp_eval

   pure module subroutine cfc_radius_vjp_eval(pd0, pd1_r, pd2_rr, rd0, rd1_r, rd2_rr, w0, w1, w2, &
                                       vjp_f1_rad)
      !> Accumulated order-0 spatial derivative of PD
      real(wp), intent(in) :: pd0
      !> Accumulated order-1 spatial derivative of PD
      real(wp), intent(in) :: pd1_r(3)
      !> Accumulated order-2 spatial derivative of PD
      real(wp), intent(in) :: pd2_rr(3, 3)
      !> Atom-A d/dRad_A of the order-0 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rd0
      !> Atom-A d/dRad_A of the order-1 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rd1_r(3)
      !> Atom-A d/dRad_A of the order-2 spatial derivative of PD (no trailing index: a radius is a
      !> scalar parameter)
      real(wp), intent(in) :: rd2_rr(3, 3)
      !> Adjoint weight of the value rung `f1_rad`
      real(wp), intent(in) :: w0
      !> Adjoint weights of the gradient rung `f2_r_rad`
      real(wp), intent(in) :: w1(3)
      !> Adjoint weights of the Hessian rung `f3_rr_rad`; a general 3x3, read entry by entry
      real(wp), intent(in) :: w2(3, 3)
      !> Adjoint jet contracted onto the radius gradient of the level set; a scalar, because a
      !> radius carries no index
      real(wp), intent(out) :: vjp_f1_rad

      !> Reciprocal of the total pseudo-density
      real(wp) :: inv_pd
      !> Common subexpressions and symmetry orbits
      real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10

      ! Unconditional: a screened-out point returns early below, and the
      ! result must be defined on that path too.
      vjp_f1_rad = 0.0_wp

      if (pd0 <= 0.0_wp) return
      inv_pd = 1.0_wp/pd0

      x0 = (inv_pd*inv_pd)
      x1 = rd0*x0
      x2 = pd1_r(1)*x0
      x3 = 2.0_wp*(inv_pd*inv_pd*inv_pd)
      x4 = pd1_r(2)*x0
      x5 = pd1_r(3)*x0
      x6 = rd1_r(1)*x0
      x7 = pd1_r(1)*x3
      x8 = -inv_pd*rd2_rr(1, 2) + pd1_r(2)*x6 + rd0*(-pd1_r(2)*x7 + pd2_rr(1, 2)*x0) + rd1_r(2)*x2
      x9 = -inv_pd*rd2_rr(1, 3) + pd1_r(3)*x6 + rd0*(-pd1_r(3)*x7 + pd2_rr(1, 3)*x0) + rd1_r(3)*x2
      x10 = &
         -inv_pd*rd2_rr(2, 3) + rd0*(-pd1_r(2)*pd1_r(3)*x3 + pd2_rr(2, 3)*x0) + rd1_r(2)*x5 + &
         rd1_r(3)*x4
      vjp_f1_rad = &
         -inv_pd*rd0*w0 + w1(1)*(-inv_pd*rd1_r(1) + pd1_r(1)*x1) + w1(2)*(-inv_pd*rd1_r(2) + &
         pd1_r(2)*x1) + w1(3)*(-inv_pd*rd1_r(3) + pd1_r(3)*x1) + w2(1, 1)*(-inv_pd*rd2_rr(1, 1) + &
         rd0*(-(pd1_r(1)*pd1_r(1))*x3 + pd2_rr(1, 1)*x0) + 2.0_wp*rd1_r(1)*x2) + w2(1, 2)*x8 + &
         w2(1, 3)*x9 + w2(2, 1)*x8 + w2(2, 2)*(-inv_pd*rd2_rr(2, 2) + rd0*(-(pd1_r(2)*pd1_r(2))*x3 &
         + pd2_rr(2, 2)*x0) + 2.0_wp*rd1_r(2)*x4) + w2(2, 3)*x10 + w2(3, 1)*x9 + w2(3, 2)*x10 + &
         w2(3, 3)*(-inv_pd*rd2_rr(3, 3) + rd0*(-(pd1_r(3)*pd1_r(3))*x3 + pd2_rr(3, 3)*x0) + &
         2.0_wp*rd1_r(3)*x5)

   end subroutine cfc_radius_vjp_eval

   pure module subroutine cfc_strip_powersums_o0(np, points, nat, centers, radii, bound_sq, a1, a2, &
                                          c_par, fade_start, fade_width, pd0, n_zero, geo, sv, &
                                          reach)
      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(0)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Strip points, point-last
      real(wp), intent(in) :: points(3, np)
      !> Atoms in the shared list
      integer, intent(in) :: nat
      !> Atom centers of the shared list
      real(wp), intent(in) :: centers(3, nat)
      !> Atom radii R_a
      real(wp), intent(in) :: radii(nat)
      !> Squared screening reach per atom, the gate's `cand_screen` row
      real(wp), intent(in) :: bound_sq(nat)
      !> Atomic-term exponent a1 (<= 0)
      real(wp), intent(in) :: a1
      !> Pair-term exponent a2 (<= 0)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma_A = ||r - R_A||/R_a - 1; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma_A, finite and > 0
      real(wp), intent(in) :: fade_width
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(out) :: pd0(np)
      !> Point-atom pairs at zero distance among the evaluated atoms; nonzero means the sums are not
      !> finite
      integer, intent(out) :: n_zero
      !> Point-first geometry cache and pair-pass workspace, one block per list atom (slots in the
      !> routine notes)
      real(wp), intent(out) :: geo(nps, 5, nat)
      !> Survivor workspace: list indices of the atoms kept by the strip classification, leading
      !> entries written
      integer, intent(out) :: sv(nat)
      !> Reach workspace: pair-test radius of each survivor, leading entries written
      real(wp), intent(out) :: reach(nat)

      !> Accumulated columns, one per orbit representative
      integer, parameter :: nacc = 1
      !> Shrink of the strip-level distances in the gate tests (rounding slack)
      real(wp), parameter :: gate_shrink = 1.0_wp - 1e-12_wp
      !> Point-first copy of the strip
      real(wp) :: px(nps), py(nps), pz(nps)
      !> Reduced distance, unfaded factors and squared distance of one atom, point-first
      real(wp) :: gsg(nps), gu(nps), ge(nps), gr2(nps)
      !> Radial jets d^j (w u)/dx^j and d^j (w e)/dx^j of one atom, point-first
      real(wp) :: gju(nps, 0:0), gje(nps, 0:0)
      !> Fade of one atom against the strip, point-first
      real(wp) :: gfs(nps), gds(nps), gfp(nps, 0:0), gsp(nps, 5)
      !> Accumulators
      real(wp) :: acc(nps, nacc)
      !> Strip bounding box
      real(wp) :: lo(3), hi(3)
      !> Atom data, box distances and hoisted constants
      real(wp) :: cx, cy, cz, ra, ira, bsq, ex, ey, ez, e2, snear, sfar
      real(wp) :: lam1, lam2, band_end, inv_delta, irab, rsum
      !> Point geometry, inline-exp scalars and plain-jet scalars
      real(wp) :: dx, dy, dz, r2, x, sg, arg, ekf, er, ep, u, e, hu, he, dsx
      !> Fade scalars
      real(wp) :: sr, fs, ft
      !> Pair body: 1 - q, dq/dr, f(q) derivatives, f jet, f x G_B jet
      real(wp) :: pw, pf0, dp0_1, qj0_1
      !> Common subexpressions of one point-atom or point-pair
      real(wp) :: cs0
      !> Point, list and survivor indices
      integer :: p, a, i, j, ia, ib, ns

      if (np < 1 .or. np > nps) error stop &
         "cfc_strip_powersums_o0: np outside 1..strip width"
      if (.not. fade_width > 0.0_wp) error stop &
         "cfc_strip_powersums_o0: fade_width must be positive"
      if (a1 > 0.0_wp .or. a2 > 0.0_wp .or. max(-a1, -a2) > exp_arg_max) error stop &
         "cfc_strip_powersums_o0: exp argument bound exceeded"

      do p = 1, np
         px(p) = points(1, p)
         py(p) = points(2, p)
         pz(p) = points(3, p)
      end do
      lo(1) = minval(px(1:np))
      lo(2) = minval(py(1:np))
      lo(3) = minval(pz(1:np))
      hi(1) = maxval(px(1:np))
      hi(2) = maxval(py(1:np))
      hi(3) = maxval(pz(1:np))
      band_end = fade_start + fade_width
      inv_delta = 1.0_wp/fade_width
      acc(1:np, :) = 0.0_wp
      n_zero = 0
      ns = 0

      ! Atom pass: geometry cache, Cartesian jets, atomic terms
      do a = 1, nat
         cx = centers(1, a)
         cy = centers(2, a)
         cz = centers(3, a)
         ra = radii(a)
         ira = 1.0_wp/ra
         bsq = bound_sq(a)

         ! Nearest and farthest box point, as reduced distances
         ex = max(lo(1) - cx, 0.0_wp, cx - hi(1))
         ey = max(lo(2) - cy, 0.0_wp, cy - hi(2))
         ez = max(lo(3) - cz, 0.0_wp, cz - hi(3))
         e2 = ex*ex + ey*ey + ez*ez
         if (e2*gate_shrink > bsq) cycle
         snear = (sqrt(e2) - ra)*ira
         if (snear >= band_end) cycle
         ex = max(abs(cx - lo(1)), abs(cx - hi(1)))
         ey = max(abs(cy - lo(2)), abs(cy - hi(2)))
         ez = max(abs(cz - lo(3)), abs(cz - hi(3)))
         sfar = (sqrt(ex*ex + ey*ey + ez*ez) - ra)*ira
         ns = ns + 1
         sv(ns) = a
         ! Pair reach: the gate sphere, cut to the band end when that is nearer
         reach(ns) = sqrt(bsq)
         if (band_end < reach(ns)*ira - 1.0_wp) reach(ns) = ra*(1.0_wp + band_end)
         lam1 = a1*ira
         lam2 = a2*ira

         do p = 1, np
            dx = px(p) - cx
            dy = py(p) - cy
            dz = pz(p) - cz
            r2 = dx*dx + dy*dy + dz*dz
            x = sqrt(r2)
            sg = (x - ra)*ira
            arg = max(a2*sg, exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            u = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            arg = max(a1*sg, exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            e = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            geo(p, 1, a) = dx
            geo(p, 2, a) = dy
            geo(p, 3, a) = dz
            geo(p, 4, a) = 1.0_wp/x
            gsg(p) = sg
            gu(p) = u
            ge(p) = e
            gr2(p) = r2
         end do
         ! Hard screening: the gate's own squared compare; a separate loop, as a
         ! select on the exp result lets the compiler sink the exp into a branch
         do p = 1, np
            gu(p) = merge(gu(p), 0.0_wp, gr2(p) <= bsq)
            ge(p) = merge(ge(p), 0.0_wp, gr2(p) <= bsq)
         end do
         n_zero = n_zero + count(gr2(1:np) == 0.0_wp)

         if (sfar <= fade_start) then
            ! Plateau for the whole strip: plain radial jets lam**j u
            do p = 1, np
               hu = gu(p)
               he = ge(p)
               gju(p, 0) = hu
               gje(p, 0) = he
            end do
         else
            ! Strip meets the band: faded radial jets
            do p = 1, np
               sr = (band_end - (gsg(p)))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((gsg(p) - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               gfs(p) = fs
               gds(p) = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               gfp(p, 0) = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               gsp(p, 1) = fs
               gsp(p, 2) = gsp(p, 1)*fs
               gsp(p, 3) = gsp(p, 2)*fs
               gsp(p, 4) = gsp(p, 3)*fs
               gsp(p, 5) = gsp(p, 4)*fs
            end do
            do p = 1, np
               dsx = gds(p)*ira
               cs0 = gfp(p, 0)*gsp(p, 5)
               gju(p, 0) = cs0*gu(p)
               gje(p, 0) = cs0*ge(p)
            end do
         end if

         ! Cartesian jets: pair factor into the cache, atomic term into the sums
         do p = 1, np
            geo(p, 5, a) = gju(p, 0)
            acc(p, 1) = acc(p, 1) + (gje(p, 0))
         end do
      end do

      ! Pair pass over the survivors, list order
      do i = 1, ns
         ia = sv(i)
         cx = centers(1, ia)
         cy = centers(2, ia)
         cz = centers(3, ia)
         ra = radii(ia)
         do j = i + 1, ns
            ib = sv(j)
            ex = centers(1, ib) - cx
            ey = centers(2, ib) - cy
            ez = centers(3, ib) - cz
            rsum = reach(i) + reach(j)
            if (sqrt(ex*ex + ey*ey + ez*ez)*gate_shrink > rsum) cycle
            irab = 1.0_wp/(ra*radii(ib))
            do p = 1, np
               pw = &
                  -irab*(geo(p, 1, ia)*geo(p, 1, ib) + geo(p, 2, ia)*geo(p, 2, ib) + geo(p, 3, &
                  ia)*geo(p, 3, ib)) + 1.0_wp
               pf0 = c_par*(pw*pw*pw*pw)
               dp0_1 = pf0
               qj0_1 = dp0_1*geo(p, 5, ib)
               acc(p, 1) = acc(p, 1) + (geo(p, 5, ia)*qj0_1)
            end do
         end do
      end do

      pd0(:) = acc(1:np, 1)

   end subroutine cfc_strip_powersums_o0

   pure module subroutine cfc_strip_lift_o0(np, pd0, lsf0)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(in) :: pd0(np)
      !> Level-set value S = -log(PD)
      real(wp), intent(out) :: lsf0(np)

      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(0)
      !> Point index
      integer :: p

      if (np < 1 .or. np > nps) error stop &
         "cfc_strip_lift_o0: np outside 1..strip width"

      ! libm log: kept out of the vectorized loops
      do p = 1, np
         lsf0(p) = -log(pd0(p))
      end do

   end subroutine cfc_strip_lift_o0

   pure module subroutine cfc_strip_powersums_o1(np, points, nat, centers, radii, bound_sq, a1, a2, &
                                          c_par, fade_start, fade_width, pd0, pd1, n_zero, geo, &
                                          sv, reach)
      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(1)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Strip points, point-last
      real(wp), intent(in) :: points(3, np)
      !> Atoms in the shared list
      integer, intent(in) :: nat
      !> Atom centers of the shared list
      real(wp), intent(in) :: centers(3, nat)
      !> Atom radii R_a
      real(wp), intent(in) :: radii(nat)
      !> Squared screening reach per atom, the gate's `cand_screen` row
      real(wp), intent(in) :: bound_sq(nat)
      !> Atomic-term exponent a1 (<= 0)
      real(wp), intent(in) :: a1
      !> Pair-term exponent a2 (<= 0)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma_A = ||r - R_A||/R_a - 1; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma_A, finite and > 0
      real(wp), intent(in) :: fade_width
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(out) :: pd0(np)
      !> Order-1 pseudo-density jet of the strip, point-first; second index the Cartesian component
      real(wp), intent(out) :: pd1(np, 3)
      !> Point-atom pairs at zero distance among the evaluated atoms; nonzero means the sums are not
      !> finite
      integer, intent(out) :: n_zero
      !> Point-first geometry cache and pair-pass workspace, one block per list atom (slots in the
      !> routine notes)
      real(wp), intent(out) :: geo(nps, 8, nat)
      !> Survivor workspace: list indices of the atoms kept by the strip classification, leading
      !> entries written
      integer, intent(out) :: sv(nat)
      !> Reach workspace: pair-test radius of each survivor, leading entries written
      real(wp), intent(out) :: reach(nat)

      !> Accumulated columns, one per orbit representative
      integer, parameter :: nacc = 4
      !> Shrink of the strip-level distances in the gate tests (rounding slack)
      real(wp), parameter :: gate_shrink = 1.0_wp - 1e-12_wp
      !> Point-first copy of the strip
      real(wp) :: px(nps), py(nps), pz(nps)
      !> Reduced distance, unfaded factors and squared distance of one atom, point-first
      real(wp) :: gsg(nps), gu(nps), ge(nps), gr2(nps)
      !> Radial jets d^j (w u)/dx^j and d^j (w e)/dx^j of one atom, point-first
      real(wp) :: gju(nps, 0:1), gje(nps, 0:1)
      !> Fade of one atom against the strip, point-first
      real(wp) :: gfs(nps), gds(nps), gfp(nps, 0:1), gsp(nps, 5)
      !> Accumulators
      real(wp) :: acc(nps, nacc)
      !> Strip bounding box
      real(wp) :: lo(3), hi(3)
      !> Atom data, box distances and hoisted constants
      real(wp) :: cx, cy, cz, ra, ira, bsq, ex, ey, ez, e2, snear, sfar
      real(wp) :: lam1, lam2, band_end, inv_delta, irab, rsum
      !> Point geometry, inline-exp scalars and plain-jet scalars
      real(wp) :: dx, dy, dz, r2, x, sg, arg, ekf, er, ep, u, e, hu, he, dsx
      !> Fade scalars
      real(wp) :: sr, fs, ft
      !> Pair body: 1 - q, dq/dr, f(q) derivatives, f jet, f x G_B jet
      real(wp) :: pw, pss1, pss2, pss3, pf0, pf1, dp0_1, dp1_1, dp1_2, dp1_3, qj0_1, qj1_1, qj1_2
      real(wp) :: qj1_3
      !> Common subexpressions of one point-atom or point-pair
      real(wp) :: cs0, cs1, cs2, cs3
      !> Point, list and survivor indices
      integer :: p, a, i, j, ia, ib, ns

      if (np < 1 .or. np > nps) error stop &
         "cfc_strip_powersums_o1: np outside 1..strip width"
      if (.not. fade_width > 0.0_wp) error stop &
         "cfc_strip_powersums_o1: fade_width must be positive"
      if (a1 > 0.0_wp .or. a2 > 0.0_wp .or. max(-a1, -a2) > exp_arg_max) error stop &
         "cfc_strip_powersums_o1: exp argument bound exceeded"

      do p = 1, np
         px(p) = points(1, p)
         py(p) = points(2, p)
         pz(p) = points(3, p)
      end do
      lo(1) = minval(px(1:np))
      lo(2) = minval(py(1:np))
      lo(3) = minval(pz(1:np))
      hi(1) = maxval(px(1:np))
      hi(2) = maxval(py(1:np))
      hi(3) = maxval(pz(1:np))
      band_end = fade_start + fade_width
      inv_delta = 1.0_wp/fade_width
      acc(1:np, :) = 0.0_wp
      n_zero = 0
      ns = 0

      ! Atom pass: geometry cache, Cartesian jets, atomic terms
      do a = 1, nat
         cx = centers(1, a)
         cy = centers(2, a)
         cz = centers(3, a)
         ra = radii(a)
         ira = 1.0_wp/ra
         bsq = bound_sq(a)

         ! Nearest and farthest box point, as reduced distances
         ex = max(lo(1) - cx, 0.0_wp, cx - hi(1))
         ey = max(lo(2) - cy, 0.0_wp, cy - hi(2))
         ez = max(lo(3) - cz, 0.0_wp, cz - hi(3))
         e2 = ex*ex + ey*ey + ez*ez
         if (e2*gate_shrink > bsq) cycle
         snear = (sqrt(e2) - ra)*ira
         if (snear >= band_end) cycle
         ex = max(abs(cx - lo(1)), abs(cx - hi(1)))
         ey = max(abs(cy - lo(2)), abs(cy - hi(2)))
         ez = max(abs(cz - lo(3)), abs(cz - hi(3)))
         sfar = (sqrt(ex*ex + ey*ey + ez*ez) - ra)*ira
         ns = ns + 1
         sv(ns) = a
         ! Pair reach: the gate sphere, cut to the band end when that is nearer
         reach(ns) = sqrt(bsq)
         if (band_end < reach(ns)*ira - 1.0_wp) reach(ns) = ra*(1.0_wp + band_end)
         lam1 = a1*ira
         lam2 = a2*ira

         do p = 1, np
            dx = px(p) - cx
            dy = py(p) - cy
            dz = pz(p) - cz
            r2 = dx*dx + dy*dy + dz*dz
            x = sqrt(r2)
            sg = (x - ra)*ira
            arg = max(a2*sg, exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            u = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            arg = max(a1*sg, exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            e = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            geo(p, 1, a) = dx
            geo(p, 2, a) = dy
            geo(p, 3, a) = dz
            geo(p, 4, a) = 1.0_wp/x
            gsg(p) = sg
            gu(p) = u
            ge(p) = e
            gr2(p) = r2
         end do
         ! Hard screening: the gate's own squared compare; a separate loop, as a
         ! select on the exp result lets the compiler sink the exp into a branch
         do p = 1, np
            gu(p) = merge(gu(p), 0.0_wp, gr2(p) <= bsq)
            ge(p) = merge(ge(p), 0.0_wp, gr2(p) <= bsq)
         end do
         n_zero = n_zero + count(gr2(1:np) == 0.0_wp)

         if (sfar <= fade_start) then
            ! Plateau for the whole strip: plain radial jets lam**j u
            do p = 1, np
               hu = gu(p)
               he = ge(p)
               gju(p, 0) = hu
               gje(p, 0) = he
               hu = lam2*hu
               he = lam1*he
               gju(p, 1) = hu
               gje(p, 1) = he
            end do
         else
            ! Strip meets the band: faded radial jets
            do p = 1, np
               sr = (band_end - (gsg(p)))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((gsg(p) - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               gfs(p) = fs
               gds(p) = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               gfp(p, 0) = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               gfp(p, 1) = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               gsp(p, 1) = fs
               gsp(p, 2) = gsp(p, 1)*fs
               gsp(p, 3) = gsp(p, 2)*fs
               gsp(p, 4) = gsp(p, 3)*fs
               gsp(p, 5) = gsp(p, 4)*fs
            end do
            do p = 1, np
               dsx = gds(p)*ira
               cs0 = gfp(p, 0)*gsp(p, 5)
               gju(p, 0) = cs0*gu(p)
               cs1 = dsx*(5.0_wp*gfp(p, 0)*gsp(p, 4) + gfp(p, 1)*gsp(p, 5))
               gju(p, 1) = gu(p)*(cs0*lam2 + cs1)
               gje(p, 0) = cs0*ge(p)
               gje(p, 1) = ge(p)*(cs0*lam1 + cs1)
            end do
         end if

         ! Cartesian jets: pair factor into the cache, atomic term into the sums
         do p = 1, np
            geo(p, 5, a) = gju(p, 0)
            cs2 = gju(p, 1)*geo(p, 4, a)
            geo(p, 6, a) = cs2*geo(p, 1, a)
            geo(p, 7, a) = cs2*geo(p, 2, a)
            geo(p, 8, a) = cs2*geo(p, 3, a)
            acc(p, 1) = acc(p, 1) + (gje(p, 0))
            cs3 = gje(p, 1)*geo(p, 4, a)
            acc(p, 2) = acc(p, 2) + (cs3*geo(p, 1, a))
            acc(p, 3) = acc(p, 3) + (cs3*geo(p, 2, a))
            acc(p, 4) = acc(p, 4) + (cs3*geo(p, 3, a))
         end do
      end do

      ! Pair pass over the survivors, list order
      do i = 1, ns
         ia = sv(i)
         cx = centers(1, ia)
         cy = centers(2, ia)
         cz = centers(3, ia)
         ra = radii(ia)
         do j = i + 1, ns
            ib = sv(j)
            ex = centers(1, ib) - cx
            ey = centers(2, ib) - cy
            ez = centers(3, ib) - cz
            rsum = reach(i) + reach(j)
            if (sqrt(ex*ex + ey*ey + ez*ez)*gate_shrink > rsum) cycle
            irab = 1.0_wp/(ra*radii(ib))
            do p = 1, np
               pw = &
                  -irab*(geo(p, 1, ia)*geo(p, 1, ib) + geo(p, 2, ia)*geo(p, 2, ib) + geo(p, 3, &
                  ia)*geo(p, 3, ib)) + 1.0_wp
               pss1 = irab*(geo(p, 1, ia) + geo(p, 1, ib))
               pss2 = irab*(geo(p, 2, ia) + geo(p, 2, ib))
               pss3 = irab*(geo(p, 3, ia) + geo(p, 3, ib))
               pf0 = c_par*(pw*pw*pw*pw)
               pf1 = -4.0_wp*c_par*(pw*pw*pw)
               dp0_1 = pf0
               dp1_1 = pf1*pss1
               dp1_2 = pf1*pss2
               dp1_3 = pf1*pss3
               qj0_1 = dp0_1*geo(p, 5, ib)
               qj1_1 = dp0_1*geo(p, 6, ib) + dp1_1*geo(p, 5, ib)
               qj1_2 = dp0_1*geo(p, 7, ib) + dp1_2*geo(p, 5, ib)
               qj1_3 = dp0_1*geo(p, 8, ib) + dp1_3*geo(p, 5, ib)
               acc(p, 1) = acc(p, 1) + (geo(p, 5, ia)*qj0_1)
               acc(p, 2) = acc(p, 2) + (geo(p, 5, ia)*qj1_1 + geo(p, 6, ia)*qj0_1)
               acc(p, 3) = acc(p, 3) + (geo(p, 5, ia)*qj1_2 + geo(p, 7, ia)*qj0_1)
               acc(p, 4) = acc(p, 4) + (geo(p, 5, ia)*qj1_3 + geo(p, 8, ia)*qj0_1)
            end do
         end do
      end do

      pd0(:) = acc(1:np, 1)
      pd1(:, 1) = acc(1:np, 2)
      pd1(:, 2) = acc(1:np, 3)
      pd1(:, 3) = acc(1:np, 4)

   end subroutine cfc_strip_powersums_o1

   pure module subroutine cfc_strip_lift_o1(np, pd0, pd1, lsf0, lsf1_r)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(in) :: pd0(np)
      !> Order-1 pseudo-density jet of the strip, point-first; second index the Cartesian component
      real(wp), intent(in) :: pd1(np, 3)
      !> Level-set value S = -log(PD)
      real(wp), intent(out) :: lsf0(np)
      !> Spatial gradient dS/dr
      real(wp), intent(out) :: lsf1_r(3, np)

      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(1)
      !> Reciprocal pseudo-density per point
      real(wp) :: ipd(nps)
      !> Packed results, point-first
      real(wp) :: o1(nps, 3)
      !> Point index
      integer :: p

      if (np < 1 .or. np > nps) error stop &
         "cfc_strip_lift_o1: np outside 1..strip width"

      ! libm log: kept out of the vectorized loops
      do p = 1, np
         lsf0(p) = -log(pd0(p))
      end do

      do p = 1, np
         ipd(p) = 1.0_wp/pd0(p)
      end do

      do p = 1, np
         o1(p, 1) = -ipd(p)*pd1(p, 1)
         o1(p, 2) = -ipd(p)*pd1(p, 2)
         o1(p, 3) = -ipd(p)*pd1(p, 3)
      end do

      do p = 1, np
         lsf1_r(1, p) = o1(p, 1)
         lsf1_r(2, p) = o1(p, 2)
         lsf1_r(3, p) = o1(p, 3)
      end do

   end subroutine cfc_strip_lift_o1

   pure module subroutine cfc_strip_powersums_o2(np, points, nat, centers, radii, bound_sq, a1, a2, &
                                          c_par, fade_start, fade_width, pd0, pd1, pd2, n_zero, &
                                          geo, sv, reach)
      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(2)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Strip points, point-last
      real(wp), intent(in) :: points(3, np)
      !> Atoms in the shared list
      integer, intent(in) :: nat
      !> Atom centers of the shared list
      real(wp), intent(in) :: centers(3, nat)
      !> Atom radii R_a
      real(wp), intent(in) :: radii(nat)
      !> Squared screening reach per atom, the gate's `cand_screen` row
      real(wp), intent(in) :: bound_sq(nat)
      !> Atomic-term exponent a1 (<= 0)
      real(wp), intent(in) :: a1
      !> Pair-term exponent a2 (<= 0)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma_A = ||r - R_A||/R_a - 1; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma_A, finite and > 0
      real(wp), intent(in) :: fade_width
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(out) :: pd0(np)
      !> Order-1 pseudo-density jet of the strip, point-first; second index the Cartesian component
      real(wp), intent(out) :: pd1(np, 3)
      !> Order-2 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-2 tuple
      real(wp), intent(out) :: pd2(np, 6)
      !> Point-atom pairs at zero distance among the evaluated atoms; nonzero means the sums are not
      !> finite
      integer, intent(out) :: n_zero
      !> Point-first geometry cache and pair-pass workspace, one block per list atom (slots in the
      !> routine notes)
      real(wp), intent(out) :: geo(nps, 14, nat)
      !> Survivor workspace: list indices of the atoms kept by the strip classification, leading
      !> entries written
      integer, intent(out) :: sv(nat)
      !> Reach workspace: pair-test radius of each survivor, leading entries written
      real(wp), intent(out) :: reach(nat)

      !> Accumulated columns, one per orbit representative
      integer, parameter :: nacc = 10
      !> Shrink of the strip-level distances in the gate tests (rounding slack)
      real(wp), parameter :: gate_shrink = 1.0_wp - 1e-12_wp
      !> Point-first copy of the strip
      real(wp) :: px(nps), py(nps), pz(nps)
      !> Reduced distance, unfaded factors and squared distance of one atom, point-first
      real(wp) :: gsg(nps), gu(nps), ge(nps), gr2(nps)
      !> Radial jets d^j (w u)/dx^j and d^j (w e)/dx^j of one atom, point-first
      real(wp) :: gju(nps, 0:2), gje(nps, 0:2)
      !> Fade of one atom against the strip, point-first
      real(wp) :: gfs(nps), gds(nps), gfp(nps, 0:2), gsp(nps, 5)
      !> Accumulators
      real(wp) :: acc(nps, nacc)
      !> Strip bounding box
      real(wp) :: lo(3), hi(3)
      !> Atom data, box distances and hoisted constants
      real(wp) :: cx, cy, cz, ra, ira, bsq, ex, ey, ez, e2, snear, sfar
      real(wp) :: lam1, lam2, band_end, inv_delta, irab, rsum
      !> Point geometry, inline-exp scalars and plain-jet scalars
      real(wp) :: dx, dy, dz, r2, x, sg, arg, ekf, er, ep, u, e, hu, he, dsx
      !> Fade scalars
      real(wp) :: sr, fs, ft
      !> Pair body: 1 - q, dq/dr, f(q) derivatives, f jet, f x G_B jet
      real(wp) :: pw, pss1, pss2, pss3, pf0, pf1, pf2, dp0_1, dp1_1, dp1_2, dp1_3, dp2_1, dp2_2
      real(wp) :: dp2_4, dp2_3, dp2_5, dp2_6, qj0_1, qj1_1, qj1_2, qj1_3, qj2_1, qj2_2, qj2_4, qj2_3
      real(wp) :: qj2_5, qj2_6
      !> Common subexpressions of one point-atom or point-pair
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13, cs14
      real(wp) :: cs15, cs16, cs17, cs18, cs19
      !> Point, list and survivor indices
      integer :: p, a, i, j, ia, ib, ns

      if (np < 1 .or. np > nps) error stop &
         "cfc_strip_powersums_o2: np outside 1..strip width"
      if (.not. fade_width > 0.0_wp) error stop &
         "cfc_strip_powersums_o2: fade_width must be positive"
      if (a1 > 0.0_wp .or. a2 > 0.0_wp .or. max(-a1, -a2) > exp_arg_max) error stop &
         "cfc_strip_powersums_o2: exp argument bound exceeded"

      do p = 1, np
         px(p) = points(1, p)
         py(p) = points(2, p)
         pz(p) = points(3, p)
      end do
      lo(1) = minval(px(1:np))
      lo(2) = minval(py(1:np))
      lo(3) = minval(pz(1:np))
      hi(1) = maxval(px(1:np))
      hi(2) = maxval(py(1:np))
      hi(3) = maxval(pz(1:np))
      band_end = fade_start + fade_width
      inv_delta = 1.0_wp/fade_width
      acc(1:np, :) = 0.0_wp
      n_zero = 0
      ns = 0

      ! Atom pass: geometry cache, Cartesian jets, atomic terms
      do a = 1, nat
         cx = centers(1, a)
         cy = centers(2, a)
         cz = centers(3, a)
         ra = radii(a)
         ira = 1.0_wp/ra
         bsq = bound_sq(a)

         ! Nearest and farthest box point, as reduced distances
         ex = max(lo(1) - cx, 0.0_wp, cx - hi(1))
         ey = max(lo(2) - cy, 0.0_wp, cy - hi(2))
         ez = max(lo(3) - cz, 0.0_wp, cz - hi(3))
         e2 = ex*ex + ey*ey + ez*ez
         if (e2*gate_shrink > bsq) cycle
         snear = (sqrt(e2) - ra)*ira
         if (snear >= band_end) cycle
         ex = max(abs(cx - lo(1)), abs(cx - hi(1)))
         ey = max(abs(cy - lo(2)), abs(cy - hi(2)))
         ez = max(abs(cz - lo(3)), abs(cz - hi(3)))
         sfar = (sqrt(ex*ex + ey*ey + ez*ez) - ra)*ira
         ns = ns + 1
         sv(ns) = a
         ! Pair reach: the gate sphere, cut to the band end when that is nearer
         reach(ns) = sqrt(bsq)
         if (band_end < reach(ns)*ira - 1.0_wp) reach(ns) = ra*(1.0_wp + band_end)
         lam1 = a1*ira
         lam2 = a2*ira

         do p = 1, np
            dx = px(p) - cx
            dy = py(p) - cy
            dz = pz(p) - cz
            r2 = dx*dx + dy*dy + dz*dz
            x = sqrt(r2)
            sg = (x - ra)*ira
            arg = max(a2*sg, exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            u = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            arg = max(a1*sg, exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            e = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            geo(p, 1, a) = dx
            geo(p, 2, a) = dy
            geo(p, 3, a) = dz
            geo(p, 4, a) = 1.0_wp/x
            gsg(p) = sg
            gu(p) = u
            ge(p) = e
            gr2(p) = r2
         end do
         ! Hard screening: the gate's own squared compare; a separate loop, as a
         ! select on the exp result lets the compiler sink the exp into a branch
         do p = 1, np
            gu(p) = merge(gu(p), 0.0_wp, gr2(p) <= bsq)
            ge(p) = merge(ge(p), 0.0_wp, gr2(p) <= bsq)
         end do
         n_zero = n_zero + count(gr2(1:np) == 0.0_wp)

         if (sfar <= fade_start) then
            ! Plateau for the whole strip: plain radial jets lam**j u
            do p = 1, np
               hu = gu(p)
               he = ge(p)
               gju(p, 0) = hu
               gje(p, 0) = he
               hu = lam2*hu
               he = lam1*he
               gju(p, 1) = hu
               gje(p, 1) = he
               hu = lam2*hu
               he = lam1*he
               gju(p, 2) = hu
               gje(p, 2) = he
            end do
         else
            ! Strip meets the band: faded radial jets
            do p = 1, np
               sr = (band_end - (gsg(p)))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((gsg(p) - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               gfs(p) = fs
               gds(p) = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               gfp(p, 0) = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               gfp(p, 1) = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               gfp(p, 2) = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               gsp(p, 1) = fs
               gsp(p, 2) = gsp(p, 1)*fs
               gsp(p, 3) = gsp(p, 2)*fs
               gsp(p, 4) = gsp(p, 3)*fs
               gsp(p, 5) = gsp(p, 4)*fs
            end do
            do p = 1, np
               dsx = gds(p)*ira
               cs0 = gfp(p, 0)*gsp(p, 5)
               gju(p, 0) = cs0*gu(p)
               cs1 = dsx*(5.0_wp*gfp(p, 0)*gsp(p, 4) + gfp(p, 1)*gsp(p, 5))
               gju(p, 1) = gu(p)*(cs0*lam2 + cs1)
               cs2 = 2.0_wp*cs1
               cs3 = &
                  (dsx*dsx)*gsp(p, 3)*(20.0_wp*gfp(p, 0) + 10.0_wp*gfp(p, 1)*gfs(p) + gfp(p, &
                  2)*gsp(p, 2))
               gju(p, 2) = gu(p)*(cs0*(lam2*lam2) + cs2*lam2 + cs3)
               gje(p, 0) = cs0*ge(p)
               gje(p, 1) = ge(p)*(cs0*lam1 + cs1)
               gje(p, 2) = ge(p)*(cs0*(lam1*lam1) + cs2*lam1 + cs3)
            end do
         end if

         ! Cartesian jets: pair factor into the cache, atomic term into the sums
         do p = 1, np
            geo(p, 5, a) = gju(p, 0)
            cs4 = gju(p, 1)*geo(p, 4, a)
            geo(p, 6, a) = cs4*geo(p, 1, a)
            geo(p, 7, a) = cs4*geo(p, 2, a)
            geo(p, 8, a) = cs4*geo(p, 3, a)
            cs5 = (geo(p, 1, a)*geo(p, 1, a))
            cs6 = (geo(p, 4, a)*geo(p, 4, a))
            cs7 = cs6*gju(p, 2)
            cs8 = (geo(p, 4, a)*geo(p, 4, a)*geo(p, 4, a))
            cs9 = cs8*gju(p, 1)
            geo(p, 9, a) = cs4 + cs5*cs7 - cs5*cs9
            cs10 = geo(p, 1, a)*geo(p, 2, a)
            geo(p, 10, a) = -cs10*cs9 + cs6*geo(p, 1, a)*geo(p, 2, a)*gju(p, 2)
            cs11 = geo(p, 1, a)*geo(p, 3, a)
            geo(p, 12, a) = -cs11*cs9 + cs6*geo(p, 1, a)*geo(p, 3, a)*gju(p, 2)
            cs12 = (geo(p, 2, a)*geo(p, 2, a))
            geo(p, 11, a) = cs12*cs7 - cs12*cs9 + cs4
            cs13 = geo(p, 2, a)*geo(p, 3, a)
            geo(p, 13, a) = -cs13*cs9 + cs6*geo(p, 2, a)*geo(p, 3, a)*gju(p, 2)
            cs14 = (geo(p, 3, a)*geo(p, 3, a))
            geo(p, 14, a) = cs14*cs7 - cs14*cs9 + cs4
            acc(p, 1) = acc(p, 1) + (gje(p, 0))
            cs15 = gje(p, 1)*geo(p, 4, a)
            acc(p, 2) = acc(p, 2) + (cs15*geo(p, 1, a))
            acc(p, 3) = acc(p, 3) + (cs15*geo(p, 2, a))
            acc(p, 4) = acc(p, 4) + (cs15*geo(p, 3, a))
            cs16 = cs6*gje(p, 2)
            cs17 = cs8*gje(p, 1)
            acc(p, 5) = acc(p, 5) + (cs15 + cs16*cs5 - cs17*cs5)
            acc(p, 6) = acc(p, 6) + (-cs10*cs17 + cs6*geo(p, 1, a)*geo(p, 2, a)*gje(p, 2))
            acc(p, 7) = acc(p, 7) + (-cs11*cs17 + cs6*geo(p, 1, a)*geo(p, 3, a)*gje(p, 2))
            acc(p, 8) = acc(p, 8) + (cs12*cs16 - cs12*cs17 + cs15)
            acc(p, 9) = acc(p, 9) + (-cs13*cs17 + cs6*geo(p, 2, a)*geo(p, 3, a)*gje(p, 2))
            acc(p, 10) = acc(p, 10) + (cs14*cs16 - cs14*cs17 + cs15)
         end do
      end do

      ! Pair pass over the survivors, list order
      do i = 1, ns
         ia = sv(i)
         cx = centers(1, ia)
         cy = centers(2, ia)
         cz = centers(3, ia)
         ra = radii(ia)
         do j = i + 1, ns
            ib = sv(j)
            ex = centers(1, ib) - cx
            ey = centers(2, ib) - cy
            ez = centers(3, ib) - cz
            rsum = reach(i) + reach(j)
            if (sqrt(ex*ex + ey*ey + ez*ez)*gate_shrink > rsum) cycle
            irab = 1.0_wp/(ra*radii(ib))
            do p = 1, np
               pw = &
                  -irab*(geo(p, 1, ia)*geo(p, 1, ib) + geo(p, 2, ia)*geo(p, 2, ib) + geo(p, 3, &
                  ia)*geo(p, 3, ib)) + 1.0_wp
               pss1 = irab*(geo(p, 1, ia) + geo(p, 1, ib))
               pss2 = irab*(geo(p, 2, ia) + geo(p, 2, ib))
               pss3 = irab*(geo(p, 3, ia) + geo(p, 3, ib))
               pf0 = c_par*(pw*pw*pw*pw)
               pf1 = -4.0_wp*c_par*(pw*pw*pw)
               pf2 = 12.0_wp*c_par*(pw*pw)
               dp0_1 = pf0
               dp1_1 = pf1*pss1
               dp1_2 = pf1*pss2
               dp1_3 = pf1*pss3
               cs18 = 2.0_wp*irab*pf1
               dp2_1 = cs18 + pf2*(pss1*pss1)
               cs19 = pf2*pss1
               dp2_2 = cs19*pss2
               dp2_4 = cs19*pss3
               dp2_3 = cs18 + pf2*(pss2*pss2)
               dp2_5 = pf2*pss2*pss3
               dp2_6 = cs18 + pf2*(pss3*pss3)
               qj0_1 = dp0_1*geo(p, 5, ib)
               qj1_1 = dp0_1*geo(p, 6, ib) + dp1_1*geo(p, 5, ib)
               qj1_2 = dp0_1*geo(p, 7, ib) + dp1_2*geo(p, 5, ib)
               qj1_3 = dp0_1*geo(p, 8, ib) + dp1_3*geo(p, 5, ib)
               qj2_1 = dp0_1*geo(p, 9, ib) + 2.0_wp*dp1_1*geo(p, 6, ib) + dp2_1*geo(p, 5, ib)
               qj2_2 = &
                  dp0_1*geo(p, 10, ib) + dp1_1*geo(p, 7, ib) + dp1_2*geo(p, 6, ib) + dp2_2*geo(p, &
                  5, ib)
               qj2_4 = &
                  dp0_1*geo(p, 12, ib) + dp1_1*geo(p, 8, ib) + dp1_3*geo(p, 6, ib) + dp2_4*geo(p, &
                  5, ib)
               qj2_3 = dp0_1*geo(p, 11, ib) + 2.0_wp*dp1_2*geo(p, 7, ib) + dp2_3*geo(p, 5, ib)
               qj2_5 = &
                  dp0_1*geo(p, 13, ib) + dp1_2*geo(p, 8, ib) + dp1_3*geo(p, 7, ib) + dp2_5*geo(p, &
                  5, ib)
               qj2_6 = dp0_1*geo(p, 14, ib) + 2.0_wp*dp1_3*geo(p, 8, ib) + dp2_6*geo(p, 5, ib)
               acc(p, 1) = acc(p, 1) + (geo(p, 5, ia)*qj0_1)
               acc(p, 2) = acc(p, 2) + (geo(p, 5, ia)*qj1_1 + geo(p, 6, ia)*qj0_1)
               acc(p, 3) = acc(p, 3) + (geo(p, 5, ia)*qj1_2 + geo(p, 7, ia)*qj0_1)
               acc(p, 4) = acc(p, 4) + (geo(p, 5, ia)*qj1_3 + geo(p, 8, ia)*qj0_1)
               acc(p, 5) = &
                  acc(p, 5) + (geo(p, 5, ia)*qj2_1 + 2.0_wp*geo(p, 6, ia)*qj1_1 + geo(p, 9, &
                  ia)*qj0_1)
               acc(p, 6) = &
                  acc(p, 6) + (geo(p, 5, ia)*qj2_2 + geo(p, 6, ia)*qj1_2 + geo(p, 7, ia)*qj1_1 + &
                  geo(p, 10, ia)*qj0_1)
               acc(p, 7) = &
                  acc(p, 7) + (geo(p, 5, ia)*qj2_4 + geo(p, 6, ia)*qj1_3 + geo(p, 8, ia)*qj1_1 + &
                  geo(p, 12, ia)*qj0_1)
               acc(p, 8) = &
                  acc(p, 8) + (geo(p, 5, ia)*qj2_3 + 2.0_wp*geo(p, 7, ia)*qj1_2 + geo(p, 11, &
                  ia)*qj0_1)
               acc(p, 9) = &
                  acc(p, 9) + (geo(p, 5, ia)*qj2_5 + geo(p, 7, ia)*qj1_3 + geo(p, 8, ia)*qj1_2 + &
                  geo(p, 13, ia)*qj0_1)
               acc(p, 10) = &
                  acc(p, 10) + (geo(p, 5, ia)*qj2_6 + 2.0_wp*geo(p, 8, ia)*qj1_3 + geo(p, 14, &
                  ia)*qj0_1)
            end do
         end do
      end do

      pd0(:) = acc(1:np, 1)
      pd1(:, 1) = acc(1:np, 2)
      pd1(:, 2) = acc(1:np, 3)
      pd1(:, 3) = acc(1:np, 4)
      pd2(:, 1) = acc(1:np, 5)
      pd2(:, 2) = acc(1:np, 6)
      pd2(:, 4) = acc(1:np, 7)
      pd2(:, 3) = acc(1:np, 8)
      pd2(:, 5) = acc(1:np, 9)
      pd2(:, 6) = acc(1:np, 10)

   end subroutine cfc_strip_powersums_o2

   pure module subroutine cfc_strip_lift_o2(np, pd0, pd1, pd2, lsf0, lsf1_r, lsf2_rr)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(in) :: pd0(np)
      !> Order-1 pseudo-density jet of the strip, point-first; second index the Cartesian component
      real(wp), intent(in) :: pd1(np, 3)
      !> Order-2 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-2 tuple
      real(wp), intent(in) :: pd2(np, 6)
      !> Level-set value S = -log(PD)
      real(wp), intent(out) :: lsf0(np)
      !> Spatial gradient dS/dr
      real(wp), intent(out) :: lsf1_r(3, np)
      !> Spatial Hessian, packed (6)
      real(wp), intent(out) :: lsf2_rr(6, np)

      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(2)
      !> Reciprocal pseudo-density per point
      real(wp) :: ipd(nps)
      !> Packed results, point-first
      real(wp) :: o1(nps, 3), o2(nps, 6)
      !> Common subexpressions of one point
      real(wp) :: cs0, cs1
      !> Point index
      integer :: p

      if (np < 1 .or. np > nps) error stop &
         "cfc_strip_lift_o2: np outside 1..strip width"

      ! libm log: kept out of the vectorized loops
      do p = 1, np
         lsf0(p) = -log(pd0(p))
      end do

      do p = 1, np
         ipd(p) = 1.0_wp/pd0(p)
      end do

      do p = 1, np
         cs0 = (ipd(p)*ipd(p))
         cs1 = cs0*pd1(p, 1)
         o1(p, 1) = -ipd(p)*pd1(p, 1)
         o1(p, 2) = -ipd(p)*pd1(p, 2)
         o1(p, 3) = -ipd(p)*pd1(p, 3)
         o2(p, 1) = cs0*(pd1(p, 1)*pd1(p, 1)) - ipd(p)*pd2(p, 1)
         o2(p, 2) = cs1*pd1(p, 2) - ipd(p)*pd2(p, 2)
         o2(p, 4) = cs1*pd1(p, 3) - ipd(p)*pd2(p, 4)
         o2(p, 3) = cs0*(pd1(p, 2)*pd1(p, 2)) - ipd(p)*pd2(p, 3)
         o2(p, 5) = cs0*pd1(p, 2)*pd1(p, 3) - ipd(p)*pd2(p, 5)
         o2(p, 6) = cs0*(pd1(p, 3)*pd1(p, 3)) - ipd(p)*pd2(p, 6)
      end do

      do p = 1, np
         lsf1_r(1, p) = o1(p, 1)
         lsf1_r(2, p) = o1(p, 2)
         lsf1_r(3, p) = o1(p, 3)
         lsf2_rr(1, p) = o2(p, 1)
         lsf2_rr(2, p) = o2(p, 2)
         lsf2_rr(3, p) = o2(p, 3)
         lsf2_rr(4, p) = o2(p, 4)
         lsf2_rr(5, p) = o2(p, 5)
         lsf2_rr(6, p) = o2(p, 6)
      end do

   end subroutine cfc_strip_lift_o2

   pure module subroutine cfc_strip_powersums_o3(np, points, nat, centers, radii, bound_sq, a1, a2, &
                                          c_par, fade_start, fade_width, pd0, pd1, pd2, pd3, &
                                          n_zero, geo, sv, reach)
      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(3)
      !> Live points in the strip, 1..16
      integer, intent(in) :: np
      !> Strip points, point-last
      real(wp), intent(in) :: points(3, np)
      !> Atoms in the shared list
      integer, intent(in) :: nat
      !> Atom centers of the shared list
      real(wp), intent(in) :: centers(3, nat)
      !> Atom radii R_a
      real(wp), intent(in) :: radii(nat)
      !> Squared screening reach per atom, the gate's `cand_screen` row
      real(wp), intent(in) :: bound_sq(nat)
      !> Atomic-term exponent a1 (<= 0)
      real(wp), intent(in) :: a1
      !> Pair-term exponent a2 (<= 0)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma_A = ||r - R_A||/R_a - 1; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma_A, finite and > 0
      real(wp), intent(in) :: fade_width
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(out) :: pd0(np)
      !> Order-1 pseudo-density jet of the strip, point-first; second index the Cartesian component
      real(wp), intent(out) :: pd1(np, 3)
      !> Order-2 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-2 tuple
      real(wp), intent(out) :: pd2(np, 6)
      !> Order-3 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-3 tuple
      real(wp), intent(out) :: pd3(np, 10)
      !> Point-atom pairs at zero distance among the evaluated atoms; nonzero means the sums are not
      !> finite
      integer, intent(out) :: n_zero
      !> Point-first geometry cache and pair-pass workspace, one block per list atom (slots in the
      !> routine notes)
      real(wp), intent(out) :: geo(nps, 24, nat)
      !> Survivor workspace: list indices of the atoms kept by the strip classification, leading
      !> entries written
      integer, intent(out) :: sv(nat)
      !> Reach workspace: pair-test radius of each survivor, leading entries written
      real(wp), intent(out) :: reach(nat)

      !> Accumulated columns, one per orbit representative
      integer, parameter :: nacc = 20
      !> Shrink of the strip-level distances in the gate tests (rounding slack)
      real(wp), parameter :: gate_shrink = 1.0_wp - 1e-12_wp
      !> Point-first copy of the strip
      real(wp) :: px(nps), py(nps), pz(nps)
      !> Reduced distance, unfaded factors and squared distance of one atom, point-first
      real(wp) :: gsg(nps), gu(nps), ge(nps), gr2(nps)
      !> Radial jets d^j (w u)/dx^j and d^j (w e)/dx^j of one atom, point-first
      real(wp) :: gju(nps, 0:3), gje(nps, 0:3)
      !> Fade of one atom against the strip, point-first
      real(wp) :: gfs(nps), gds(nps), gfp(nps, 0:3), gsp(nps, 5)
      !> Accumulators
      real(wp) :: acc(nps, nacc)
      !> Strip bounding box
      real(wp) :: lo(3), hi(3)
      !> Atom data, box distances and hoisted constants
      real(wp) :: cx, cy, cz, ra, ira, bsq, ex, ey, ez, e2, snear, sfar
      real(wp) :: lam1, lam2, band_end, inv_delta, irab, rsum
      !> Point geometry, inline-exp scalars and plain-jet scalars
      real(wp) :: dx, dy, dz, r2, x, sg, arg, ekf, er, ep, u, e, hu, he, dsx
      !> Fade scalars
      real(wp) :: sr, fs, ft
      !> Pair body: 1 - q, dq/dr, f(q) derivatives, f jet, f x G_B jet
      real(wp) :: pw, pss1, pss2, pss3, pf0, pf1, pf2, pf3, dp0_1, dp1_1, dp1_2, dp1_3, dp2_1, dp2_2
      real(wp) :: dp2_4, dp2_3, dp2_5, dp2_6, dp3_1, dp3_2, dp3_5, dp3_3, dp3_6, dp3_8, dp3_4, dp3_7
      real(wp) :: dp3_9, dp3_10, qj0_1, qj1_1, qj1_2, qj1_3, qj2_1, qj2_2, qj2_4, qj2_3, qj2_5
      real(wp) :: qj2_6, qj3_1, qj3_2, qj3_5, qj3_3, qj3_6, qj3_8, qj3_4, qj3_7, qj3_9, qj3_10
      !> Common subexpressions of one point-atom or point-pair
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13, cs14
      real(wp) :: cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26, cs27, cs28
      real(wp) :: cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39, cs40, cs41, cs42
      real(wp) :: cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52, cs53, cs54, cs55, cs56
      real(wp) :: cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65, cs66, cs67, cs68, cs69, cs70
      real(wp) :: cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78, cs79, cs80, cs81, cs82, cs83, cs84
      real(wp) :: cs85, cs86, cs87, cs88, cs89, cs90, cs91, cs92, cs93, cs94, cs95
      !> Point, list and survivor indices
      integer :: p, a, i, j, ia, ib, ns

      if (np < 1 .or. np > nps) error stop &
         "cfc_strip_powersums_o3: np outside 1..strip width"
      if (.not. fade_width > 0.0_wp) error stop &
         "cfc_strip_powersums_o3: fade_width must be positive"
      if (a1 > 0.0_wp .or. a2 > 0.0_wp .or. max(-a1, -a2) > exp_arg_max) error stop &
         "cfc_strip_powersums_o3: exp argument bound exceeded"

      do p = 1, np
         px(p) = points(1, p)
         py(p) = points(2, p)
         pz(p) = points(3, p)
      end do
      lo(1) = minval(px(1:np))
      lo(2) = minval(py(1:np))
      lo(3) = minval(pz(1:np))
      hi(1) = maxval(px(1:np))
      hi(2) = maxval(py(1:np))
      hi(3) = maxval(pz(1:np))
      band_end = fade_start + fade_width
      inv_delta = 1.0_wp/fade_width
      acc(1:np, :) = 0.0_wp
      n_zero = 0
      ns = 0

      ! Atom pass: geometry cache, Cartesian jets, atomic terms
      do a = 1, nat
         cx = centers(1, a)
         cy = centers(2, a)
         cz = centers(3, a)
         ra = radii(a)
         ira = 1.0_wp/ra
         bsq = bound_sq(a)

         ! Nearest and farthest box point, as reduced distances
         ex = max(lo(1) - cx, 0.0_wp, cx - hi(1))
         ey = max(lo(2) - cy, 0.0_wp, cy - hi(2))
         ez = max(lo(3) - cz, 0.0_wp, cz - hi(3))
         e2 = ex*ex + ey*ey + ez*ez
         if (e2*gate_shrink > bsq) cycle
         snear = (sqrt(e2) - ra)*ira
         if (snear >= band_end) cycle
         ex = max(abs(cx - lo(1)), abs(cx - hi(1)))
         ey = max(abs(cy - lo(2)), abs(cy - hi(2)))
         ez = max(abs(cz - lo(3)), abs(cz - hi(3)))
         sfar = (sqrt(ex*ex + ey*ey + ez*ez) - ra)*ira
         ns = ns + 1
         sv(ns) = a
         ! Pair reach: the gate sphere, cut to the band end when that is nearer
         reach(ns) = sqrt(bsq)
         if (band_end < reach(ns)*ira - 1.0_wp) reach(ns) = ra*(1.0_wp + band_end)
         lam1 = a1*ira
         lam2 = a2*ira

         do p = 1, np
            dx = px(p) - cx
            dy = py(p) - cy
            dz = pz(p) - cz
            r2 = dx*dx + dy*dy + dz*dz
            x = sqrt(r2)
            sg = (x - ra)*ira
            arg = max(a2*sg, exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            u = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            arg = max(a1*sg, exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            e = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            geo(p, 1, a) = dx
            geo(p, 2, a) = dy
            geo(p, 3, a) = dz
            geo(p, 4, a) = 1.0_wp/x
            gsg(p) = sg
            gu(p) = u
            ge(p) = e
            gr2(p) = r2
         end do
         ! Hard screening: the gate's own squared compare; a separate loop, as a
         ! select on the exp result lets the compiler sink the exp into a branch
         do p = 1, np
            gu(p) = merge(gu(p), 0.0_wp, gr2(p) <= bsq)
            ge(p) = merge(ge(p), 0.0_wp, gr2(p) <= bsq)
         end do
         n_zero = n_zero + count(gr2(1:np) == 0.0_wp)

         if (sfar <= fade_start) then
            ! Plateau for the whole strip: plain radial jets lam**j u
            do p = 1, np
               hu = gu(p)
               he = ge(p)
               gju(p, 0) = hu
               gje(p, 0) = he
               hu = lam2*hu
               he = lam1*he
               gju(p, 1) = hu
               gje(p, 1) = he
               hu = lam2*hu
               he = lam1*he
               gju(p, 2) = hu
               gje(p, 2) = he
               hu = lam2*hu
               he = lam1*he
               gju(p, 3) = hu
               gje(p, 3) = he
            end do
         else
            ! Strip meets the band: faded radial jets
            do p = 1, np
               sr = (band_end - (gsg(p)))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((gsg(p) - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               gfs(p) = fs
               gds(p) = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               gfp(p, 0) = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               gfp(p, 1) = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               gfp(p, 2) = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               gfp(p, 3) = -1680.0_wp*ft - 210.0_wp
               gsp(p, 1) = fs
               gsp(p, 2) = gsp(p, 1)*fs
               gsp(p, 3) = gsp(p, 2)*fs
               gsp(p, 4) = gsp(p, 3)*fs
               gsp(p, 5) = gsp(p, 4)*fs
            end do
            do p = 1, np
               dsx = gds(p)*ira
               cs0 = gfp(p, 0)*gsp(p, 5)
               gju(p, 0) = cs0*gu(p)
               cs1 = dsx*(5.0_wp*gfp(p, 0)*gsp(p, 4) + gfp(p, 1)*gsp(p, 5))
               gju(p, 1) = gu(p)*(cs0*lam2 + cs1)
               cs2 = (lam2*lam2)
               cs3 = 2.0_wp*cs1
               cs4 = gfp(p, 2)*gsp(p, 2)
               cs5 = gfp(p, 1)*gfs(p)
               cs6 = (dsx*dsx)*gsp(p, 3)*(cs4 + 10.0_wp*cs5 + 20.0_wp*gfp(p, 0))
               gju(p, 2) = gu(p)*(cs0*cs2 + cs3*lam2 + cs6)
               cs7 = 3.0_wp*cs1
               cs8 = 3.0_wp*cs6
               cs9 = &
                  (dsx*dsx*dsx)*gsp(p, 2)*(15.0_wp*cs4 + 60.0_wp*cs5 + 60.0_wp*gfp(p, 0) + gfp(p, &
                  3)*gsp(p, 3))
               gju(p, 3) = gu(p)*(cs0*(lam2*lam2*lam2) + cs2*cs7 + cs8*lam2 + cs9)
               gje(p, 0) = cs0*ge(p)
               gje(p, 1) = ge(p)*(cs0*lam1 + cs1)
               cs10 = (lam1*lam1)
               gje(p, 2) = ge(p)*(cs0*cs10 + cs3*lam1 + cs6)
               gje(p, 3) = ge(p)*(cs0*(lam1*lam1*lam1) + cs10*cs7 + cs8*lam1 + cs9)
            end do
         end if

         ! Cartesian jets: pair factor into the cache, atomic term into the sums
         do p = 1, np
            geo(p, 5, a) = gju(p, 0)
            cs11 = gju(p, 1)*geo(p, 4, a)
            geo(p, 6, a) = cs11*geo(p, 1, a)
            geo(p, 7, a) = cs11*geo(p, 2, a)
            geo(p, 8, a) = cs11*geo(p, 3, a)
            cs12 = (geo(p, 1, a)*geo(p, 1, a))
            cs13 = (geo(p, 4, a)*geo(p, 4, a))
            cs14 = cs13*gju(p, 2)
            cs15 = (geo(p, 4, a)*geo(p, 4, a)*geo(p, 4, a))
            cs16 = cs15*gju(p, 1)
            geo(p, 9, a) = cs11 + cs12*cs14 - cs12*cs16
            cs17 = cs16*geo(p, 2, a)
            geo(p, 10, a) = cs13*geo(p, 1, a)*geo(p, 2, a)*gju(p, 2) - cs17*geo(p, 1, a)
            cs18 = cs16*geo(p, 3, a)
            geo(p, 12, a) = cs13*geo(p, 1, a)*geo(p, 3, a)*gju(p, 2) - cs18*geo(p, 1, a)
            cs19 = (geo(p, 2, a)*geo(p, 2, a))
            geo(p, 11, a) = cs11 + cs14*cs19 - cs16*cs19
            geo(p, 13, a) = cs13*geo(p, 2, a)*geo(p, 3, a)*gju(p, 2) - cs17*geo(p, 3, a)
            cs20 = (geo(p, 3, a)*geo(p, 3, a))
            geo(p, 14, a) = cs11 + cs14*cs20 - cs16*cs20
            cs21 = cs16*geo(p, 1, a)
            cs22 = cs14*geo(p, 1, a)
            cs23 = (geo(p, 1, a)*geo(p, 1, a)*geo(p, 1, a))
            cs24 = cs15*gju(p, 3)
            cs25 = 3.0_wp*cs23
            cs26 = (geo(p, 4, a)*geo(p, 4, a)*geo(p, 4, a)*geo(p, 4, a)*geo(p, 4, a))
            cs27 = cs26*gju(p, 1)
            cs28 = (geo(p, 4, a)*geo(p, 4, a)*geo(p, 4, a)*geo(p, 4, a))
            cs29 = cs28*gju(p, 2)
            geo(p, 15, a) = -3.0_wp*cs21 + 3.0_wp*cs22 + cs23*cs24 + cs25*cs27 - cs25*cs29
            cs30 = cs12*cs24
            cs31 = 3.0_wp*cs12
            cs32 = cs31*geo(p, 2, a)
            cs33 = cs14*geo(p, 2, a)
            cs34 = -cs17 + cs33
            geo(p, 16, a) = cs27*cs32 - cs29*cs32 + cs30*geo(p, 2, a) + cs34
            cs35 = cs31*geo(p, 3, a)
            cs36 = cs14*geo(p, 3, a)
            cs37 = -cs18 + cs36
            geo(p, 19, a) = cs27*cs35 - cs29*cs35 + cs30*geo(p, 3, a) + cs37
            cs38 = cs24*geo(p, 1, a)
            cs39 = 3.0_wp*geo(p, 1, a)
            cs40 = cs19*cs39
            cs41 = -cs21 + cs22
            geo(p, 17, a) = cs19*cs38 + cs27*cs40 - cs29*cs40 + cs41
            cs42 = geo(p, 2, a)*geo(p, 3, a)
            cs43 = cs39*cs42
            geo(p, 20, a) = cs27*cs43 - cs29*cs43 + cs38*cs42
            cs44 = cs20*cs39
            geo(p, 22, a) = cs20*cs38 + cs27*cs44 - cs29*cs44 + cs41
            cs45 = (geo(p, 2, a)*geo(p, 2, a)*geo(p, 2, a))
            cs46 = 3.0_wp*cs45
            geo(p, 18, a) = -3.0_wp*cs17 + cs24*cs45 + cs27*cs46 - cs29*cs46 + 3.0_wp*cs33
            cs47 = cs19*geo(p, 3, a)
            cs48 = 3.0_wp*cs47
            geo(p, 21, a) = cs24*cs47 + cs27*cs48 - cs29*cs48 + cs37
            cs49 = cs20*geo(p, 2, a)
            cs50 = 3.0_wp*cs49
            geo(p, 23, a) = cs24*cs49 + cs27*cs50 - cs29*cs50 + cs34
            cs51 = (geo(p, 3, a)*geo(p, 3, a)*geo(p, 3, a))
            cs52 = 3.0_wp*cs51
            geo(p, 24, a) = -3.0_wp*cs18 + cs24*cs51 + cs27*cs52 - cs29*cs52 + 3.0_wp*cs36
            acc(p, 1) = acc(p, 1) + (gje(p, 0))
            cs53 = gje(p, 1)*geo(p, 4, a)
            acc(p, 2) = acc(p, 2) + (cs53*geo(p, 1, a))
            acc(p, 3) = acc(p, 3) + (cs53*geo(p, 2, a))
            acc(p, 4) = acc(p, 4) + (cs53*geo(p, 3, a))
            cs54 = cs13*gje(p, 2)
            cs55 = cs15*gje(p, 1)
            acc(p, 5) = acc(p, 5) + (cs12*cs54 - cs12*cs55 + cs53)
            cs56 = cs55*geo(p, 2, a)
            acc(p, 6) = acc(p, 6) + (cs13*geo(p, 1, a)*geo(p, 2, a)*gje(p, 2) - cs56*geo(p, 1, a))
            cs57 = cs55*geo(p, 3, a)
            acc(p, 7) = acc(p, 7) + (cs13*geo(p, 1, a)*geo(p, 3, a)*gje(p, 2) - cs57*geo(p, 1, a))
            acc(p, 8) = acc(p, 8) + (cs19*cs54 - cs19*cs55 + cs53)
            acc(p, 9) = acc(p, 9) + (cs13*geo(p, 2, a)*geo(p, 3, a)*gje(p, 2) - cs56*geo(p, 3, a))
            acc(p, 10) = acc(p, 10) + (cs20*cs54 - cs20*cs55 + cs53)
            cs58 = cs55*geo(p, 1, a)
            cs59 = cs54*geo(p, 1, a)
            cs60 = cs15*gje(p, 3)
            cs61 = cs26*gje(p, 1)
            cs62 = cs28*gje(p, 2)
            acc(p, 11) = &
               acc(p, 11) + (cs23*cs60 + cs25*cs61 - cs25*cs62 - 3.0_wp*cs58 + 3.0_wp*cs59)
            cs63 = cs12*cs60
            cs64 = cs54*geo(p, 2, a)
            cs65 = -cs56 + cs64
            acc(p, 12) = acc(p, 12) + (cs32*cs61 - cs32*cs62 + cs63*geo(p, 2, a) + cs65)
            cs66 = cs54*geo(p, 3, a)
            cs67 = -cs57 + cs66
            acc(p, 13) = acc(p, 13) + (cs35*cs61 - cs35*cs62 + cs63*geo(p, 3, a) + cs67)
            cs68 = cs60*geo(p, 1, a)
            cs69 = -cs58 + cs59
            acc(p, 14) = acc(p, 14) + (cs19*cs68 + cs40*cs61 - cs40*cs62 + cs69)
            acc(p, 15) = acc(p, 15) + (cs42*cs68 + cs43*cs61 - cs43*cs62)
            acc(p, 16) = acc(p, 16) + (cs20*cs68 + cs44*cs61 - cs44*cs62 + cs69)
            acc(p, 17) = &
               acc(p, 17) + (cs45*cs60 + cs46*cs61 - cs46*cs62 - 3.0_wp*cs56 + 3.0_wp*cs64)
            acc(p, 18) = acc(p, 18) + (cs47*cs60 + cs48*cs61 - cs48*cs62 + cs67)
            acc(p, 19) = acc(p, 19) + (cs49*cs60 + cs50*cs61 - cs50*cs62 + cs65)
            acc(p, 20) = &
               acc(p, 20) + (cs51*cs60 + cs52*cs61 - cs52*cs62 - 3.0_wp*cs57 + 3.0_wp*cs66)
         end do
      end do

      ! Pair pass over the survivors, list order
      do i = 1, ns
         ia = sv(i)
         cx = centers(1, ia)
         cy = centers(2, ia)
         cz = centers(3, ia)
         ra = radii(ia)
         do j = i + 1, ns
            ib = sv(j)
            ex = centers(1, ib) - cx
            ey = centers(2, ib) - cy
            ez = centers(3, ib) - cz
            rsum = reach(i) + reach(j)
            if (sqrt(ex*ex + ey*ey + ez*ez)*gate_shrink > rsum) cycle
            irab = 1.0_wp/(ra*radii(ib))
            do p = 1, np
               pw = &
                  -irab*(geo(p, 1, ia)*geo(p, 1, ib) + geo(p, 2, ia)*geo(p, 2, ib) + geo(p, 3, &
                  ia)*geo(p, 3, ib)) + 1.0_wp
               pss1 = irab*(geo(p, 1, ia) + geo(p, 1, ib))
               pss2 = irab*(geo(p, 2, ia) + geo(p, 2, ib))
               pss3 = irab*(geo(p, 3, ia) + geo(p, 3, ib))
               pf0 = c_par*(pw*pw*pw*pw)
               pf1 = -4.0_wp*c_par*(pw*pw*pw)
               pf2 = 12.0_wp*c_par*(pw*pw)
               pf3 = -24.0_wp*c_par*pw
               dp0_1 = pf0
               dp1_1 = pf1*pss1
               dp1_2 = pf1*pss2
               dp1_3 = pf1*pss3
               cs70 = 2.0_wp*irab
               cs71 = cs70*pf1
               cs72 = (pss1*pss1)
               dp2_1 = cs71 + cs72*pf2
               cs73 = pf2*pss1
               dp2_2 = cs73*pss2
               dp2_4 = cs73*pss3
               cs74 = (pss2*pss2)
               dp2_3 = cs71 + cs74*pf2
               cs75 = pf2*pss2
               dp2_5 = cs75*pss3
               cs76 = (pss3*pss3)
               dp2_6 = cs71 + cs76*pf2
               cs77 = 6.0_wp*irab
               dp3_1 = cs73*cs77 + pf3*(pss1*pss1*pss1)
               cs78 = cs70*cs75
               cs79 = cs72*pf3
               dp3_2 = cs78 + cs79*pss2
               cs80 = pf2*pss3
               cs81 = cs70*cs80
               dp3_5 = cs79*pss3 + cs81
               cs82 = cs70*cs73
               cs83 = pf3*pss1
               dp3_3 = cs74*cs83 + cs82
               dp3_6 = cs83*pss2*pss3
               dp3_8 = cs76*cs83 + cs82
               dp3_4 = cs75*cs77 + pf3*(pss2*pss2*pss2)
               dp3_7 = cs74*pf3*pss3 + cs81
               dp3_9 = cs76*pf3*pss2 + cs78
               dp3_10 = cs77*cs80 + pf3*(pss3*pss3*pss3)
               qj0_1 = dp0_1*geo(p, 5, ib)
               qj1_1 = dp0_1*geo(p, 6, ib) + dp1_1*geo(p, 5, ib)
               qj1_2 = dp0_1*geo(p, 7, ib) + dp1_2*geo(p, 5, ib)
               qj1_3 = dp0_1*geo(p, 8, ib) + dp1_3*geo(p, 5, ib)
               cs84 = 2.0_wp*dp1_1
               qj2_1 = cs84*geo(p, 6, ib) + dp0_1*geo(p, 9, ib) + dp2_1*geo(p, 5, ib)
               qj2_2 = &
                  dp0_1*geo(p, 10, ib) + dp1_1*geo(p, 7, ib) + dp1_2*geo(p, 6, ib) + dp2_2*geo(p, &
                  5, ib)
               qj2_4 = &
                  dp0_1*geo(p, 12, ib) + dp1_1*geo(p, 8, ib) + dp1_3*geo(p, 6, ib) + dp2_4*geo(p, &
                  5, ib)
               cs85 = 2.0_wp*dp1_2
               qj2_3 = cs85*geo(p, 7, ib) + dp0_1*geo(p, 11, ib) + dp2_3*geo(p, 5, ib)
               qj2_5 = &
                  dp0_1*geo(p, 13, ib) + dp1_2*geo(p, 8, ib) + dp1_3*geo(p, 7, ib) + dp2_5*geo(p, &
                  5, ib)
               cs86 = 2.0_wp*dp1_3
               qj2_6 = cs86*geo(p, 8, ib) + dp0_1*geo(p, 14, ib) + dp2_6*geo(p, 5, ib)
               qj3_1 = &
                  dp0_1*geo(p, 15, ib) + 3.0_wp*dp1_1*geo(p, 9, ib) + 3.0_wp*dp2_1*geo(p, 6, ib) + &
                  dp3_1*geo(p, 5, ib)
               cs87 = 2.0_wp*geo(p, 6, ib)
               qj3_2 = &
                  cs84*geo(p, 10, ib) + cs87*dp2_2 + dp0_1*geo(p, 16, ib) + dp1_2*geo(p, 9, ib) + &
                  dp2_1*geo(p, 7, ib) + dp3_2*geo(p, 5, ib)
               qj3_5 = &
                  cs84*geo(p, 12, ib) + cs87*dp2_4 + dp0_1*geo(p, 19, ib) + dp1_3*geo(p, 9, ib) + &
                  dp2_1*geo(p, 8, ib) + dp3_5*geo(p, 5, ib)
               cs88 = 2.0_wp*geo(p, 7, ib)
               qj3_3 = &
                  cs85*geo(p, 10, ib) + cs88*dp2_2 + dp0_1*geo(p, 17, ib) + dp1_1*geo(p, 11, ib) + &
                  dp2_3*geo(p, 6, ib) + dp3_3*geo(p, 5, ib)
               qj3_6 = &
                  dp0_1*geo(p, 20, ib) + dp1_1*geo(p, 13, ib) + dp1_2*geo(p, 12, ib) + &
                  dp1_3*geo(p, 10, ib) + dp2_2*geo(p, 8, ib) + dp2_4*geo(p, 7, ib) + dp2_5*geo(p, &
                  6, ib) + dp3_6*geo(p, 5, ib)
               cs89 = 2.0_wp*geo(p, 8, ib)
               qj3_8 = &
                  cs86*geo(p, 12, ib) + cs89*dp2_4 + dp0_1*geo(p, 22, ib) + dp1_1*geo(p, 14, ib) + &
                  dp2_6*geo(p, 6, ib) + dp3_8*geo(p, 5, ib)
               qj3_4 = &
                  dp0_1*geo(p, 18, ib) + 3.0_wp*dp1_2*geo(p, 11, ib) + 3.0_wp*dp2_3*geo(p, 7, ib) &
                  + dp3_4*geo(p, 5, ib)
               qj3_7 = &
                  cs85*geo(p, 13, ib) + cs88*dp2_5 + dp0_1*geo(p, 21, ib) + dp1_3*geo(p, 11, ib) + &
                  dp2_3*geo(p, 8, ib) + dp3_7*geo(p, 5, ib)
               qj3_9 = &
                  cs86*geo(p, 13, ib) + cs89*dp2_5 + dp0_1*geo(p, 23, ib) + dp1_2*geo(p, 14, ib) + &
                  dp2_6*geo(p, 7, ib) + dp3_9*geo(p, 5, ib)
               qj3_10 = &
                  dp0_1*geo(p, 24, ib) + 3.0_wp*dp1_3*geo(p, 14, ib) + 3.0_wp*dp2_6*geo(p, 8, ib) &
                  + dp3_10*geo(p, 5, ib)
               acc(p, 1) = acc(p, 1) + (geo(p, 5, ia)*qj0_1)
               acc(p, 2) = acc(p, 2) + (geo(p, 5, ia)*qj1_1 + geo(p, 6, ia)*qj0_1)
               acc(p, 3) = acc(p, 3) + (geo(p, 5, ia)*qj1_2 + geo(p, 7, ia)*qj0_1)
               acc(p, 4) = acc(p, 4) + (geo(p, 5, ia)*qj1_3 + geo(p, 8, ia)*qj0_1)
               cs90 = 2.0_wp*geo(p, 6, ia)
               acc(p, 5) = acc(p, 5) + (cs90*qj1_1 + geo(p, 5, ia)*qj2_1 + geo(p, 9, ia)*qj0_1)
               acc(p, 6) = &
                  acc(p, 6) + (geo(p, 5, ia)*qj2_2 + geo(p, 6, ia)*qj1_2 + geo(p, 7, ia)*qj1_1 + &
                  geo(p, 10, ia)*qj0_1)
               acc(p, 7) = &
                  acc(p, 7) + (geo(p, 5, ia)*qj2_4 + geo(p, 6, ia)*qj1_3 + geo(p, 8, ia)*qj1_1 + &
                  geo(p, 12, ia)*qj0_1)
               cs91 = 2.0_wp*geo(p, 7, ia)
               acc(p, 8) = acc(p, 8) + (cs91*qj1_2 + geo(p, 5, ia)*qj2_3 + geo(p, 11, ia)*qj0_1)
               acc(p, 9) = &
                  acc(p, 9) + (geo(p, 5, ia)*qj2_5 + geo(p, 7, ia)*qj1_3 + geo(p, 8, ia)*qj1_2 + &
                  geo(p, 13, ia)*qj0_1)
               cs92 = 2.0_wp*geo(p, 8, ia)
               acc(p, 10) = acc(p, 10) + (cs92*qj1_3 + geo(p, 5, ia)*qj2_6 + geo(p, 14, ia)*qj0_1)
               acc(p, 11) = &
                  acc(p, 11) + (geo(p, 5, ia)*qj3_1 + 3.0_wp*geo(p, 6, ia)*qj2_1 + 3.0_wp*geo(p, &
                  9, ia)*qj1_1 + geo(p, 15, ia)*qj0_1)
               cs93 = 2.0_wp*qj1_1
               acc(p, 12) = &
                  acc(p, 12) + (cs90*qj2_2 + cs93*geo(p, 10, ia) + geo(p, 5, ia)*qj3_2 + geo(p, 7, &
                  ia)*qj2_1 + geo(p, 9, ia)*qj1_2 + geo(p, 16, ia)*qj0_1)
               acc(p, 13) = &
                  acc(p, 13) + (cs90*qj2_4 + cs93*geo(p, 12, ia) + geo(p, 5, ia)*qj3_5 + geo(p, 8, &
                  ia)*qj2_1 + geo(p, 9, ia)*qj1_3 + geo(p, 19, ia)*qj0_1)
               cs94 = 2.0_wp*qj1_2
               acc(p, 14) = &
                  acc(p, 14) + (cs91*qj2_2 + cs94*geo(p, 10, ia) + geo(p, 5, ia)*qj3_3 + geo(p, 6, &
                  ia)*qj2_3 + geo(p, 11, ia)*qj1_1 + geo(p, 17, ia)*qj0_1)
               acc(p, 15) = &
                  acc(p, 15) + (geo(p, 5, ia)*qj3_6 + geo(p, 6, ia)*qj2_5 + geo(p, 7, ia)*qj2_4 + &
                  geo(p, 8, ia)*qj2_2 + geo(p, 10, ia)*qj1_3 + geo(p, 12, ia)*qj1_2 + geo(p, 13, &
                  ia)*qj1_1 + geo(p, 20, ia)*qj0_1)
               cs95 = 2.0_wp*qj1_3
               acc(p, 16) = &
                  acc(p, 16) + (cs92*qj2_4 + cs95*geo(p, 12, ia) + geo(p, 5, ia)*qj3_8 + geo(p, 6, &
                  ia)*qj2_6 + geo(p, 14, ia)*qj1_1 + geo(p, 22, ia)*qj0_1)
               acc(p, 17) = &
                  acc(p, 17) + (geo(p, 5, ia)*qj3_4 + 3.0_wp*geo(p, 7, ia)*qj2_3 + 3.0_wp*geo(p, &
                  11, ia)*qj1_2 + geo(p, 18, ia)*qj0_1)
               acc(p, 18) = &
                  acc(p, 18) + (cs91*qj2_5 + cs94*geo(p, 13, ia) + geo(p, 5, ia)*qj3_7 + geo(p, 8, &
                  ia)*qj2_3 + geo(p, 11, ia)*qj1_3 + geo(p, 21, ia)*qj0_1)
               acc(p, 19) = &
                  acc(p, 19) + (cs92*qj2_5 + cs95*geo(p, 13, ia) + geo(p, 5, ia)*qj3_9 + geo(p, 7, &
                  ia)*qj2_6 + geo(p, 14, ia)*qj1_2 + geo(p, 23, ia)*qj0_1)
               acc(p, 20) = &
                  acc(p, 20) + (geo(p, 5, ia)*qj3_10 + 3.0_wp*geo(p, 8, ia)*qj2_6 + 3.0_wp*geo(p, &
                  14, ia)*qj1_3 + geo(p, 24, ia)*qj0_1)
            end do
         end do
      end do

      pd0(:) = acc(1:np, 1)
      pd1(:, 1) = acc(1:np, 2)
      pd1(:, 2) = acc(1:np, 3)
      pd1(:, 3) = acc(1:np, 4)
      pd2(:, 1) = acc(1:np, 5)
      pd2(:, 2) = acc(1:np, 6)
      pd2(:, 4) = acc(1:np, 7)
      pd2(:, 3) = acc(1:np, 8)
      pd2(:, 5) = acc(1:np, 9)
      pd2(:, 6) = acc(1:np, 10)
      pd3(:, 1) = acc(1:np, 11)
      pd3(:, 2) = acc(1:np, 12)
      pd3(:, 5) = acc(1:np, 13)
      pd3(:, 3) = acc(1:np, 14)
      pd3(:, 6) = acc(1:np, 15)
      pd3(:, 8) = acc(1:np, 16)
      pd3(:, 4) = acc(1:np, 17)
      pd3(:, 7) = acc(1:np, 18)
      pd3(:, 9) = acc(1:np, 19)
      pd3(:, 10) = acc(1:np, 20)

   end subroutine cfc_strip_powersums_o3

   pure module subroutine cfc_strip_lift_o3(np, pd0, pd1, pd2, pd3, lsf0, lsf1_r, lsf2_rr, lsf3_rrr)
      !> Live points in the strip, 1..16
      integer, intent(in) :: np
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(in) :: pd0(np)
      !> Order-1 pseudo-density jet of the strip, point-first; second index the Cartesian component
      real(wp), intent(in) :: pd1(np, 3)
      !> Order-2 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-2 tuple
      real(wp), intent(in) :: pd2(np, 6)
      !> Order-3 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-3 tuple
      real(wp), intent(in) :: pd3(np, 10)
      !> Level-set value S = -log(PD)
      real(wp), intent(out) :: lsf0(np)
      !> Spatial gradient dS/dr
      real(wp), intent(out) :: lsf1_r(3, np)
      !> Spatial Hessian, packed (6)
      real(wp), intent(out) :: lsf2_rr(6, np)
      !> Third spatial derivative, packed (10)
      real(wp), intent(out) :: lsf3_rrr(10, np)

      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(3)
      !> Reciprocal pseudo-density per point
      real(wp) :: ipd(nps)
      !> Packed results, point-first
      real(wp) :: o1(nps, 3), o2(nps, 6), o3(nps, 10)
      !> Common subexpressions of one point
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13, cs14
      real(wp) :: cs15, cs16, cs17
      !> Point index
      integer :: p

      if (np < 1 .or. np > nps) error stop &
         "cfc_strip_lift_o3: np outside 1..strip width"

      ! libm log: kept out of the vectorized loops
      do p = 1, np
         lsf0(p) = -log(pd0(p))
      end do

      do p = 1, np
         ipd(p) = 1.0_wp/pd0(p)
      end do

      do p = 1, np
         cs0 = (ipd(p)*ipd(p))
         cs1 = (pd1(p, 1)*pd1(p, 1))
         cs2 = cs0*pd1(p, 1)
         cs3 = (pd1(p, 2)*pd1(p, 2))
         cs4 = pd1(p, 2)*pd1(p, 3)
         cs5 = (pd1(p, 3)*pd1(p, 3))
         cs6 = 2.0_wp*pd1(p, 1)
         cs7 = 2.0_wp*(ipd(p)*ipd(p)*ipd(p))
         cs8 = cs0*pd2(p, 1) - cs1*cs7
         cs9 = cs0*pd2(p, 2)
         cs10 = cs0*pd2(p, 4)
         cs11 = cs0*pd2(p, 3)
         cs12 = cs7*pd1(p, 1)
         cs13 = cs0*pd2(p, 2) - cs12*pd1(p, 2)
         cs14 = cs0*pd2(p, 5)
         cs15 = cs0*pd2(p, 6)
         cs16 = 2.0_wp*pd1(p, 2)
         cs17 = cs0*pd2(p, 3) - cs3*cs7
         o1(p, 1) = -ipd(p)*pd1(p, 1)
         o1(p, 2) = -ipd(p)*pd1(p, 2)
         o1(p, 3) = -ipd(p)*pd1(p, 3)
         o2(p, 1) = cs0*cs1 - ipd(p)*pd2(p, 1)
         o2(p, 2) = cs2*pd1(p, 2) - ipd(p)*pd2(p, 2)
         o2(p, 4) = cs2*pd1(p, 3) - ipd(p)*pd2(p, 4)
         o2(p, 3) = cs0*cs3 - ipd(p)*pd2(p, 3)
         o2(p, 5) = cs0*cs4 - ipd(p)*pd2(p, 5)
         o2(p, 6) = cs0*cs5 - ipd(p)*pd2(p, 6)
         o3(p, 1) = cs0*cs6*pd2(p, 1) + cs8*pd1(p, 1) - ipd(p)*pd3(p, 1)
         o3(p, 2) = cs6*cs9 + cs8*pd1(p, 2) - ipd(p)*pd3(p, 2)
         o3(p, 5) = cs10*cs6 + cs8*pd1(p, 3) - ipd(p)*pd3(p, 5)
         o3(p, 3) = cs11*pd1(p, 1) + cs13*pd1(p, 2) + cs9*pd1(p, 2) - ipd(p)*pd3(p, 3)
         o3(p, 6) = cs10*pd1(p, 2) + cs13*pd1(p, 3) + cs14*pd1(p, 1) - ipd(p)*pd3(p, 6)
         o3(p, 8) = &
            cs10*pd1(p, 3) + cs15*pd1(p, 1) - ipd(p)*pd3(p, 8) + pd1(p, 3)*(cs0*pd2(p, 4) - &
            cs12*pd1(p, 3))
         o3(p, 4) = cs11*cs16 + cs17*pd1(p, 2) - ipd(p)*pd3(p, 4)
         o3(p, 7) = cs14*cs16 + cs17*pd1(p, 3) - ipd(p)*pd3(p, 7)
         o3(p, 9) = &
            cs14*pd1(p, 3) + cs15*pd1(p, 2) - ipd(p)*pd3(p, 9) + pd1(p, 3)*(cs0*pd2(p, 5) - &
            cs4*cs7)
         o3(p, 10) = 2.0_wp*cs15*pd1(p, 3) - ipd(p)*pd3(p, 10) + pd1(p, 3)*(cs0*pd2(p, 6) - cs5*cs7)
      end do

      do p = 1, np
         lsf1_r(1, p) = o1(p, 1)
         lsf1_r(2, p) = o1(p, 2)
         lsf1_r(3, p) = o1(p, 3)
         lsf2_rr(1, p) = o2(p, 1)
         lsf2_rr(2, p) = o2(p, 2)
         lsf2_rr(3, p) = o2(p, 3)
         lsf2_rr(4, p) = o2(p, 4)
         lsf2_rr(5, p) = o2(p, 5)
         lsf2_rr(6, p) = o2(p, 6)
         lsf3_rrr(1, p) = o3(p, 1)
         lsf3_rrr(2, p) = o3(p, 2)
         lsf3_rrr(3, p) = o3(p, 3)
         lsf3_rrr(4, p) = o3(p, 4)
         lsf3_rrr(5, p) = o3(p, 5)
         lsf3_rrr(6, p) = o3(p, 6)
         lsf3_rrr(7, p) = o3(p, 7)
         lsf3_rrr(8, p) = o3(p, 8)
         lsf3_rrr(9, p) = o3(p, 9)
         lsf3_rrr(10, p) = o3(p, 10)
      end do

   end subroutine cfc_strip_lift_o3

   pure module subroutine cfc_strip_powersums_o4(np, points, nat, centers, radii, bound_sq, a1, a2, &
                                          c_par, fade_start, fade_width, pd0, pd1, pd2, pd3, pd4, &
                                          n_zero, geo, sv, reach)
      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(4)
      !> Live points in the strip, 1..8
      integer, intent(in) :: np
      !> Strip points, point-last
      real(wp), intent(in) :: points(3, np)
      !> Atoms in the shared list
      integer, intent(in) :: nat
      !> Atom centers of the shared list
      real(wp), intent(in) :: centers(3, nat)
      !> Atom radii R_a
      real(wp), intent(in) :: radii(nat)
      !> Squared screening reach per atom, the gate's `cand_screen` row
      real(wp), intent(in) :: bound_sq(nat)
      !> Atomic-term exponent a1 (<= 0)
      real(wp), intent(in) :: a1
      !> Pair-term exponent a2 (<= 0)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma_A = ||r - R_A||/R_a - 1; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma_A, finite and > 0
      real(wp), intent(in) :: fade_width
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(out) :: pd0(np)
      !> Order-1 pseudo-density jet of the strip, point-first; second index the Cartesian component
      real(wp), intent(out) :: pd1(np, 3)
      !> Order-2 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-2 tuple
      real(wp), intent(out) :: pd2(np, 6)
      !> Order-3 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-3 tuple
      real(wp), intent(out) :: pd3(np, 10)
      !> Order-4 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-4 tuple
      real(wp), intent(out) :: pd4(np, 15)
      !> Point-atom pairs at zero distance among the evaluated atoms; nonzero means the sums are not
      !> finite
      integer, intent(out) :: n_zero
      !> Point-first geometry cache and pair-pass workspace, one block per list atom (slots in the
      !> routine notes)
      real(wp), intent(out) :: geo(nps, 39, nat)
      !> Survivor workspace: list indices of the atoms kept by the strip classification, leading
      !> entries written
      integer, intent(out) :: sv(nat)
      !> Reach workspace: pair-test radius of each survivor, leading entries written
      real(wp), intent(out) :: reach(nat)

      !> Accumulated columns, one per orbit representative
      integer, parameter :: nacc = 35
      !> Shrink of the strip-level distances in the gate tests (rounding slack)
      real(wp), parameter :: gate_shrink = 1.0_wp - 1e-12_wp
      !> Point-first copy of the strip
      real(wp) :: px(nps), py(nps), pz(nps)
      !> Reduced distance, unfaded factors and squared distance of one atom, point-first
      real(wp) :: gsg(nps), gu(nps), ge(nps), gr2(nps)
      !> Radial jets d^j (w u)/dx^j and d^j (w e)/dx^j of one atom, point-first
      real(wp) :: gju(nps, 0:4), gje(nps, 0:4)
      !> Fade of one atom against the strip, point-first
      real(wp) :: gfs(nps), gds(nps), gfp(nps, 0:4), gsp(nps, 5)
      !> Accumulators
      real(wp) :: acc(nps, nacc)
      !> Strip bounding box
      real(wp) :: lo(3), hi(3)
      !> Atom data, box distances and hoisted constants
      real(wp) :: cx, cy, cz, ra, ira, bsq, ex, ey, ez, e2, snear, sfar
      real(wp) :: lam1, lam2, band_end, inv_delta, irab, rsum
      !> Point geometry, inline-exp scalars and plain-jet scalars
      real(wp) :: dx, dy, dz, r2, x, sg, arg, ekf, er, ep, u, e, hu, he, dsx
      !> Fade scalars
      real(wp) :: sr, fs, ft
      !> Pair body: 1 - q, dq/dr, f(q) derivatives, f jet, f x G_B jet
      real(wp) :: pw, pss1, pss2, pss3, pf0, pf1, pf2, pf3, pf4, dp0_1, dp1_1, dp1_2, dp1_3, dp2_1
      real(wp) :: dp2_2, dp2_4, dp2_3, dp2_5, dp2_6, dp3_1, dp3_2, dp3_5, dp3_3, dp3_6, dp3_8, dp3_4
      real(wp) :: dp3_7, dp3_9, dp3_10, dp4_1, dp4_2, dp4_6, dp4_3, dp4_7, dp4_10, dp4_4, dp4_8
      real(wp) :: dp4_11, dp4_13, dp4_5, dp4_9, dp4_12, dp4_14, dp4_15, qj0_1, qj1_1, qj1_2, qj1_3
