               dsx = gds(p)*ira
               cs0 = gfp(p, 0)*gsp(p, 5)
               gju(p, 0) = cs0*gu(p)
               cs1 = dsx*(5.0_wp*gfp(p, 0)*gsp(p, 4) + gfp(p, 1)*gsp(p, 5))
