               cs14 = 4.0_wp*cs11
               cs15 = &
                  (dsx*dsx*dsx*dsx)*gfs(p)*(20.0_wp*cs10 + 120.0_wp*cs4 + 240.0_wp*cs5 + &
                  120.0_wp*gfp(p, 0) + gfp(p, 4)*gsp(p, 4))
