                  gu(p)*(cs0*(lam2*lam2*lam2*lam2) + cs12*cs7 + cs13*cs2 + cs14*lam2 + cs15)
               gje(p, 0) = cs0*ge(p)
               gje(p, 1) = ge(p)*(cs0*lam1 + cs1)
