            cs120 = cs35*gje(p, 2)
            acc(p, 11) = &
               acc(p, 11) + (-3.0_wp*cs116 + 3.0_wp*cs117 + cs118*cs30 + cs119*cs32 - cs120*cs32)
            cs121 = cs118*cs19
            cs122 = 3.0_wp*cs120
            cs123 = cs122*cs19
            cs124 = 3.0_wp*cs119
            cs125 = cs124*cs19
            cs126 = cs112*geo(p, 2, a)
            cs127 = -cs114 + cs126
            acc(p, 12) = &
               acc(p, 12) + (cs121*geo(p, 2, a) - cs123*geo(p, 2, a) + cs125*geo(p, 2, a) + cs127)
            cs128 = cs112*geo(p, 3, a)
            cs129 = -cs115 + cs128
            acc(p, 13) = &
               acc(p, 13) + (cs121*geo(p, 3, a) - cs123*geo(p, 3, a) + cs125*geo(p, 3, a) + cs129)
            cs130 = cs118*cs26
            cs131 = cs122*cs26
            cs132 = cs124*cs26
            cs133 = -cs116 + cs117
            acc(p, 14) = &
               acc(p, 14) + (cs130*geo(p, 1, a) - cs131*geo(p, 1, a) + cs132*geo(p, 1, a) + cs133)
            cs134 = cs118*geo(p, 3, a)
            cs135 = cs124*cs52
            cs136 = cs122*cs52
            acc(p, 15) = acc(p, 15) + (cs134*cs52 + cs135*geo(p, 3, a) - cs136*geo(p, 3, a))
            cs137 = cs118*cs27
            cs138 = cs122*cs27
            cs139 = cs124*cs27
            acc(p, 16) = &
               acc(p, 16) + (cs133 + cs137*geo(p, 1, a) - cs138*geo(p, 1, a) + cs139*geo(p, 1, a))
            acc(p, 17) = &
               acc(p, 17) + (-3.0_wp*cs114 + cs118*cs58 + cs119*cs59 - cs120*cs59 + 3.0_wp*cs126)
            acc(p, 18) = &
               acc(p, 18) + (cs129 + cs130*geo(p, 3, a) - cs131*geo(p, 3, a) + cs132*geo(p, 3, a))
            acc(p, 19) = &
               acc(p, 19) + (cs127 + cs137*geo(p, 2, a) - cs138*geo(p, 2, a) + cs139*geo(p, 2, a))
            acc(p, 20) = &
               acc(p, 20) + (-3.0_wp*cs115 + cs118*cs60 + cs119*cs61 - cs120*cs61 + 3.0_wp*cs128)
            cs140 = cs35*gje(p, 4)
