            cs142 = cs68*gje(p, 3)
            cs143 = cs70*gje(p, 2)
            cs144 = 3.0_wp*cs112 - 3.0_wp*cs113
            acc(p, 21) = &
               acc(p, 21) + (cs119*cs64 - cs120*cs64 + 6.0_wp*cs121 + cs140*cs62 - cs141*cs65 - &
               cs142*cs62 + cs143*cs65 + cs144)
            cs145 = cs140*cs30
            cs146 = 15.0_wp*cs74
            cs147 = cs118*cs52
            cs148 = cs119*cs77 - cs120*cs77 + 3.0_wp*cs147
            acc(p, 22) = &
               acc(p, 22) + (-cs141*cs146 - cs142*cs74 + cs143*cs146 + cs145*geo(p, 2, a) + cs148)
            cs149 = 15.0_wp*cs80
            cs150 = cs134*geo(p, 1, a)
            cs151 = cs119*cs82 - cs120*cs82 + 3.0_wp*cs150
            acc(p, 23) = &
               acc(p, 23) + (-cs141*cs149 - cs142*cs80 + cs143*cs149 + cs145*geo(p, 3, a) + cs151)
            cs152 = cs140*cs19
            cs153 = 15.0_wp*cs86
            cs154 = -cs113
            cs155 = cs112 + cs121 - cs123 + cs125 + cs154
            cs156 = cs130 - cs131 + cs132
            acc(p, 24) = &
               acc(p, 24) + (-cs141*cs153 - cs142*cs86 + cs143*cs153 + cs152*cs26 + cs155 + cs156)
            cs157 = cs134*geo(p, 2, a)
            cs158 = 15.0_wp*cs91
            acc(p, 25) = &
               acc(p, 25) + (-cs122*cs90 + cs124*cs90 - cs141*cs158 - cs142*cs91 + cs143*cs158 + &
               cs152*cs90 + cs157)
            cs159 = 15.0_wp*cs92
            cs160 = cs137 - cs138 + cs139
            acc(p, 26) = &
