            cs161 = cs140*geo(p, 1, a)
            cs162 = 15.0_wp*cs95
            acc(p, 27) = acc(p, 27) + (-cs141*cs162 - cs142*cs95 + cs143*cs162 + cs148 + cs161*cs58)
            cs163 = 15.0_wp*cs97
            acc(p, 28) = &
