               cs147)
            cs165 = 15.0_wp*cs99
            acc(p, 30) = acc(p, 30) + (-cs141*cs165 - cs142*cs99 + cs143*cs165 + cs151 + cs161*cs60)
            acc(p, 31) = &
               acc(p, 31) + (cs100*cs140 - cs100*cs142 + cs101*cs119 - cs101*cs120 - cs102*cs141 + &
