            cs166 = 15.0_wp*cs103
            cs167 = cs104*cs119 - cs104*cs120 + 3.0_wp*cs157
            acc(p, 32) = &
               acc(p, 32) + (cs103*cs140 - cs103*cs142 - cs141*cs166 + cs143*cs166 + cs167)
            cs168 = 15.0_wp*cs106
            acc(p, 33) = &
               acc(p, 33) + (cs106*cs140 - cs106*cs142 + cs112 - cs141*cs168 + cs143*cs168 + cs154 &
