            cs169 = 15.0_wp*cs107
            acc(p, 34) = &
               acc(p, 34) + (cs107*cs140 - cs107*cs142 - cs141*cs169 + cs143*cs169 + cs167)
            acc(p, 35) = &
               acc(p, 35) + (cs108*cs140 - cs108*cs142 + cs109*cs119 - cs109*cs120 - cs110*cs141 + &
               cs110*cs143 + 6.0_wp*cs137 + cs144)
         end do
      end do

      ! Pair pass over the survivors, list order
      do i = 1, ns
         ia = sv(i)
         cx = centers(1, ia)
         cy = centers(2, ia)
         cz = centers(3, ia)
         ra = radii(ia)
         do j = i + 1, ns
            ib = sv(j)
            ex = centers(1, ib) - cx
            ey = centers(2, ib) - cy
            ez = centers(3, ib) - cz
            rsum = reach(i) + reach(j)
            if (sqrt(ex*ex + ey*ey + ez*ez)*gate_shrink > rsum) cycle
            irab = 1.0_wp/(ra*radii(ib))
            do p = 1, np
               pw = &
                  -irab*(geo(p, 1, ia)*geo(p, 1, ib) + geo(p, 2, ia)*geo(p, 2, ib) + geo(p, 3, &
                  ia)*geo(p, 3, ib)) + 1.0_wp
               pss1 = irab*(geo(p, 1, ia) + geo(p, 1, ib))
               pss2 = irab*(geo(p, 2, ia) + geo(p, 2, ib))
               pss3 = irab*(geo(p, 3, ia) + geo(p, 3, ib))
               pf0 = c_par*(pw*pw*pw*pw)
               pf1 = -4.0_wp*c_par*(pw*pw*pw)
               pf2 = 12.0_wp*c_par*(pw*pw)
               cs170 = 24.0_wp*c_par
               pf3 = -cs170*pw
               pf4 = cs170
               dp0_1 = pf0
               dp1_1 = pf1*pss1
               dp1_2 = pf1*pss2
               dp1_3 = pf1*pss3
               cs171 = 2.0_wp*irab
               cs172 = cs171*pf1
               cs173 = (pss1*pss1)
               dp2_1 = cs172 + cs173*pf2
               cs174 = pf2*pss1
               dp2_2 = cs174*pss2
               dp2_4 = cs174*pss3
               cs175 = (pss2*pss2)
               dp2_3 = cs172 + cs175*pf2
               cs176 = pf2*pss2
               dp2_5 = cs176*pss3
               cs177 = (pss3*pss3)
               dp2_6 = cs172 + cs177*pf2
               cs178 = (pss1*pss1*pss1)
               cs179 = 6.0_wp*irab
               dp3_1 = cs174*cs179 + cs178*pf3
               cs180 = cs171*cs176
               cs181 = cs173*pf3
               dp3_2 = cs180 + cs181*pss2
               cs182 = pf2*pss3
               cs183 = cs171*cs182
               dp3_5 = cs181*pss3 + cs183
               cs184 = cs171*cs174
               cs185 = pf3*pss1
               dp3_3 = cs175*cs185 + cs184
               cs186 = pss2*pss3
               dp3_6 = cs185*cs186
               dp3_8 = cs177*cs185 + cs184
               cs187 = (pss2*pss2*pss2)
               dp3_4 = cs176*cs179 + cs187*pf3
               cs188 = cs175*pf3
               dp3_7 = cs183 + cs188*pss3
               cs189 = cs177*pf3
               dp3_9 = cs180 + cs189*pss2
               cs190 = (pss3*pss3*pss3)
               dp3_10 = cs179*cs182 + cs190*pf3
               cs191 = (irab*irab)*pf2
               cs192 = 12.0_wp*cs191
               cs193 = 12.0_wp*irab
               dp4_1 = cs181*cs193 + cs192 + pf4*(pss1*pss1*pss1*pss1)
               cs194 = cs178*pf4
               cs195 = cs179*cs185
               cs196 = cs195*pss2
               dp4_2 = cs194*pss2 + cs196
               cs197 = cs195*pss3
               dp4_6 = cs194*pss3 + cs197
               cs198 = cs173*pf4
               cs199 = cs171*cs188
               cs200 = 4.0_wp*cs191
               cs201 = cs171*cs181 + cs200
               dp4_3 = cs175*cs198 + cs199 + cs201
               cs202 = cs186*pf3
               dp4_7 = cs171*cs202 + cs186*cs198
               cs203 = cs171*cs189
               dp4_10 = cs177*cs198 + cs201 + cs203
               cs204 = pf4*pss1
               dp4_4 = cs187*cs204 + cs196
               cs205 = cs171*cs185
               dp4_8 = cs175*cs204*pss3 + cs205*pss3
               dp4_11 = cs177*cs204*pss2 + cs205*pss2
               dp4_13 = cs190*cs204 + cs197
               dp4_5 = cs188*cs193 + cs192 + pf4*(pss2*pss2*pss2*pss2)
               cs206 = cs179*cs202
               dp4_9 = cs187*pf4*pss3 + cs206
               dp4_12 = cs175*cs177*pf4 + cs199 + cs200 + cs203
               dp4_14 = cs190*pf4*pss2 + cs206
               dp4_15 = cs189*cs193 + cs192 + pf4*(pss3*pss3*pss3*pss3)
               qj0_1 = dp0_1*geo(p, 5, ib)
               qj1_1 = dp0_1*geo(p, 6, ib) + dp1_1*geo(p, 5, ib)
               qj1_2 = dp0_1*geo(p, 7, ib) + dp1_2*geo(p, 5, ib)
               qj1_3 = dp0_1*geo(p, 8, ib) + dp1_3*geo(p, 5, ib)
               cs207 = 2.0_wp*dp1_1
               qj2_1 = cs207*geo(p, 6, ib) + dp0_1*geo(p, 9, ib) + dp2_1*geo(p, 5, ib)
               qj2_2 = &
                  dp0_1*geo(p, 10, ib) + dp1_1*geo(p, 7, ib) + dp1_2*geo(p, 6, ib) + dp2_2*geo(p, &
                  5, ib)
               qj2_4 = &
                  dp0_1*geo(p, 12, ib) + dp1_1*geo(p, 8, ib) + dp1_3*geo(p, 6, ib) + dp2_4*geo(p, &
                  5, ib)
               cs208 = 2.0_wp*dp1_2
               qj2_3 = cs208*geo(p, 7, ib) + dp0_1*geo(p, 11, ib) + dp2_3*geo(p, 5, ib)
               qj2_5 = &
                  dp0_1*geo(p, 13, ib) + dp1_2*geo(p, 8, ib) + dp1_3*geo(p, 7, ib) + dp2_5*geo(p, &
                  5, ib)
               cs209 = 2.0_wp*dp1_3
               qj2_6 = cs209*geo(p, 8, ib) + dp0_1*geo(p, 14, ib) + dp2_6*geo(p, 5, ib)
               cs210 = 3.0_wp*dp1_1
               cs211 = 3.0_wp*dp2_1
               qj3_1 = &
                  cs210*geo(p, 9, ib) + cs211*geo(p, 6, ib) + dp0_1*geo(p, 15, ib) + dp3_1*geo(p, &
                  5, ib)
               cs212 = 2.0_wp*geo(p, 6, ib)
               qj3_2 = &
                  cs207*geo(p, 10, ib) + cs212*dp2_2 + dp0_1*geo(p, 16, ib) + dp1_2*geo(p, 9, ib) &
                  + dp2_1*geo(p, 7, ib) + dp3_2*geo(p, 5, ib)
               qj3_5 = &
                  cs207*geo(p, 12, ib) + cs212*dp2_4 + dp0_1*geo(p, 19, ib) + dp1_3*geo(p, 9, ib) &
                  + dp2_1*geo(p, 8, ib) + dp3_5*geo(p, 5, ib)
               cs213 = 2.0_wp*geo(p, 7, ib)
               qj3_3 = &
                  cs208*geo(p, 10, ib) + cs213*dp2_2 + dp0_1*geo(p, 17, ib) + dp1_1*geo(p, 11, ib) &
                  + dp2_3*geo(p, 6, ib) + dp3_3*geo(p, 5, ib)
               qj3_6 = &
                  dp0_1*geo(p, 20, ib) + dp1_1*geo(p, 13, ib) + dp1_2*geo(p, 12, ib) + &
