                  + dp2_6*geo(p, 6, ib) + dp3_8*geo(p, 5, ib)
               cs215 = 3.0_wp*dp1_2
               cs216 = 3.0_wp*dp2_3
               qj3_4 = &
                  cs215*geo(p, 11, ib) + cs216*geo(p, 7, ib) + dp0_1*geo(p, 18, ib) + dp3_4*geo(p, &
                  5, ib)
               qj3_7 = &
                  cs208*geo(p, 13, ib) + cs213*dp2_5 + dp0_1*geo(p, 21, ib) + dp1_3*geo(p, 11, ib) &
                  + dp2_3*geo(p, 8, ib) + dp3_7*geo(p, 5, ib)
               qj3_9 = &
                  cs209*geo(p, 13, ib) + cs214*dp2_5 + dp0_1*geo(p, 23, ib) + dp1_2*geo(p, 14, ib) &
                  + dp2_6*geo(p, 7, ib) + dp3_9*geo(p, 5, ib)
               cs217 = 3.0_wp*dp1_3
               cs218 = 3.0_wp*dp2_6
               qj3_10 = &
                  cs217*geo(p, 14, ib) + cs218*geo(p, 8, ib) + dp0_1*geo(p, 24, ib) + &
                  dp3_10*geo(p, 5, ib)
               qj4_1 = &
                  dp0_1*geo(p, 25, ib) + 4.0_wp*dp1_1*geo(p, 15, ib) + 6.0_wp*dp2_1*geo(p, 9, ib) &
                  + 4.0_wp*dp3_1*geo(p, 6, ib) + dp4_1*geo(p, 5, ib)
               cs219 = 3.0_wp*geo(p, 9, ib)
               cs220 = 3.0_wp*geo(p, 6, ib)
               qj4_2 = &
                  cs210*geo(p, 16, ib) + cs211*geo(p, 10, ib) + cs219*dp2_2 + cs220*dp3_2 + &
                  dp0_1*geo(p, 26, ib) + dp1_2*geo(p, 15, ib) + dp3_1*geo(p, 7, ib) + dp4_2*geo(p, &
                  5, ib)
               qj4_6 = &
                  cs210*geo(p, 19, ib) + cs211*geo(p, 12, ib) + cs219*dp2_4 + cs220*dp3_5 + &
                  dp0_1*geo(p, 30, ib) + dp1_3*geo(p, 15, ib) + dp3_1*geo(p, 8, ib) + dp4_6*geo(p, &
                  5, ib)
               qj4_3 = &
                  cs207*geo(p, 17, ib) + cs208*geo(p, 16, ib) + cs212*dp3_3 + cs213*dp3_2 + &
                  dp0_1*geo(p, 27, ib) + dp2_1*geo(p, 11, ib) + 4.0_wp*dp2_2*geo(p, 10, ib) + &
                  dp2_3*geo(p, 9, ib) + dp4_3*geo(p, 5, ib)
               cs221 = 2.0_wp*dp2_2
               cs222 = 2.0_wp*geo(p, 10, ib)
               qj4_7 = &
                  cs207*geo(p, 20, ib) + cs212*dp3_6 + cs221*geo(p, 12, ib) + cs222*dp2_4 + &
                  dp0_1*geo(p, 31, ib) + dp1_2*geo(p, 19, ib) + dp1_3*geo(p, 16, ib) + &
                  dp2_1*geo(p, 13, ib) + dp2_5*geo(p, 9, ib) + dp3_2*geo(p, 8, ib) + dp3_5*geo(p, &
                  7, ib) + dp4_7*geo(p, 5, ib)
               qj4_10 = &
                  cs207*geo(p, 22, ib) + cs209*geo(p, 19, ib) + cs212*dp3_8 + cs214*dp3_5 + &
                  dp0_1*geo(p, 34, ib) + dp2_1*geo(p, 14, ib) + 4.0_wp*dp2_4*geo(p, 12, ib) + &
                  dp2_6*geo(p, 9, ib) + dp4_10*geo(p, 5, ib)
               cs223 = 3.0_wp*geo(p, 11, ib)
               cs224 = 3.0_wp*geo(p, 7, ib)
               qj4_4 = &
                  cs215*geo(p, 17, ib) + cs216*geo(p, 10, ib) + cs223*dp2_2 + cs224*dp3_3 + &
                  dp0_1*geo(p, 28, ib) + dp1_1*geo(p, 18, ib) + dp3_4*geo(p, 6, ib) + dp4_4*geo(p, &
                  5, ib)
               qj4_8 = &
                  cs208*geo(p, 20, ib) + cs213*dp3_6 + cs221*geo(p, 13, ib) + cs222*dp2_5 + &
                  dp0_1*geo(p, 32, ib) + dp1_1*geo(p, 21, ib) + dp1_3*geo(p, 17, ib) + &
                  dp2_3*geo(p, 12, ib) + dp2_4*geo(p, 11, ib) + dp3_3*geo(p, 8, ib) + dp3_7*geo(p, &
                  6, ib) + dp4_8*geo(p, 5, ib)
               qj4_11 = &
                  cs209*geo(p, 20, ib) + cs214*dp3_6 + dp0_1*geo(p, 35, ib) + dp1_1*geo(p, 23, ib) &
                  + dp1_2*geo(p, 22, ib) + dp2_2*geo(p, 14, ib) + 2.0_wp*dp2_4*geo(p, 13, ib) + &
                  2.0_wp*dp2_5*geo(p, 12, ib) + dp2_6*geo(p, 10, ib) + dp3_8*geo(p, 7, ib) + &
                  dp3_9*geo(p, 6, ib) + dp4_11*geo(p, 5, ib)
               cs225 = 3.0_wp*geo(p, 14, ib)
               cs226 = 3.0_wp*geo(p, 8, ib)
               qj4_13 = &
                  cs217*geo(p, 22, ib) + cs218*geo(p, 12, ib) + cs225*dp2_4 + cs226*dp3_8 + &
                  dp0_1*geo(p, 37, ib) + dp1_1*geo(p, 24, ib) + dp3_10*geo(p, 6, ib) + &
                  dp4_13*geo(p, 5, ib)
               qj4_5 = &
                  dp0_1*geo(p, 29, ib) + 4.0_wp*dp1_2*geo(p, 18, ib) + 6.0_wp*dp2_3*geo(p, 11, ib) &
                  + 4.0_wp*dp3_4*geo(p, 7, ib) + dp4_5*geo(p, 5, ib)
               qj4_9 = &
                  cs215*geo(p, 21, ib) + cs216*geo(p, 13, ib) + cs223*dp2_5 + cs224*dp3_7 + &
                  dp0_1*geo(p, 33, ib) + dp1_3*geo(p, 18, ib) + dp3_4*geo(p, 8, ib) + dp4_9*geo(p, &
                  5, ib)
               qj4_12 = &
                  cs208*geo(p, 23, ib) + cs209*geo(p, 21, ib) + cs213*dp3_9 + cs214*dp3_7 + &
                  dp0_1*geo(p, 36, ib) + dp2_3*geo(p, 14, ib) + 4.0_wp*dp2_5*geo(p, 13, ib) + &
                  dp2_6*geo(p, 11, ib) + dp4_12*geo(p, 5, ib)
               qj4_14 = &
                  cs217*geo(p, 23, ib) + cs218*geo(p, 13, ib) + cs225*dp2_5 + cs226*dp3_9 + &
                  dp0_1*geo(p, 38, ib) + dp1_2*geo(p, 24, ib) + dp3_10*geo(p, 7, ib) + &
                  dp4_14*geo(p, 5, ib)
               qj4_15 = &
                  dp0_1*geo(p, 39, ib) + 4.0_wp*dp1_3*geo(p, 24, ib) + 6.0_wp*dp2_6*geo(p, 14, ib) &
                  + 4.0_wp*dp3_10*geo(p, 8, ib) + dp4_15*geo(p, 5, ib)
               acc(p, 1) = acc(p, 1) + (geo(p, 5, ia)*qj0_1)
               acc(p, 2) = acc(p, 2) + (geo(p, 5, ia)*qj1_1 + geo(p, 6, ia)*qj0_1)
               acc(p, 3) = acc(p, 3) + (geo(p, 5, ia)*qj1_2 + geo(p, 7, ia)*qj0_1)
               acc(p, 4) = acc(p, 4) + (geo(p, 5, ia)*qj1_3 + geo(p, 8, ia)*qj0_1)
               cs227 = 2.0_wp*geo(p, 6, ia)
               acc(p, 5) = acc(p, 5) + (cs227*qj1_1 + geo(p, 5, ia)*qj2_1 + geo(p, 9, ia)*qj0_1)
               acc(p, 6) = &
                  acc(p, 6) + (geo(p, 5, ia)*qj2_2 + geo(p, 6, ia)*qj1_2 + geo(p, 7, ia)*qj1_1 + &
                  geo(p, 10, ia)*qj0_1)
               acc(p, 7) = &
                  acc(p, 7) + (geo(p, 5, ia)*qj2_4 + geo(p, 6, ia)*qj1_3 + geo(p, 8, ia)*qj1_1 + &
                  geo(p, 12, ia)*qj0_1)
               cs228 = 2.0_wp*geo(p, 7, ia)
               acc(p, 8) = acc(p, 8) + (cs228*qj1_2 + geo(p, 5, ia)*qj2_3 + geo(p, 11, ia)*qj0_1)
               acc(p, 9) = &
                  acc(p, 9) + (geo(p, 5, ia)*qj2_5 + geo(p, 7, ia)*qj1_3 + geo(p, 8, ia)*qj1_2 + &
                  geo(p, 13, ia)*qj0_1)
               cs229 = 2.0_wp*geo(p, 8, ia)
               acc(p, 10) = acc(p, 10) + (cs229*qj1_3 + geo(p, 5, ia)*qj2_6 + geo(p, 14, ia)*qj0_1)
               cs230 = 3.0_wp*geo(p, 6, ia)
               cs231 = 3.0_wp*geo(p, 9, ia)
               acc(p, 11) = &
                  acc(p, 11) + (cs230*qj2_1 + cs231*qj1_1 + geo(p, 5, ia)*qj3_1 + geo(p, 15, &
                  ia)*qj0_1)
               cs232 = 2.0_wp*qj1_1
               acc(p, 12) = &
                  acc(p, 12) + (cs227*qj2_2 + cs232*geo(p, 10, ia) + geo(p, 5, ia)*qj3_2 + geo(p, &
                  7, ia)*qj2_1 + geo(p, 9, ia)*qj1_2 + geo(p, 16, ia)*qj0_1)
               acc(p, 13) = &
                  acc(p, 13) + (cs227*qj2_4 + cs232*geo(p, 12, ia) + geo(p, 5, ia)*qj3_5 + geo(p, &
                  8, ia)*qj2_1 + geo(p, 9, ia)*qj1_3 + geo(p, 19, ia)*qj0_1)
               cs233 = 2.0_wp*qj1_2
               acc(p, 14) = &
                  acc(p, 14) + (cs228*qj2_2 + cs233*geo(p, 10, ia) + geo(p, 5, ia)*qj3_3 + geo(p, &
                  6, ia)*qj2_3 + geo(p, 11, ia)*qj1_1 + geo(p, 17, ia)*qj0_1)
               acc(p, 15) = &
                  acc(p, 15) + (geo(p, 5, ia)*qj3_6 + geo(p, 6, ia)*qj2_5 + geo(p, 7, ia)*qj2_4 + &
                  geo(p, 8, ia)*qj2_2 + geo(p, 10, ia)*qj1_3 + geo(p, 12, ia)*qj1_2 + geo(p, 13, &
                  ia)*qj1_1 + geo(p, 20, ia)*qj0_1)
               cs234 = 2.0_wp*qj1_3
               acc(p, 16) = &
                  acc(p, 16) + (cs229*qj2_4 + cs234*geo(p, 12, ia) + geo(p, 5, ia)*qj3_8 + geo(p, &
                  6, ia)*qj2_6 + geo(p, 14, ia)*qj1_1 + geo(p, 22, ia)*qj0_1)
               cs235 = 3.0_wp*geo(p, 7, ia)
               cs236 = 3.0_wp*geo(p, 11, ia)
               acc(p, 17) = &
                  acc(p, 17) + (cs235*qj2_3 + cs236*qj1_2 + geo(p, 5, ia)*qj3_4 + geo(p, 18, &
                  ia)*qj0_1)
               acc(p, 18) = &
                  acc(p, 18) + (cs228*qj2_5 + cs233*geo(p, 13, ia) + geo(p, 5, ia)*qj3_7 + geo(p, &
                  8, ia)*qj2_3 + geo(p, 11, ia)*qj1_3 + geo(p, 21, ia)*qj0_1)
               acc(p, 19) = &
                  acc(p, 19) + (cs229*qj2_5 + cs234*geo(p, 13, ia) + geo(p, 5, ia)*qj3_9 + geo(p, &
                  7, ia)*qj2_6 + geo(p, 14, ia)*qj1_2 + geo(p, 23, ia)*qj0_1)
               cs237 = 3.0_wp*geo(p, 8, ia)
               cs238 = 3.0_wp*geo(p, 14, ia)
               acc(p, 20) = &
                  acc(p, 20) + (cs237*qj2_6 + cs238*qj1_3 + geo(p, 5, ia)*qj3_10 + geo(p, 24, &
                  ia)*qj0_1)
               acc(p, 21) = &
                  acc(p, 21) + (geo(p, 5, ia)*qj4_1 + 4.0_wp*geo(p, 6, ia)*qj3_1 + 6.0_wp*geo(p, &
                  9, ia)*qj2_1 + 4.0_wp*geo(p, 15, ia)*qj1_1 + geo(p, 25, ia)*qj0_1)
               cs239 = 3.0_wp*qj2_1
               cs240 = 3.0_wp*qj1_1
               acc(p, 22) = &
                  acc(p, 22) + (cs230*qj3_2 + cs231*qj2_2 + cs239*geo(p, 10, ia) + cs240*geo(p, &
                  16, ia) + geo(p, 5, ia)*qj4_2 + geo(p, 7, ia)*qj3_1 + geo(p, 15, ia)*qj1_2 + &
                  geo(p, 26, ia)*qj0_1)
               acc(p, 23) = &
                  acc(p, 23) + (cs230*qj3_5 + cs231*qj2_4 + cs239*geo(p, 12, ia) + cs240*geo(p, &
                  19, ia) + geo(p, 5, ia)*qj4_6 + geo(p, 8, ia)*qj3_1 + geo(p, 15, ia)*qj1_3 + &
                  geo(p, 30, ia)*qj0_1)
               acc(p, 24) = &
                  acc(p, 24) + (cs227*qj3_3 + cs228*qj3_2 + cs232*geo(p, 17, ia) + cs233*geo(p, &
                  16, ia) + geo(p, 5, ia)*qj4_3 + geo(p, 9, ia)*qj2_3 + 4.0_wp*geo(p, 10, &
                  ia)*qj2_2 + geo(p, 11, ia)*qj2_1 + geo(p, 27, ia)*qj0_1)
               cs241 = 2.0_wp*geo(p, 10, ia)
               cs242 = 2.0_wp*qj2_2
               acc(p, 25) = &
                  acc(p, 25) + (cs227*qj3_6 + cs232*geo(p, 20, ia) + cs241*qj2_4 + cs242*geo(p, &
                  12, ia) + geo(p, 5, ia)*qj4_7 + geo(p, 7, ia)*qj3_5 + geo(p, 8, ia)*qj3_2 + &
                  geo(p, 9, ia)*qj2_5 + geo(p, 13, ia)*qj2_1 + geo(p, 16, ia)*qj1_3 + geo(p, 19, &
                  ia)*qj1_2 + geo(p, 31, ia)*qj0_1)
               acc(p, 26) = &
                  acc(p, 26) + (cs227*qj3_8 + cs229*qj3_5 + cs232*geo(p, 22, ia) + cs234*geo(p, &
                  19, ia) + geo(p, 5, ia)*qj4_10 + geo(p, 9, ia)*qj2_6 + 4.0_wp*geo(p, 12, &
                  ia)*qj2_4 + geo(p, 14, ia)*qj2_1 + geo(p, 34, ia)*qj0_1)
               cs243 = 3.0_wp*qj2_3
               cs244 = 3.0_wp*qj1_2
               acc(p, 27) = &
                  acc(p, 27) + (cs235*qj3_3 + cs236*qj2_2 + cs243*geo(p, 10, ia) + cs244*geo(p, &
                  17, ia) + geo(p, 5, ia)*qj4_4 + geo(p, 6, ia)*qj3_4 + geo(p, 18, ia)*qj1_1 + &
                  geo(p, 28, ia)*qj0_1)
               acc(p, 28) = &
                  acc(p, 28) + (cs228*qj3_6 + cs233*geo(p, 20, ia) + cs241*qj2_5 + cs242*geo(p, &
                  13, ia) + geo(p, 5, ia)*qj4_8 + geo(p, 6, ia)*qj3_7 + geo(p, 8, ia)*qj3_3 + &
                  geo(p, 11, ia)*qj2_4 + geo(p, 12, ia)*qj2_3 + geo(p, 17, ia)*qj1_3 + geo(p, 21, &
                  ia)*qj1_1 + geo(p, 32, ia)*qj0_1)
               acc(p, 29) = &
                  acc(p, 29) + (cs229*qj3_6 + cs234*geo(p, 20, ia) + geo(p, 5, ia)*qj4_11 + geo(p, &
                  6, ia)*qj3_9 + geo(p, 7, ia)*qj3_8 + geo(p, 10, ia)*qj2_6 + 2.0_wp*geo(p, 12, &
                  ia)*qj2_5 + 2.0_wp*geo(p, 13, ia)*qj2_4 + geo(p, 14, ia)*qj2_2 + geo(p, 22, &
                  ia)*qj1_2 + geo(p, 23, ia)*qj1_1 + geo(p, 35, ia)*qj0_1)
               cs245 = 3.0_wp*qj2_6
               cs246 = 3.0_wp*qj1_3
               acc(p, 30) = &
                  acc(p, 30) + (cs237*qj3_8 + cs238*qj2_4 + cs245*geo(p, 12, ia) + cs246*geo(p, &
                  22, ia) + geo(p, 5, ia)*qj4_13 + geo(p, 6, ia)*qj3_10 + geo(p, 24, ia)*qj1_1 + &
                  geo(p, 37, ia)*qj0_1)
               acc(p, 31) = &
                  acc(p, 31) + (geo(p, 5, ia)*qj4_5 + 4.0_wp*geo(p, 7, ia)*qj3_4 + 6.0_wp*geo(p, &
                  11, ia)*qj2_3 + 4.0_wp*geo(p, 18, ia)*qj1_2 + geo(p, 29, ia)*qj0_1)
               acc(p, 32) = &
                  acc(p, 32) + (cs235*qj3_7 + cs236*qj2_5 + cs243*geo(p, 13, ia) + cs244*geo(p, &
                  21, ia) + geo(p, 5, ia)*qj4_9 + geo(p, 8, ia)*qj3_4 + geo(p, 18, ia)*qj1_3 + &
                  geo(p, 33, ia)*qj0_1)
               acc(p, 33) = &
                  acc(p, 33) + (cs228*qj3_9 + cs229*qj3_7 + cs233*geo(p, 23, ia) + cs234*geo(p, &
                  21, ia) + geo(p, 5, ia)*qj4_12 + geo(p, 11, ia)*qj2_6 + 4.0_wp*geo(p, 13, &
                  ia)*qj2_5 + geo(p, 14, ia)*qj2_3 + geo(p, 36, ia)*qj0_1)
               acc(p, 34) = &
                  acc(p, 34) + (cs237*qj3_9 + cs238*qj2_5 + cs245*geo(p, 13, ia) + cs246*geo(p, &
                  23, ia) + geo(p, 5, ia)*qj4_14 + geo(p, 7, ia)*qj3_10 + geo(p, 24, ia)*qj1_2 + &
                  geo(p, 38, ia)*qj0_1)
               acc(p, 35) = &
                  acc(p, 35) + (geo(p, 5, ia)*qj4_15 + 4.0_wp*geo(p, 8, ia)*qj3_10 + 6.0_wp*geo(p, &
                  14, ia)*qj2_6 + 4.0_wp*geo(p, 24, ia)*qj1_3 + geo(p, 39, ia)*qj0_1)
            end do
         end do
      end do

      pd0(:) = acc(1:np, 1)
      pd1(:, 1) = acc(1:np, 2)
      pd1(:, 2) = acc(1:np, 3)
      pd1(:, 3) = acc(1:np, 4)
      pd2(:, 1) = acc(1:np, 5)
      pd2(:, 2) = acc(1:np, 6)
      pd2(:, 4) = acc(1:np, 7)
      pd2(:, 3) = acc(1:np, 8)
      pd2(:, 5) = acc(1:np, 9)
      pd2(:, 6) = acc(1:np, 10)
      pd3(:, 1) = acc(1:np, 11)
      pd3(:, 2) = acc(1:np, 12)
      pd3(:, 5) = acc(1:np, 13)
      pd3(:, 3) = acc(1:np, 14)
      pd3(:, 6) = acc(1:np, 15)
      pd3(:, 8) = acc(1:np, 16)
      pd3(:, 4) = acc(1:np, 17)
      pd3(:, 7) = acc(1:np, 18)
      pd3(:, 9) = acc(1:np, 19)
      pd3(:, 10) = acc(1:np, 20)
      pd4(:, 1) = acc(1:np, 21)
      pd4(:, 2) = acc(1:np, 22)
      pd4(:, 6) = acc(1:np, 23)
      pd4(:, 3) = acc(1:np, 24)
      pd4(:, 7) = acc(1:np, 25)
      pd4(:, 10) = acc(1:np, 26)
      pd4(:, 4) = acc(1:np, 27)
      pd4(:, 8) = acc(1:np, 28)
      pd4(:, 11) = acc(1:np, 29)
      pd4(:, 13) = acc(1:np, 30)
      pd4(:, 5) = acc(1:np, 31)
      pd4(:, 9) = acc(1:np, 32)
      pd4(:, 12) = acc(1:np, 33)
      pd4(:, 14) = acc(1:np, 34)
      pd4(:, 15) = acc(1:np, 35)

   end subroutine cfc_strip_powersums_o4

   pure module subroutine cfc_strip_lift_o4(np, pd0, pd1, pd2, pd3, pd4, lsf0, lsf1_r, lsf2_rr, &
                                     lsf3_rrr, lsf4_rrrr)
      !> Live points in the strip, 1..8
      integer, intent(in) :: np
      !> Order-0 pseudo-density jet of the strip, point-first
      real(wp), intent(in) :: pd0(np)
      !> Order-1 pseudo-density jet of the strip, point-first; second index the Cartesian component
      real(wp), intent(in) :: pd1(np, 3)
      !> Order-2 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-2 tuple
      real(wp), intent(in) :: pd2(np, 6)
      !> Order-3 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-3 tuple
      real(wp), intent(in) :: pd3(np, 10)
      !> Order-4 pseudo-density jet of the strip, point-first; second index the packed slot of the
      !> sorted rank-4 tuple
      real(wp), intent(in) :: pd4(np, 15)
      !> Level-set value S = -log(PD)
      real(wp), intent(out) :: lsf0(np)
      !> Spatial gradient dS/dr
      real(wp), intent(out) :: lsf1_r(3, np)
      !> Spatial Hessian, packed (6)
      real(wp), intent(out) :: lsf2_rr(6, np)
      !> Third spatial derivative, packed (10)
      real(wp), intent(out) :: lsf3_rrr(10, np)
      !> Fourth spatial derivative, packed (15)
      real(wp), intent(out) :: lsf4_rrrr(15, np)

      !> Strip width of this order
      integer, parameter :: nps = cfc_strip_width(4)
      !> Reciprocal pseudo-density per point
      real(wp) :: ipd(nps)
      !> Packed results, point-first
      real(wp) :: o1(nps, 3), o2(nps, 6), o3(nps, 10), o4(nps, 15)
      !> Common subexpressions of one point
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13, cs14
      real(wp) :: cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26, cs27, cs28
      real(wp) :: cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39, cs40, cs41, cs42
      real(wp) :: cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52, cs53, cs54, cs55, cs56
      real(wp) :: cs57, cs58, cs59, cs60
      !> Point index
      integer :: p

      if (np < 1 .or. np > nps) error stop &
         "cfc_strip_lift_o4: np outside 1..strip width"

      ! libm log: kept out of the vectorized loops
      do p = 1, np
         lsf0(p) = -log(pd0(p))
      end do

      do p = 1, np
         ipd(p) = 1.0_wp/pd0(p)
      end do

      do p = 1, np
         cs0 = (ipd(p)*ipd(p))
         cs1 = (pd1(p, 1)*pd1(p, 1))
         cs2 = cs0*pd1(p, 1)
         cs3 = (pd1(p, 2)*pd1(p, 2))
         cs4 = pd1(p, 2)*pd1(p, 3)
         cs5 = (pd1(p, 3)*pd1(p, 3))
         cs6 = 2.0_wp*pd1(p, 1)
         cs7 = (ipd(p)*ipd(p)*ipd(p))
         cs8 = 2.0_wp*cs7
         cs9 = cs0*pd2(p, 1) - cs1*cs8
         cs10 = cs0*pd2(p, 2)
         cs11 = cs0*pd2(p, 4)
         cs12 = cs0*pd2(p, 3)
         cs13 = cs8*pd1(p, 1)
         cs14 = cs0*pd2(p, 2) - cs13*pd1(p, 2)
         cs15 = cs0*pd2(p, 5)
         cs16 = cs0*pd2(p, 6)
         cs17 = cs0*pd2(p, 4) - cs13*pd1(p, 3)
         cs18 = 2.0_wp*pd1(p, 2)
         cs19 = cs0*pd2(p, 3) - cs3*cs8
         cs20 = cs0*pd2(p, 5) - cs4*cs8
         cs21 = 2.0_wp*pd1(p, 3)
         cs22 = cs0*pd2(p, 6) - cs5*cs8
         cs23 = cs0*pd3(p, 1)
         cs24 = 3.0_wp*pd1(p, 1)
         cs25 = 6.0_wp*cs1
         cs26 = 3.0_wp*cs0*pd2(p, 1) - cs25*cs7
         cs27 = 4.0_wp*cs7
         cs28 = cs27*pd1(p, 1)
         cs29 = (ipd(p)*ipd(p)*ipd(p)*ipd(p))
         cs30 = cs25*cs29 - cs8*pd2(p, 1)
         cs31 = cs23 - cs28*pd2(p, 1) + cs30*pd1(p, 1)
         cs32 = cs0*pd3(p, 2)
         cs33 = cs0*pd3(p, 5)
         cs34 = cs0*pd3(p, 3)
         cs35 = 2.0_wp*cs0*pd2(p, 2) - cs28*pd1(p, 2)
         cs36 = -cs28*pd2(p, 2) + cs30*pd1(p, 2) + cs32
         cs37 = cs0*pd3(p, 6)
         cs38 = cs0*pd3(p, 8)
         cs39 = 2.0_wp*cs0*pd2(p, 4) - cs28*pd1(p, 3)
         cs40 = cs0*pd3(p, 4)
         cs41 = cs8*pd2(p, 3)
         cs42 = cs8*pd2(p, 2)
         cs43 = 6.0_wp*cs29
         cs44 = cs43*pd1(p, 1)
         cs45 = -cs42 + cs44*pd1(p, 2)
         cs46 = cs0*pd3(p, 3) - cs41*pd1(p, 1) - cs42*pd1(p, 2) + cs45*pd1(p, 2)
         cs47 = cs0*pd3(p, 7)
         cs48 = cs0*pd3(p, 9)
         cs49 = cs8*pd2(p, 5)
         cs50 = cs8*pd2(p, 4)
         cs51 = cs0*pd3(p, 10)
         cs52 = cs8*pd2(p, 6)
         cs53 = 3.0_wp*pd1(p, 2)
         cs54 = 6.0_wp*cs3
         cs55 = 3.0_wp*cs0*pd2(p, 3) - cs54*cs7
         cs56 = cs27*pd1(p, 2)
         cs57 = cs29*cs54 - cs41
         cs58 = cs40 - cs56*pd2(p, 3) + cs57*pd1(p, 2)
         cs59 = 2.0_wp*cs0*pd2(p, 5) - cs27*cs4
         cs60 = 6.0_wp*cs5
         o1(p, 1) = -ipd(p)*pd1(p, 1)
         o1(p, 2) = -ipd(p)*pd1(p, 2)
         o1(p, 3) = -ipd(p)*pd1(p, 3)
         o2(p, 1) = cs0*cs1 - ipd(p)*pd2(p, 1)
         o2(p, 2) = cs2*pd1(p, 2) - ipd(p)*pd2(p, 2)
         o2(p, 4) = cs2*pd1(p, 3) - ipd(p)*pd2(p, 4)
         o2(p, 3) = cs0*cs3 - ipd(p)*pd2(p, 3)
         o2(p, 5) = cs0*cs4 - ipd(p)*pd2(p, 5)
         o2(p, 6) = cs0*cs5 - ipd(p)*pd2(p, 6)
         o3(p, 1) = cs0*cs6*pd2(p, 1) + cs9*pd1(p, 1) - ipd(p)*pd3(p, 1)
         o3(p, 2) = 2.0_wp*cs10*pd1(p, 1) + cs9*pd1(p, 2) - ipd(p)*pd3(p, 2)
         o3(p, 5) = 2.0_wp*cs11*pd1(p, 1) + cs9*pd1(p, 3) - ipd(p)*pd3(p, 5)
         o3(p, 3) = cs10*pd1(p, 2) + cs12*pd1(p, 1) + cs14*pd1(p, 2) - ipd(p)*pd3(p, 3)
         o3(p, 6) = cs11*pd1(p, 2) + cs14*pd1(p, 3) + cs15*pd1(p, 1) - ipd(p)*pd3(p, 6)
         o3(p, 8) = cs11*pd1(p, 3) + cs16*pd1(p, 1) + cs17*pd1(p, 3) - ipd(p)*pd3(p, 8)
         o3(p, 4) = cs12*cs18 + cs19*pd1(p, 2) - ipd(p)*pd3(p, 4)
         o3(p, 7) = 2.0_wp*cs15*pd1(p, 2) + cs19*pd1(p, 3) - ipd(p)*pd3(p, 7)
         o3(p, 9) = cs15*pd1(p, 3) + cs16*pd1(p, 2) + cs20*pd1(p, 3) - ipd(p)*pd3(p, 9)
         o3(p, 10) = cs16*cs21 + cs22*pd1(p, 3) - ipd(p)*pd3(p, 10)
         o4(p, 1) = cs23*cs24 + cs26*pd2(p, 1) + cs31*pd1(p, 1) - ipd(p)*pd4(p, 1)
         o4(p, 2) = cs24*cs32 + cs26*pd2(p, 2) + cs31*pd1(p, 2) - ipd(p)*pd4(p, 2)
         o4(p, 6) = cs24*cs33 + cs26*pd2(p, 4) + cs31*pd1(p, 3) - ipd(p)*pd4(p, 6)
         o4(p, 3) = &
            cs32*pd1(p, 2) + cs34*cs6 + cs35*pd2(p, 2) + cs36*pd1(p, 2) + cs9*pd2(p, 3) - &
            ipd(p)*pd4(p, 3)
         o4(p, 7) = &
            cs33*pd1(p, 2) + cs35*pd2(p, 4) + cs36*pd1(p, 3) + cs37*cs6 + cs9*pd2(p, 5) - &
            ipd(p)*pd4(p, 7)
         o4(p, 10) = &
            cs33*pd1(p, 3) + cs38*cs6 + cs39*pd2(p, 4) + cs9*pd2(p, 6) - ipd(p)*pd4(p, 10) + &
            pd1(p, 3)*(-cs28*pd2(p, 4) + cs30*pd1(p, 3) + cs33)
         o4(p, 4) = &
            cs18*cs34 + cs19*pd2(p, 2) + cs35*pd2(p, 3) + cs40*pd1(p, 1) + cs46*pd1(p, 2) - &
            ipd(p)*pd4(p, 4)
         o4(p, 8) = &
            cs18*cs37 + cs19*pd2(p, 4) + cs35*pd2(p, 5) + cs46*pd1(p, 3) + cs47*pd1(p, 1) - &
            ipd(p)*pd4(p, 8)
         o4(p, 11) = &
            cs14*pd2(p, 6) + cs17*pd2(p, 5) + cs20*pd2(p, 4) + cs37*pd1(p, 3) + cs38*pd1(p, 2) + &
            cs48*pd1(p, 1) - ipd(p)*pd4(p, 11) + pd1(p, 3)*(cs0*pd3(p, 6) + cs45*pd1(p, 3) - &
            cs49*pd1(p, 1) - cs50*pd1(p, 2))
         o4(p, 13) = &
            cs21*cs38 + cs22*pd2(p, 4) + cs39*pd2(p, 6) + cs51*pd1(p, 1) - ipd(p)*pd4(p, 13) + &
            pd1(p, 3)*(cs0*pd3(p, 8) - cs50*pd1(p, 3) - cs52*pd1(p, 1) + pd1(p, 3)*(cs44*pd1(p, 3) &
            - cs50))
         o4(p, 5) = cs40*cs53 + cs55*pd2(p, 3) + cs58*pd1(p, 2) - ipd(p)*pd4(p, 5)
         o4(p, 9) = cs47*cs53 + cs55*pd2(p, 5) + cs58*pd1(p, 3) - ipd(p)*pd4(p, 9)
         o4(p, 12) = &
            cs18*cs48 + cs19*pd2(p, 6) + cs47*pd1(p, 3) + cs59*pd2(p, 5) - ipd(p)*pd4(p, 12) + &
            pd1(p, 3)*(cs47 - cs56*pd2(p, 5) + cs57*pd1(p, 3))
         o4(p, 14) = &
            cs21*cs48 + cs22*pd2(p, 5) + cs51*pd1(p, 2) + cs59*pd2(p, 6) - ipd(p)*pd4(p, 14) + &
            pd1(p, 3)*(cs0*pd3(p, 9) - cs49*pd1(p, 3) - cs52*pd1(p, 2) + pd1(p, 3)*(cs4*cs43 - &
            cs49))
         o4(p, 15) = &
            3.0_wp*cs51*pd1(p, 3) - ipd(p)*pd4(p, 15) + pd1(p, 3)*(-cs27*pd1(p, 3)*pd2(p, 6) + &
            cs51 + pd1(p, 3)*(cs29*cs60 - cs52)) + pd2(p, 6)*(3.0_wp*cs0*pd2(p, 6) - cs60*cs7)
      end do

      do p = 1, np
         lsf1_r(1, p) = o1(p, 1)
         lsf1_r(2, p) = o1(p, 2)
         lsf1_r(3, p) = o1(p, 3)
